INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6a7a0a-cb70-4294-96f1-a58b63457bec', '柳枝辭九首 八', '柳枝辞九首 八', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["王孫宴罷曲江池，折取春光伴醉歸。","怪得美人爭鬬乞，要他穠翠染羅衣。"]', '["王孫宴罷曲江池，折取春光伴醉归。","怪得美人爭鬬乞，要他穠翠染羅衣。"]', '诗', 'shi', '', NULL, '柳枝辭九首 八 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a046a9-c67f-485c-9116-18784a13ab58', '柳枝辭九首 九', '柳枝辞九首 九', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["殘照林梢嫋數枝，能折醉客上金堤。","馬嬌如練纓如火，瑟瑟陰中步步嘶。"]', '["殘照林梢嫋數枝，能折醉客上金堤。","马嬌如練纓如火，瑟瑟陰中步步嘶。"]', '诗', 'shi', '', NULL, '柳枝辭九首 九 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7969678-cc76-4951-8731-5c358195e3fc', '句', '句', 'a4a29e2c-10fc-461c-aa65-efe03e2d869c', '唐', '["莎草放茵深護砌，海榴噴火巧橫牆。","紋鱗引子跳銀海，紫燕呼雛語畫梁。"]', '["莎草放茵深護砌，海榴噴火巧橫牆。","紋鱗引子跳銀海，紫燕呼雛語畫梁。"]', '诗', 'shi', '', NULL, '句 成彥雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37afad39-b55f-4f65-b73a-1f8b20f9e0ca', '寄禪月大師', '寄禪月大師', '4d2cb837-38e5-4428-9d38-e7dbf0e14c00', '唐', '["昨日塵遊到幾家，就中偏省近宣麻。","水田鋪座時移畫，金地譚空說盡沙。","傍竹欲添犀浦石，栽松更碾味江茶。","有時捻得休公卷，倚柱閑吟見落霞。"]', '["昨日塵游到幾家，就中偏省近宣麻。","水田鋪座时移畫，金地譚空说尽沙。","傍竹欲添犀浦石，栽松更碾味江茶。","有时捻得休公卷，倚柱闲吟见落霞。"]', '诗', 'shi', '', NULL, '寄禪月大師 周庠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f289049e-cc32-4ff4-b79f-9912fe77226e', '寄禪月大師', '寄禪月大師', 'f3e2faf5-0f25-4bef-b6e6-716598d254b4', '唐', '["龍華咫尺斷來音，日夕空馳詠德心。","禪月字清師號別，壽春詩古帝恩深。","畫成羅漢驚三界，書似張顛直萬金。","莫倚名高忘故舊，曉晴閑步一相尋。"]', '["龙华咫尺斷来音，日夕空驰詠德心。","禪月字清師號別，壽春诗古帝恩深。","畫成羅漢驚三界，书似張顛直万金。","莫倚名高忘故旧，晓晴闲步一相尋。"]', '诗', 'shi', '', NULL, '寄禪月大師 張格 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0276959f-001e-46ce-9c3b-cb2a7e39685d', '贈禪月大師', '贈禪月大師', '7db93322-0e5f-496e-b25c-39a0cc03c434', '唐', '["長愛吾師性自然，天心白月水中蓮。","神通力遍恆沙外，詩句名高八米前。","尋訪不聞朝振錫，修行唯說夜安禪。","太平時節俱無事，莫惜時來話草玄。"]', '["长愛吾師性自然，天心白月水中蓮。","神通力遍恆沙外，诗句名高八米前。","尋訪不闻朝振錫，修行唯说夜安禪。","太平时節俱無事，莫惜时来話草玄。"]', '诗', 'shi', '', NULL, '贈禪月大師 王鍇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58642f5b-b16f-41a3-8f17-f9eb91804e38', '奉詔賦蜀主降唐', '奉詔賦蜀主降唐', 'fe9677ec-c0d1-4155-8222-fdfeaa096aba', '唐', '["滿城文武欲朝天，不覺鄰師犯塞煙。","唐主再懸新日月，蜀王難保舊山川。","非干將相扶持拙，自是君臣數盡年。","古往今來亦如此，幾曾歡笑幾潸然。"]', '["满城文武欲朝天，不覺鄰師犯塞煙。","唐主再懸新日月，蜀王难保旧山川。","非干將相扶持拙，自是君臣數尽年。","古往今来亦如此，幾曾歡笑幾潸然。"]', '诗', 'shi', '', NULL, '奉詔賦蜀主降唐 牛希濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9db58a2-7f2b-47e3-9041-6d3bb59cdcff', '蜀獁引 一', '蜀獁引 一', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["昂藏大步蠶叢國，曲頸微伸高九尺。","卓女窺窗莫我知，嚴仙據案何曾識。"]', '["昂藏大步蠶叢国，曲頸微伸高九尺。","卓女窺窗莫我知，嚴仙據案何曾識。"]', '诗', 'shi', '', NULL, '蜀獁引 一 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('662b7275-3149-4c2a-9f37-8cfa298f08da', '蜀獁引 二', '蜀獁引 二', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["自古皆傳蜀道難，爾何能過拔蛇山。","忽驚登得雞翁磧，又恐礙著鹿頭關。"]', '["自古皆傳蜀道难，爾何能過拔蛇山。","忽驚登得雞翁磧，又恐礙著鹿头关。"]', '诗', 'shi', '', NULL, '蜀獁引 二 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b1db042-e9eb-4ebd-b4eb-e533898d02a7', '句', '句', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["不隨俗物皆成土，只待良時却補天。","釜魚化作池中物，木履浮爲天際船。"]', '["不隨俗物皆成土，只待良时却補天。","釜鱼化作池中物，木履浮爲天際船。"]', '诗', 'shi', '', NULL, '句 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('013e7216-af7e-4d3d-a18f-1fe50fdf1e7d', '從幸秦川賦鷙獸詩', '從幸秦川賦鷙獸诗', 'ebff4846-2670-46f9-923d-75e4ad8ccbaf', '唐', '["巖下年年自寢訛，生靈餐盡意如何。","爪牙衆後民隨減，溪壑深來骨已多。","天子紀綱猶被弄，客人窮獨固難過。","長途莫怪無人跡，盡被山王稜殺他。"]', '["巖下年年自寢訛，生靈餐尽意如何。","爪牙衆後民隨減，溪壑深来骨已多。","天子紀綱猶被弄，客人窮独固难過。","长途莫怪無人跡，尽被山王稜殺他。"]', '诗', 'shi', '', NULL, '從幸秦川賦鷙獸詩 李浩弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005869f9-aced-4ae8-8092-8556958c7ad4', '批子弟理舊居狀', '批子弟理旧居狀', '3b9e078e-b670-4d37-af91-2de2d62834d7', '唐', '["四鄰侵我我從伊，畢竟須思未有時。","試上含元殿基望，秋風秋草正離離。"]', '["四鄰侵我我從伊，畢竟須思未有时。","試上含元殿基望，秋风秋草正離離。"]', '诗', 'shi', '', NULL, '批子弟理舊居狀 楊玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6adcf7-546f-4f00-8077-501bc252f581', '登慈恩寺塔', '登慈恩寺塔', '3b9e078e-b670-4d37-af91-2de2d62834d7', '唐', '["紫雲樓下曲江平，鴉噪殘陽麥隴青。","莫上慈恩最高處，不堪看又不堪聽。"]', '["紫云楼下曲江平，鴉噪殘陽麦隴青。","莫上慈恩最高处，不堪看又不堪听。"]', '诗', 'shi', '', NULL, '登慈恩寺塔 楊玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ddec308-c20f-4d2b-9fc9-62d8bac74227', '遣歌妓', '遣歌妓', '3b9e078e-b670-4d37-af91-2de2d62834d7', '唐', '["垂老無端用意乖，誰知道侶厭清齋。","如今又采蘼蕪去，辜負張君繡靸鞋。"]', '["垂老無端用意乖，誰知道侶厭清斋。","如今又采蘼蕪去，辜負張君繡靸鞋。"]', '诗', 'shi', '', NULL, '遣歌妓 楊玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5841457a-17e1-450d-9959-ec318bbf2355', '和題劒門', '和題劒门', 'bc08e5ac-9a8a-4617-b81e-90657827e635', '唐', '["閉關防老寇，孰敢振威稜。","險固疑天設，山河自古憑。","三川奚所賴，雙劒最堪矜。","鳥道微通處，煙霞鎖百層。"]', '["閉关防老寇，孰敢振威稜。","險固疑天設，山河自古憑。","三川奚所賴，雙劒最堪矜。","鸟道微通处，煙霞鎖百層。"]', '诗', 'shi', '', NULL, '和題劒門 韓昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1665bd-e8ec-4933-96fd-9c1b7e4e91c6', '從幸秦川過白衛獻詩', '從幸秦川過白衛獻诗', 'bc08e5ac-9a8a-4617-b81e-90657827e635', '唐', '["吾王巡狩爲安邊，此去秦亭尚數千。","夜照路岐山店火，曉通消息戍瓶煙。","爲雲巫峽雖神女，跨鳳秦樓是謫仙。","八駿似龍人似虎，何愁飛過大漫天。"]', '["吾王巡狩爲安邊，此去秦亭尚數千。","夜照路岐山店火，晓通消息戍瓶煙。","爲云巫峽雖神女，跨鳳秦楼是謫仙。","八駿似龙人似虎，何愁飞過大漫天。"]', '诗', 'shi', '', NULL, '從幸秦川過白衛獻詩 韓昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc71f03-8d6f-452b-843f-20c4251e6f4d', '記皂江墮水事', '記皂江墮水事', '66e6ae88-e6e1-4f26-8146-fb64e5d83ee1', '唐', '["青城山峭皂江寒，欲度當時作等閑。","櫂逆狂風趨近岸，舟逢怪石碎前灣。","手攜弱杖倉皇處，命出洪濤頃刻間。","今日深恩無以報，令人羞記雀銜環。"]', '["青城山峭皂江寒，欲度當时作等闲。","櫂逆狂风趨近岸，舟逢怪石碎前灣。","手携弱杖倉皇处，命出洪濤頃刻间。","今日深恩無以報，令人羞記雀銜环。"]', '诗', 'shi', '', NULL, '記皂江墮水事 楊鼎夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be8469b-9c1e-449b-a913-89e4b68f5e6b', '題張道隱太山祠畫龍', '題張道隐太山祠畫龙', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["世人空解競丹青，惟子通玄得墨靈。","應有鬼神看下筆，豈無風雨助成形。","威疑噴浪歸滄海，勢欲拏雲上杳冥。","靜閉綠堂深夜後，曉來簾幕似聞腥。"]', '["世人空解競丹青，惟子通玄得墨靈。","應有鬼神看下笔，豈無风雨助成形。","威疑噴浪归滄海，勢欲拏云上杳冥。","静閉綠堂深夜後，晓来簾幕似闻腥。"]', '诗', 'shi', '', NULL, '題張道隱太山祠畫龍 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9be50be-37eb-46ca-8272-a3fdc13664a6', '詠蠶', '詠蠶', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["辛勤得繭不盈筐，燈下繅絲恨更長。","著處不知來處苦，但貪衣上繡鴛鴦。"]', '["辛勤得繭不盈筐，灯下繅絲恨更长。","著处不知来处苦，但貪衣上繡鴛鴦。"]', '诗', 'shi', '', NULL, '詠蠶 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2b0a66-6ed7-438a-a139-d56c413bac46', '漁父歌三首 一', '漁父歌三首 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["水接衡門十里餘，信船歸去臥看書。","輕爵祿，慕玄虛，莫道漁人只爲魚。"]', '["水接衡门十里餘，信船归去臥看书。","轻爵祿，慕玄虛，莫道漁人只爲鱼。"]', '诗', 'shi', '', NULL, '漁父歌三首 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b29dc9-0529-427d-af4a-0081e8abdf46', '漁父歌三首 二', '漁父歌三首 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["避世垂綸不記年，官高爭得似君閑。","傾白酒，對青山，笑指柴門待月還。"]', '["避世垂綸不記年，官高爭得似君闲。","傾白酒，对青山，笑指柴门待月還。"]', '诗', 'shi', '', NULL, '漁父歌三首 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b428affa-cdce-4c01-a7f9-d82068e72d6c', '漁父歌三首 三', '漁父歌三首 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["棹警鷗飛水濺袍，影侵潭面柳垂條。","終日醉，絕塵勞，曾見錢塘八月濤。"]', '["棹警鷗飞水濺袍，影侵潭面柳垂條。","終日醉，絕塵勞，曾见錢塘八月濤。"]', '诗', 'shi', '', NULL, '漁父歌三首 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee3768c-ee3a-4e4b-b880-579f6b714a3f', '感禿鶖潛吟', '感禿鶖潛吟', '2b725675-1e79-4c3c-aaee-e8f518927fd2', '唐', '["昔日曾看瑞應圖，萬般祥端不如無。","摩訶池上分明見，仔細看來是那鶘。"]', '["昔日曾看瑞應圖，万般祥端不如無。","摩訶池上分明见，仔細看来是那鶘。"]', '诗', 'shi', '', NULL, '感禿鶖潛吟 顧敻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02458153-7701-4e31-9700-18c116a3df08', '與杜光庭', '與杜光庭', 'e0bc30ed-3383-4216-93ec-2294e8af708f', '唐', '["試問朝中爲宰相，何如林下作神仙。","一壺美酒一爐藥，飽聽松風白晝眠。"]', '["試问朝中爲宰相，何如林下作神仙。","一壺美酒一爐藥，飽听松风白晝眠。"]', '诗', 'shi', '', NULL, '與杜光庭 張令問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed207df2-47fc-4ea2-8a45-190ce95c9373', '題黃居寀秋山圖', '題黄居寀秋山圖', 'bb073a2a-a950-41b2-b757-8e6089e7b854', '唐', '["天與黃筌藝奇絕，筆精迴感重瞳悅。","運思潛通造化工，揮毫定得神仙訣。","秋來奉詔寫秋山，寫在輕綃數幅間。","高低向背無遺勢，重巒疊嶂何孱顏。","目想心存妙尤極，研巧覈能狀不得。","珍禽異獸皆自馴，奇花怪木非因植。","崎嶇石磴絕遊蹤，薄霧冥冥藏半峰。","娑蘿掩映迷仙洞，薜荔纍垂繳古松。","月檻參橋□，僧老坐搘筇。","屈原江上嬋娟竹，陶潛籬下芳菲菊。","良宵祗恐鷓鴣啼，晴波但見鴛鴦浴。","暮煙羃羃鏁村塢，一葉扁舟橫野度。","颯颯白蘋欲起風，黯黯紅蕉猶帶雨。","曲沼芙蓉香馥郁，長汀蘆荻花{艹/糓}蓛。","雁過孤峰帖遠青，鹿傍小溪飲殘綠。","秋山秀兮秋江靜，江光山色相輝映。","雪迸飛泉濺釣磯，雲分落葉擁樵徑。","張璪松石徒稱奇，邊鸞花鳥何足窺。","白旻鷹逞凌風勢，薛稷鶴誇警露姿。","方原畫山空巉巖，峭壁枯槎人見嫌。","孫位畫水多洶湧，驚湍怒濤人見恐。","若教對此定妍媸，必定伏膺懷愧悚。","再三展向冕旒側，便是移山回磵力。","大李小李滅聲華，獻之愷之無顏色。","髣髴垂綸渭水濱，吾皇覩之思良臣。","依稀荷鍤傅巖野，吾皇覩之求賢者。","從茲仄展復懸旌，宵衣旰食安天下。","才當老人星應候，願與南山俱獻壽。","微臣稽首貢長歌，丹青景化同天和。"]', '["天與黄筌藝奇絕，笔精迴感重瞳悅。","運思潛通造化工，揮毫定得神仙訣。","秋来奉詔寫秋山，寫在轻綃數幅间。","高低向背無遺勢，重巒叠嶂何孱顏。","目想心存妙尤極，研巧覈能狀不得。","珍禽異獸皆自馴，奇花怪木非因植。","崎嶇石磴絕游蹤，薄霧冥冥藏半峰。","娑蘿掩映迷仙洞，薜荔纍垂繳古松。","月檻參橋□，僧老坐搘筇。","屈原江上嬋娟竹，陶潛籬下芳菲菊。","良宵祗恐鷓鴣啼，晴波但见鴛鴦浴。","暮煙羃羃鏁村塢，一葉扁舟橫野度。","颯颯白蘋欲起风，黯黯紅蕉猶带雨。","曲沼芙蓉香馥郁，长汀蘆荻花{艹/糓}蓛。","雁過孤峰帖远青，鹿傍小溪饮殘綠。","秋山秀兮秋江静，江光山色相輝映。","雪迸飞泉濺釣磯，云分落葉擁樵徑。","張璪松石徒稱奇，邊鸾花鸟何足窺。","白旻鷹逞凌风勢，薛稷鹤誇警露姿。","方原畫山空巉巖，峭壁枯槎人见嫌。","孫位畫水多洶湧，驚湍怒濤人见恐。","若教对此定妍媸，必定伏膺懷愧悚。","再三展向冕旒側，便是移山回磵力。","大李小李滅声华，獻之愷之無顏色。","髣髴垂綸渭水濱，吾皇覩之思良臣。","依稀荷鍤傅巖野，吾皇覩之求賢者。","從茲仄展复懸旌，宵衣旰食安天下。","才當老人星應候，願與南山俱獻壽。","微臣稽首貢长歌，丹青景化同天和。"]', '诗', 'shi', '', NULL, '題黃居寀秋山圖 徐光溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d40b85a-570b-41c7-bc3e-32dd48dbb5dc', '同劉侍郎詠笋', '同劉侍郎詠笋', 'bb073a2a-a950-41b2-b757-8e6089e7b854', '唐', '["迸出班犀數十株，更添幽景向蓬壺。","出來似有凌雲勢，用作丹梯得也無。"]', '["迸出班犀數十株，更添幽景向蓬壺。","出来似有凌云勢，用作丹梯得也無。"]', '诗', 'shi', '', NULL, '同劉侍郎詠笋 徐光溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d99ff5-acb2-4d62-bd4c-35e58db8822e', '貫休應夢羅漢畫歌', '貫休應梦羅漢畫歌', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["西嶽高僧名貫休，孤情峭拔凌清秋。","天教水墨畫羅漢，魁岸古容生筆頭。","時捎大絹泥高壁，閉目焚香坐禪室。","忽然夢裏見真儀，脫下袈裟點神筆。","高握節腕當空擲，窸窣毫端任狂逸。","逡巡便是兩三軀，不似畫工虛費日。","怪石安拂嵌復枯，真僧列坐連跏[趺]。","形如瘦鶴精神健，頂似伏犀頭骨麤。","倚松根，傍巖縫，曲錄腰身長欲動。","看經弟子擬聞聲，瞌睡山童疑有夢。","不知夏臘幾多年，一手搘頤偏袒肩。","口開或若共人語，身定復疑初坐禪。","案前臥象低垂鼻，崖畔戲猿斜展臂。","芭蕉花裏刷輕紅，苔蘚文中暈深翠。","硬笻杖，矮松牀，雪色眉毛一寸長。","繩開梵夾兩三片，線補衲衣千萬行。","林間亂葉紛紛墮，一印殘香斷煙火。","皮穿木屐不曾拖，笋織蒲團鎮長坐。","休公休公逸藝無人加，聲譽喧喧遍海涯。","五七字句一千首，大小篆書三十家。","唐朝歷歷多名士，蕭子雲兼吳道子。","若將書畫比休公，只恐當時浪生死。","休公休公始自江南來入秦，於今到蜀無交親。","詩名畫手皆奇絕，覰你凡人爭是人。","瓦棺寺裏維摩詰，舍衛城中辟支佛。","若將此畫比量看，總在人間爲第一。"]', '["西嶽高僧名貫休，孤情峭拔凌清秋。","天教水墨畫羅漢，魁岸古容生笔头。","时捎大絹泥高壁，閉目焚香坐禪室。","忽然梦裏见真儀，脫下袈裟点神笔。","高握節腕當空擲，窸窣毫端任狂逸。","逡巡便是兩三軀，不似畫工虛費日。","怪石安拂嵌复枯，真僧列坐連跏[趺]。","形如瘦鹤精神健，頂似伏犀头骨麤。","倚松根，傍巖縫，曲錄腰身长欲动。","看經弟子擬闻声，瞌睡山童疑有梦。","不知夏臘幾多年，一手搘頤偏袒肩。","口开或若共人語，身定复疑初坐禪。","案前臥象低垂鼻，崖畔戲猿斜展臂。","芭蕉花裏刷轻紅，苔蘚文中暈深翠。","硬笻杖，矮松牀，雪色眉毛一寸长。","繩开梵夾兩三片，線補衲衣千万行。","林间亂葉紛紛墮，一印殘香斷煙火。","皮穿木屐不曾拖，笋织蒲團鎮长坐。","休公休公逸藝無人加，声譽喧喧遍海涯。","五七字句一千首，大小篆书三十家。","唐朝歷歷多名士，蕭子云兼吳道子。","若將书畫比休公，只恐當时浪生死。","休公休公始自江南来入秦，於今到蜀無交親。","诗名畫手皆奇絕，覰你凡人爭是人。","瓦棺寺裏維摩詰，舍衛城中辟支佛。","若將此畫比量看，總在人间爲第一。"]', '诗', 'shi', '', NULL, '貫休應夢羅漢畫歌 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b432f31a-d613-4575-b2dc-072b8343b8fb', '題景煥畫應天寺壁天王歌', '題景煥畫應天寺壁天王歌', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["錦城東北黃金地，故跡何人興此寺。","白眉長老重名公，曾識會稽山處士。","寺門左壁圖天王，威儀部從來何方。","鬼神怪異滿壁走，當簷颯颯生秋光。","我聞天王分理四天下，水晶宮殿琉璃瓦。","綵杖時驅狒𤝞裝，金鞭頻策騏驎馬。","毗沙大像何光輝，手擎巨塔凌雲飛。","地神對出寶缾子，天女倒披金縷衣。","唐朝說著名公畫，周昉毫端善圖寫。","張僧繇是有神人，吳道子稱無敵者。","奇哉妙手傳孫公，能如此地留神蹤。","斜窺小鬼怒雙目，直倚越狼高半胸。","寶冠動總生威容，趨蹌左右來傾恭。","臂橫鷹爪尖纖利，腰纏虎皮斑剝紅。","飄飄但恐入雲中，步驟還疑歸海東。","蟒蛇拖得渾身墮，精魅搦來雙眼空。","當時此藝實難有，鎮在寶坊稱不朽。","東邊畫了空西邊，留與後人教敵手。","後人見者皆心驚，盡爲名公不敢爭。","誰知未滿三十載，或有異人來間生。","匡山處士名稱樸，頭骨高奇連五嶽。","曾持象簡累爲官，又有蛇珠常在握。","昔年長老遇奇蹤，今日門師識景公。","興來便請泥高壁，亂搶筆頭如疾風。","逡巡隊仗何顛逸，散漫奇形皆湧出。","交加器械滿虛空，兩面或然如鬬敵。","聖王怒色覽東西，劒刃一揮皆整齊。","腕頭獅子咬金甲，脚底夜叉擊絡鞮。","馬頭壯健多筋節，烏觜彎環如屈鐵。","遍身虵虺亂縱橫，遶頷髑髏乾孑裂。","眉麤眼豎髮如錐，怪異令人不可知。","科頭巨卒欲生鬼，半面女郎安小兒。","況聞此寺初興置，地脉沈沈當正氣。","如何請得二山人，下筆咸成千古事。","君不見明皇天寶年，畫龍致雨非偶然。","包含萬象藏心裏，變現百般生眼前。","後來畫品列名賢，唯此二人堪比肩。","人間是物皆求得，此樣欲於何處傳。","嘗憂壁底生雲霧，揭起寺門天上去。"]', '["錦城东北黄金地，故跡何人兴此寺。","白眉长老重名公，曾識會稽山处士。","寺门左壁圖天王，威儀部從来何方。","鬼神怪異满壁走，當簷颯颯生秋光。","我闻天王分理四天下，水晶宮殿琉璃瓦。","綵杖时驱狒𤝞裝，金鞭頻策騏驎马。","毗沙大像何光輝，手擎巨塔凌云飞。","地神对出寶缾子，天女倒披金縷衣。","唐朝说著名公畫，周昉毫端善圖寫。","張僧繇是有神人，吳道子稱無敵者。","奇哉妙手傳孫公，能如此地留神蹤。","斜窺小鬼怒雙目，直倚越狼高半胸。","寶冠动總生威容，趨蹌左右来傾恭。","臂橫鷹爪尖纖利，腰纏虎皮斑剝紅。","飄飄但恐入云中，步驟還疑归海东。","蟒蛇拖得渾身墮，精魅搦来雙眼空。","當时此藝實难有，鎮在寶坊稱不朽。","东邊畫了空西邊，留與後人教敵手。","後人见者皆心驚，尽爲名公不敢爭。","誰知未满三十載，或有異人来间生。","匡山处士名稱樸，头骨高奇連五嶽。","曾持象簡累爲官，又有蛇珠常在握。","昔年长老遇奇蹤，今日门師識景公。","兴来便請泥高壁，亂搶笔头如疾风。","逡巡隊仗何顛逸，散漫奇形皆湧出。","交加器械满虛空，兩面或然如鬬敵。","聖王怒色覽东西，劒刃一揮皆整齊。","腕头獅子咬金甲，脚底夜叉擊絡鞮。","马头壯健多筋節，烏觜彎环如屈鐵。","遍身虵虺亂縱橫，遶頷髑髏乾孑裂。","眉麤眼豎髮如錐，怪異令人不可知。","科头巨卒欲生鬼，半面女郎安小兒。","況闻此寺初兴置，地脉沈沈當正氣。","如何請得二山人，下笔咸成千古事。","君不见明皇天寶年，畫龙致雨非偶然。","包含万象藏心裏，变現百般生眼前。","後来畫品列名賢，唯此二人堪比肩。","人间是物皆求得，此樣欲於何处傳。","嘗憂壁底生云霧，揭起寺门天上去。"]', '诗', 'shi', '', NULL, '題景煥畫應天寺壁天王歌 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdd13c5-2e1c-4ff8-bfba-9ab6f0260cab', '漁父歌二首 一', '漁父歌二首 一', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["擺脫塵機上釣船，免教榮辱有流年。","無繫絆，沒愁煎，須信船中有散仙。"]', '["擺脫塵機上釣船，免教榮辱有流年。","無繫絆，沒愁煎，須信船中有散仙。"]', '诗', 'shi', '', NULL, '漁父歌二首 一 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c728fe61-d03d-449a-a289-8b9bca87a014', '漁父歌二首 二', '漁父歌二首 二', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["風浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙輕，撥刺遊魚幾處驚。"]', '["风浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙轻，撥刺游鱼幾处驚。"]', '诗', 'shi', '', NULL, '漁父歌二首 二 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d68ff6f-2852-4d89-bc66-18345bfabd43', '大遊仙詩', '大游仙诗', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["赤城霞起武陵春，桐柏先生解守真。","白石橋高曾縱步，朱陽館靜每存神。","囊中隱訣多仙術，肘後方書濟俗人。","自領蓬萊都水監，只憂滄海變成塵。"]', '["赤城霞起武陵春，桐柏先生解守真。","白石橋高曾縱步，朱陽館静每存神。","囊中隐訣多仙術，肘後方书濟俗人。","自領蓬萊都水監，只憂滄海变成塵。"]', '诗', 'shi', '', NULL, '大遊仙詩 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508a70ad-8b2d-4db2-b197-0ed342314da2', '楊柳枝', '楊柳枝', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["軟碧搖煙似送人，映花時把翠蛾嚬。","青青自是風流主，慢颯金絲待洛神。"]', '["軟碧搖煙似送人，映花时把翠蛾嚬。","青青自是风流主，慢颯金絲待洛神。"]', '诗', 'shi', '', NULL, '楊柳枝 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4c9992-415b-450c-8d90-a7a88d8b3006', '句', '句', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["古人重到今人愛，萬局都無一局同。"]', '["古人重到今人愛，万局都無一局同。"]', '诗', 'shi', '', NULL, '句 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5354e7-1410-475c-86a9-3fb10ece5269', '感懷詩', '感懷诗', 'ea067848-c8eb-4d32-89f4-2223b5c04604', '唐', '["昨日方髽髻，如今滿頷髯。","紫閣無心戀，青山有意潛。"]', '["昨日方髽髻，如今满頷髯。","紫閣無心戀，青山有意潛。"]', '诗', 'shi', '', NULL, '感懷詩 劉義度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7761c55-8be6-4a55-acb2-8f17f8dbd29f', '同徐學士詠笋', '同徐学士詠笋', '84716c34-4cd8-4127-bc35-3e2a8977d612', '唐', '["徐徐出土非人種，枝葉難投日月壺。","爲是因緣生此地，從他長養譬如無。"]', '["徐徐出土非人種，枝葉难投日月壺。","爲是因緣生此地，從他长養譬如無。"]', '诗', 'shi', '', NULL, '同徐學士詠笋 劉羲叟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ef074fb-669e-4ce2-9392-107b219640f3', '復留侯從効問南漢劉巖改名龑字音義', '复留侯從効问南漢劉巖改名龑字音義', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["伏羲初畫卦，蒼氏乃製字。","點畫有偏旁，陰陽貴協比。","古者不嫌名，周公始稱諱。","始諱猶未酷，後習轉多忌。","或援他代易，或變文迴避。","濫觴久滋蔓，傷心日益熾。","孫休命子名，吳國尊王意。","𩅦𦯶𩅔{覀/升}僻，{壴臣}昷𥨆𡚕異。","梁復踵已非，時亦迹舊事。","𡽏杰自其一，蜀闖是其二。","鄙哉化䁈名，陋矣𡏜䵎義。","大唐有天下，武后擁神器。","私制迄無取，古音實相類。","●●●囝星，●●{厓厂=}●埊。","●圀及曌●，作史難詳備。","唐祚值傾危，劉龑懷僭僞。","吁嗟毒蛟輩，睥睨飛龍位。","龑巖雖同音，形體殊乖致。","廢學愧未弘，來問辱不棄。","奇字難雄博，摛文伏韓智。","因誦鄙所聞，敢布諸下吏。"]', '["伏羲初畫卦，蒼氏乃製字。","点畫有偏旁，陰陽貴協比。","古者不嫌名，周公始稱諱。","始諱猶未酷，後習轉多忌。","或援他代易，或变文迴避。","濫觴久滋蔓，傷心日益熾。","孫休命子名，吳国尊王意。","𩅦𦯶𩅔{覀/升}僻，{壴臣}昷𥨆𡚕異。","梁复踵已非，时亦迹旧事。","𡽏杰自其一，蜀闖是其二。","鄙哉化䁈名，陋矣𡏜䵎義。","大唐有天下，武后擁神器。","私制迄無取，古音實相類。","●●●囝星，●●{厓厂=}●埊。","●圀及曌●，作史难詳備。","唐祚值傾危，劉龑懷僭僞。","吁嗟毒蛟輩，睥睨飞龙位。","龑巖雖同音，形體殊乖致。","廢学愧未弘，来问辱不棄。","奇字难雄博，摛文伏韓智。","因誦鄙所闻，敢布諸下吏。"]', '诗', 'shi', '', NULL, '復留侯從効問南漢劉巖改名龑字音義 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('839bf05c-5cfd-4c14-b517-6b902ecb0e74', '柳堤詩', '柳堤诗', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["種稻三十頃，種柳百餘[株]。","稻可供飦粥，柳可爨庖廚。","息耒柳陰下，讀書稻田隅。","以樂堯舜道，同是耕莘夫。"]', '["種稻三十頃，種柳百餘[株]。","稻可供飦粥，柳可爨庖廚。","息耒柳陰下，读书稻田隅。","以乐堯舜道，同是耕莘夫。"]', '诗', 'shi', '', NULL, '柳堤詩 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e69ef9f8-337a-4d5b-b840-6393fd6fda33', '勸王氏入貢寵予以官作辭命篇', '勸王氏入貢寵予以官作辞命篇', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["爭霸圖王事總非，中原失統可傷悲。","從來賓主如郵傳，勝負干戈似局棊。","周粟縱榮寧忍食，葛廬頻顧謾勞思。","江山有待早歸去，好向鷦林擇一枝。"]', '["爭霸圖王事總非，中原失統可傷悲。","從来賓主如郵傳，勝負干戈似局棊。","周粟縱榮寧忍食，葛廬頻顧謾勞思。","江山有待早归去，好向鷦林擇一枝。"]', '诗', 'shi', '', NULL, '勸王氏入貢寵予以官作辭命篇 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eea1e04-096c-4be4-8fe0-f2b18161964f', '余遷泉山城留侯招遊郡圃作此', '余遷泉山城留侯招游郡圃作此', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["當年巧匠製茅亭，臺館翬飛匝郡城。","萬竈貔貅戈甲散，千家羅綺管弦鳴。","柳腰舞罷香風度，花臉粧勻酒暈生。","試問亭前花與柳，幾番衰謝幾番榮。"]', '["當年巧匠製茅亭，台館翬飞匝郡城。","万竈貔貅戈甲散，千家羅綺管弦鳴。","柳腰舞罷香风度，花臉粧勻酒暈生。","試问亭前花與柳，幾番衰謝幾番榮。"]', '诗', 'shi', '', NULL, '余遷泉山城留侯招遊郡圃作此 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9668aded-df40-4a74-9b8d-433aac61c45c', '留侯受南唐節度使知郡事辟予爲屬以詩謝之', '留侯受南唐節度使知郡事辟予爲屬以诗謝之', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["晉江江畔趁春風，耕破雲山幾萬重。","兩足一犂無外事，使君何啻五侯封。"]', '["晉江江畔趁春风，耕破云山幾万重。","兩足一犂無外事，使君何啻五侯封。"]', '诗', 'shi', '', NULL, '留侯受南唐節度使知郡事辟予爲屬以詩謝之 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02b6f922-6de0-4b4d-94e9-3435904f2bd4', '遣子訪劉乙', '遣子訪劉乙', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["掃石耕山舊子真，布衣草履自隨身。","石崖壁立題詩處，知是當年鳳閣人。"]', '["掃石耕山旧子真，布衣草履自隨身。","石崖壁立題诗处，知是當年鳳閣人。"]', '诗', 'shi', '', NULL, '遣子訪劉乙 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55d469b-8801-4d5e-99f6-93c4910e4523', '永嘉亂衣冠南度流落南泉作憶昔吟', '永嘉亂衣冠南度流落南泉作憶昔吟', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["憶昔永嘉際，中原板蕩年。","衣冠墜塗炭，輿輅染腥膻。","國勢多危厄，宗人苦播遷。","南來頻灑淚，渴驥每思泉。"]', '["憶昔永嘉際，中原板蕩年。","衣冠墜塗炭，輿輅染腥膻。","国勢多危厄，宗人苦播遷。","南来頻灑泪，渴驥每思泉。"]', '诗', 'shi', '', NULL, '永嘉亂衣冠南度流落南泉作憶昔吟 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c3ba991-c31e-4e9a-b971-49e9ab7cc437', '癸卯閩亂從弟監察御史敬凝迎仕別作', '癸卯閩亂從弟監察御史敬凝迎仕別作', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["一別幾經春，棲遲晉水濱。","鶺鴒長在念，鴻雁忽來賓。","五斗嫌腰折，朋山刺眼新。","善辭如復我，四海五湖身。"]', '["一別幾經春，棲遲晉水濱。","鶺鴒长在念，鴻雁忽来賓。","五斗嫌腰折，朋山刺眼新。","善辞如复我，四海五湖身。"]', '诗', 'shi', '', NULL, '癸卯閩亂從弟監察御史敬凝迎仕別作 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b432689-4b77-43af-bdaa-ddbbc3accc2c', '追和秦隱君辭薦之韻上陳侯乞歸鳳山', '追和秦隐君辞薦之韻上陳侯乞归鳳山', 'ed0ee3c9-8ae1-42ee-90fe-af9e99d4dbb5', '唐', '["誰言悅口是甘肥，獨酌鵝兒噉翠微。","蠅利薄於青紙扇，羊裘煖甚紫羅衣。","心隨倦鳥甘棲宿，目送征鴻遠奮飛。","擊壤太平朝野客，鳳山深處□生輝。"]', '["誰言悅口是甘肥，独酌鵝兒噉翠微。","蠅利薄於青紙扇，羊裘煖甚紫羅衣。","心隨倦鸟甘棲宿，目送征鴻远奮飞。","擊壤太平朝野客，鳳山深处□生輝。"]', '诗', 'shi', '', NULL, '追和秦隱君辭薦之韻上陳侯乞歸鳳山 詹琲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf2ba782-979f-493f-a9e3-2a8d670acc35', '雲', '云', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["因登巨石知來處，勃勃元生綠蘚痕。","靜即等閑藏草木，動時頃刻遍乾坤。","橫天未必朋元惡，捧日還曾瑞至尊。","不獨朝朝在巫峽，楚王何事謾勞魂。"]', '["因登巨石知来处，勃勃元生綠蘚痕。","静即等闲藏草木，动时頃刻遍乾坤。","橫天未必朋元惡，捧日還曾瑞至尊。","不独朝朝在巫峽，楚王何事謾勞魂。"]', '诗', 'shi', '', NULL, '雲 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4760fc44-7062-447a-ad4f-579453cc556e', '句', '句', 'b5c5c12e-3c6b-4345-a5b8-f80832d623c0', '唐', '["苦教作鎮居中國，爭得泥金在泰山。","纔聞暖律先偷眼，既待和風始展眉。","蒙君知重惠瓊實，薄起金刀釘玉深。","嚼處春冰敲齒冷，嚥時雪液沃心寒。","深妝玉瓦平無壠，亂拂蘆花細有聲。","日回禽影穿疎木，風遞猨聲入小樓。"]', '["苦教作鎮居中国，爭得泥金在泰山。","纔闻暖律先偷眼，既待和风始展眉。","蒙君知重惠瓊實，薄起金刀釘玉深。","嚼处春冰敲齒冷，嚥时雪液沃心寒。","深妝玉瓦平無壠，亂拂蘆花細有声。","日回禽影穿疎木，风遞猨声入小楼。"]', '诗', 'shi', '', NULL, '句 幸夤遜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe589d8b-6a1f-4a8f-9a91-89c870603419', '詩', '诗', '0a891673-2202-4e8d-9f04-a89fe3af3fbf', '唐', '["九重天子人中貴，五等諸侯閫外尊。","爭似布衣雲水客，不將名字挂乾坤。"]', '["九重天子人中貴，五等諸侯閫外尊。","爭似布衣云水客，不將名字挂乾坤。"]', '诗', 'shi', '', NULL, '詩 丁元和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff001976-5c56-4a4f-aea5-90eb260269c6', '詠蜀都城上芙蓉花', '詠蜀都城上芙蓉花', '56ced14e-c26a-418d-ae7c-5ef9dd59699b', '唐', '["四十里城花發時，錦囊高下照坤維。","雖粧蜀國三秋色，難入豳風七月詩。"]', '["四十里城花發时，錦囊高下照坤維。","雖粧蜀国三秋色，难入豳风七月诗。"]', '诗', 'shi', '', NULL, '詠蜀都城上芙蓉花 張立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da34f34f-7e79-4a36-80a8-b8cbdd7e5bc9', '又詠蜀都城上芙蓉花', '又詠蜀都城上芙蓉花', '56ced14e-c26a-418d-ae7c-5ef9dd59699b', '唐', '["去年今日到城都，城上芙蓉錦繡舒。","今日重來舊遊處，此花顦顇不如初。"]', '["去年今日到城都，城上芙蓉錦繡舒。","今日重来旧游处，此花顦顇不如初。"]', '诗', 'shi', '', NULL, '又詠蜀都城上芙蓉花 張立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85eeacbb-7277-43fb-8fc7-6f1c3fab9e28', '句', '句', '56ced14e-c26a-418d-ae7c-5ef9dd59699b', '唐', '["朝廷不用憂巴蜀，稱霸何曾是蜀人。"]', '["朝廷不用憂巴蜀，稱霸何曾是蜀人。"]', '诗', 'shi', '', NULL, '句 張立 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece3d218-8c47-4087-ac2d-bee5df2095ac', '括蒼山', '括蒼山', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["盡日行方半，諸山直下看。","白雲隨步起，危徑極天盤。","瀑頂橋形小，溪邊店影寒。","往來空太息，玄鬢改非難。"]', '["尽日行方半，諸山直下看。","白云隨步起，危徑極天盤。","瀑頂橋形小，溪邊店影寒。","往来空太息，玄鬢改非难。"]', '诗', 'shi', '', NULL, '括蒼山 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca62ef4-3c94-4915-9424-f6d3f7bbbf4e', '憶天台山', '憶天台山', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["常記遊靈境，道人情不低。","巖房容偃息，天路許相攜。","霞散曙峰外，虹生涼瀑西。","何當塵役了，重去聽猨啼。"]', '["常記游靈境，道人情不低。","巖房容偃息，天路許相携。","霞散曙峰外，虹生涼瀑西。","何當塵役了，重去听猨啼。"]', '诗', 'shi', '', NULL, '憶天台山 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08515c42-46bf-4df1-8eb1-29607de29d42', '冬日暮國清寺留題', '冬日暮国清寺留題', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["天台山下寺，冬暮景如屏。","樹密風長在，年深像有靈。","高鐘疑到月，遠燒欲連星。","因共真僧話，心中萬慮寧。"]', '["天台山下寺，冬暮景如屏。","樹密风长在，年深像有靈。","高鐘疑到月，远燒欲連星。","因共真僧話，心中万慮寧。"]', '诗', 'shi', '', NULL, '冬日暮國清寺留題 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00916f6a-26f1-490b-83e7-5dcfebe353a8', '靈溪觀', '靈溪观', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["鼇海西邊地，宵吟景象寬。","雲開孤月上，瀑噴一山寒。","人異髮常綠，草靈秋不乾。","無由此棲息，魂夢在長安。"]', '["鼇海西邊地，宵吟景象寬。","云开孤月上，瀑噴一山寒。","人異髮常綠，草靈秋不乾。","無由此棲息，魂梦在长安。"]', '诗', 'shi', '', NULL, '靈溪觀 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867e210c-3c08-4ec4-b6d6-2a751689d39c', '懷華山隱者', '懷华山隐者', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["先生入太華，杳杳絕良音。","秋夢有時見，孤雲無處尋。","神清峰頂立，衣冷瀑邊吟。","應笑干名者，六街塵土深。"]', '["先生入太华，杳杳絕良音。","秋梦有时见，孤云無处尋。","神清峰頂立，衣冷瀑邊吟。","應笑干名者，六街塵土深。"]', '诗', 'shi', '', NULL, '懷華山隱者 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1214742-797e-4613-b64e-3e7015c6d4f1', '贈惠律大師', '贈惠律大師', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["秋是憶山日，禪窗露灑餘。","幾懸華頂夢，應寄沃洲書。","風月資吟筆，杉篁籠靜居。","滿城誰不重，見著紫衣初。"]', '["秋是憶山日，禪窗露灑餘。","幾懸华頂梦，應寄沃洲书。","风月資吟笔，杉篁籠静居。","满城誰不重，见著紫衣初。"]', '诗', 'shi', '', NULL, '贈惠律大師 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7890449-7174-465d-b5fa-f160a3e92b9a', '經費冠卿舊隱', '經費冠卿旧隐', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["節高終不起，死戀九華山。","聖主情何切，孤雲性本閑。","名傳中國外，墳在亂松間。","依約曾棲處，斜陽鳥自還。"]', '["節高終不起，死戀九华山。","聖主情何切，孤云性本闲。","名傳中国外，墳在亂松间。","依約曾棲处，斜陽鸟自還。"]', '诗', 'shi', '', NULL, '經費冠卿舊隱 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb464e8-6dea-49d6-8f85-654d009936ef', '聞蟬', '闻蟬', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["一雨一番晴，山林冷落青。","莫侵殘日噪，正在異鄉聽。","孤館宿漳浦，扁舟離洞庭。","年年當此際，那免鬢凋零。"]', '["一雨一番晴，山林冷落青。","莫侵殘日噪，正在異乡听。","孤館宿漳浦，扁舟離洞庭。","年年當此際，那免鬢凋零。"]', '诗', 'shi', '', NULL, '聞蟬 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7d2d92-ac17-46b6-9096-7f85751b7d58', '送休公歸衡', '送休公归衡', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["草履初登南嶽船，銅瓶猶貯北山泉。","衡陽舊寺春歸晚，門鎖寒潭幾樹蟬。"]', '["草履初登南嶽船，銅瓶猶貯北山泉。","衡陽旧寺春归晚，门鎖寒潭幾樹蟬。"]', '诗', 'shi', '', NULL, '送休公歸衡 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a4db40-1b5e-4f5e-bb25-075d4956c893', '句', '句', '4948b49a-edd7-47ad-a807-0b3c50b2af26', '唐', '["句向夜深得，心從天外歸。","危樓聊側耳，高柳又鳴蟬。","蘚色圍波井，花陰上竹樓。","對面電瞋樹，當街雨趁人。","春光懷玉闕，萬里起初程。","江上呼風去，天邊挂席飛。","漆燈尋黑洞，之字上危峰。"]', '["句向夜深得，心從天外归。","危楼聊側耳，高柳又鳴蟬。","蘚色圍波井，花陰上竹楼。","对面電瞋樹，當街雨趁人。","春光懷玉闕，万里起初程。","江上呼风去，天邊挂席飞。","漆灯尋黑洞，之字上危峰。"]', '诗', 'shi', '', NULL, '句 劉昭禹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca855e5-1274-430c-ac60-e30cdc5a9e15', '銅柱辭', '銅柱辞', '455b7255-d878-4f89-bdcc-b50fc4e6986c', '唐', '["招靈鑄柱垂英烈，手執干戈征百越。","誕今鑄柱庇黔黎，指畫風雷開五溪。","五溪之險不足恃，我旅爭登若平地。","五溪之衆不足平，我師輕躡如春冰。","溪人畏威思納質，棄汙歸明求立誓。","誓山川兮告鬼神，保子孫兮千萬春。"]', '["招靈鑄柱垂英烈，手執干戈征百越。","誕今鑄柱庇黔黎，指畫风雷开五溪。","五溪之險不足恃，我旅爭登若平地。","五溪之衆不足平，我師轻躡如春冰。","溪人畏威思納質，棄汙归明求立誓。","誓山川兮告鬼神，保子孫兮千万春。"]', '诗', 'shi', '', NULL, '銅柱辭 李宏臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d6778b3-9e6b-4f20-942f-4718bc17d2df', '題桃源', '題桃源', '455b7255-d878-4f89-bdcc-b50fc4e6986c', '唐', '["山翠參差水渺茫，秦人昔在楚封[疆]。","當時避世乾坤窄，此地安家日月長。","草色幾經壇杏老，巖花猶帶澗桃香。","他年倘遂平生志，來著霞衣侍玉皇。"]', '["山翠參差水渺茫，秦人昔在楚封[疆]。","當时避世乾坤窄，此地安家日月长。","草色幾經壇杏老，巖花猶带澗桃香。","他年倘遂平生志，来著霞衣侍玉皇。"]', '诗', 'shi', '', NULL, '題桃源 李宏臯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71050f4-0261-41bc-881e-1935a37ebb01', '李臯試詩', '李臯試诗', '7a8c5552-605a-4888-8eb7-a8b483d85551', '唐', '["似玉來投獄，拋家去就枷。","可憐兩片木，夾却一枝花。"]', '["似玉来投獄，拋家去就枷。","可怜兩片木，夾却一枝花。"]', '诗', 'shi', '', NULL, '李臯試詩 何仲舉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9632ea8c-ce70-4e5b-a1d3-f9fc3ffddcaf', '句', '句', '7a8c5552-605a-4888-8eb7-a8b483d85551', '唐', '["碧雲章句纔離手，紫府神仙盡點頭。","樹迎高鳥歸深野，雲傍斜陽過遠山。"]', '["碧云章句纔離手，紫府神仙尽点头。","樹迎高鸟归深野，云傍斜陽過远山。"]', '诗', 'shi', '', NULL, '句 何仲舉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efb8387f-cb9f-40bd-8f0b-2df5fd8d3b78', '畊夫謠', '畊夫謠', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["張緒逞風流，王衍事輕薄。","出門逢畊夫，顏色必不樂。","肥膚如玉潔，力拗絲不折。","半日無畊夫，此輩總餓殺。"]', '["張緒逞风流，王衍事轻薄。","出门逢畊夫，顏色必不乐。","肥膚如玉潔，力拗絲不折。","半日無畊夫，此輩總餓殺。"]', '诗', 'shi', '', NULL, '畊夫謠 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f479eec1-12a5-47b4-bb53-10a5ba462b50', '贈齊己', '贈齊己', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["我唐有僧號齊己，未出家時宰相器。","爰見夢中逢五丁，毀形自學無生理。","骨瘦神清風一襟，松老霜天鶴病深。","一言悟得生死海，芙蓉吐出琉璃心。","悶見有唐風雅缺，敲破冰天飛白雪。","清塞清江却有靈，遺魂泣對荒郊月。","格何古，天工未生誰知主。","混沌鑿開雞子黃，散作純風如膽苦。","意何新，織女星機挑白雲。","真宰夜來調暖律，聲聲吹出嫩青春。","調何雅，澗底孤松秋雨灑。","嫦娥月裏學步虛，桂風吹落玉山下。","語何奇，血潑乾坤龍戰時。","祖龍跨海日方出，一鞭風雨萬山飛。","己公己公道如此，浩浩寰中如獨自。","一簟松風冷如冰，長伴巢由伸脚睡。"]', '["我唐有僧號齊己，未出家时宰相器。","爰见梦中逢五丁，毀形自学無生理。","骨瘦神清风一襟，松老霜天鹤病深。","一言悟得生死海，芙蓉吐出琉璃心。","悶见有唐风雅缺，敲破冰天飞白雪。","清塞清江却有靈，遺魂泣对荒郊月。","格何古，天工未生誰知主。","混沌鑿开雞子黄，散作純风如膽苦。","意何新，织女星機挑白云。","真宰夜来調暖律，声声吹出嫩青春。","調何雅，澗底孤松秋雨灑。","嫦娥月裏学步虛，桂风吹落玉山下。","語何奇，血潑乾坤龙戰时。","祖龙跨海日方出，一鞭风雨万山飞。","己公己公道如此，浩浩寰中如独自。","一簟松风冷如冰，长伴巢由伸脚睡。"]', '诗', 'shi', '', NULL, '贈齊己 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43890099-7021-48b1-80c6-b59fba090b24', '贈江處士', '贈江处士', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["門在松陰裏，山僧幾度過。","藥靈丸不大，棊妙子無多。","薄霧籠寒徑，殘風戀綠蘿。","金烏兼玉兔，年幾奈公何。"]', '["门在松陰裏，山僧幾度過。","藥靈丸不大，棊妙子無多。","薄霧籠寒徑，殘风戀綠蘿。","金烏兼玉兔，年幾奈公何。"]', '诗', 'shi', '', NULL, '贈江處士 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69809a7d-bdad-42e6-814b-ed3f3a9b7b54', '東華觀偃松', '东华观偃松', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["半已化爲石，有靈通碧湘。","生逢堯雨露，老直漢風霜。","月滴蟾心水，龍遺腦骨香。","始於毫末後，曾見幾興亡。"]', '["半已化爲石，有靈通碧湘。","生逢堯雨露，老直漢风霜。","月滴蟾心水，龙遺腦骨香。","始於毫末後，曾见幾兴亡。"]', '诗', 'shi', '', NULL, '東華觀偃松 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae7cedb-1dc7-404b-bf1e-20773737c8bd', '詠椶樹', '詠椶樹', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["葉似新蒲綠，身如亂錦纏。","任君千度剝，意氣自衝天。"]', '["葉似新蒲綠，身如亂錦纏。","任君千度剝，意氣自衝天。"]', '诗', 'shi', '', NULL, '詠椶樹 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d25e19-4b06-4464-b753-46c8c1893c1d', '宮詞', '宮词', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["內人曉起怯春寒，輕揭珠簾看牡丹。","一把柳絲收不得，和風搭在玉欄杆。"]', '["內人晓起怯春寒，轻揭珠簾看牡丹。","一把柳絲收不得，和风搭在玉欄杆。"]', '诗', 'shi', '', NULL, '宮詞 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74073bf-2610-4bb4-98bc-0bc1cb867265', '句', '句', 'dfd1a25f-acb4-4295-b9e3-eb41e0ba58c2', '唐', '["屋面盡生人耳朵，籬頭多是老翁鬚。","平分造化雙苞去，拆破春風兩面開。","雲路半開千里月，洞門斜掩一天春。","鑿開青帝春風國，移下姮娥夜月樓。","珠璣影冷偏黏草，蘭麝香濃却損花。","山色曉堆羅黛雨，草梢春戛麝香風。","衰蘭寂寞含愁綠，小杏妖嬈弄色紅。","旁搜水脉湘心滿，遍揭泉根梵底通。","水□滴殘青□瘦，石脂傾盡白雲空。","深浦送回芳草日，急灘牽斷綠楊風。","藕梢逆入銀塘裏，蘋迹潛來玉井中。","敗菊籬疎臨野渡，落梅村冷隔江楓。","剪開淨澗分苗稼，劃破漣漪下釣筒。"]', '["屋面尽生人耳朵，籬头多是老翁鬚。","平分造化雙苞去，拆破春风兩面开。","云路半开千里月，洞门斜掩一天春。","鑿开青帝春风国，移下姮娥夜月楼。","珠璣影冷偏黏草，蘭麝香濃却損花。","山色晓堆羅黛雨，草梢春戛麝香风。","衰蘭寂寞含愁綠，小杏妖嬈弄色紅。","旁搜水脉湘心满，遍揭泉根梵底通。","水□滴殘青□瘦，石脂傾尽白云空。","深浦送回芳草日，急灘牽斷綠楊风。","藕梢逆入銀塘裏，蘋迹潛来玉井中。","敗菊籬疎臨野渡，落梅村冷隔江楓。","剪开淨澗分苗稼，劃破漣漪下釣筒。"]', '诗', 'shi', '', NULL, '句 徐仲雅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2360eb86-9864-4e25-83e5-e2ed2b8ae6c1', '分水嶺', '分水嶺', 'b501293e-a937-4f05-870f-2721e4dccb1b', '唐', '["前賢功及物，禹後杳難儔。","不改古今色，平分南北流。","寒衝山影岸，清繞荻花洲。","盡是朝宗去，潺潺早晚休。"]', '["前賢功及物，禹後杳难儔。","不改古今色，平分南北流。","寒衝山影岸，清繞荻花洲。","尽是朝宗去，潺潺早晚休。"]', '诗', 'shi', '', NULL, '分水嶺 伍彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69b9031-5112-45e3-96b0-1a15d2f5206a', '句', '句', 'b501293e-a937-4f05-870f-2721e4dccb1b', '唐', '["稚子出看莎徑沒，漁翁來報竹橋流。","蹤跡未辭鴛鷺客，夢魂先到鷓鴣村。"]', '["稚子出看莎徑沒，漁翁来報竹橋流。","蹤跡未辞鴛鷺客，梦魂先到鷓鴣村。"]', '诗', 'shi', '', NULL, '句 伍彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea19971f-2e6d-440d-8bd7-3e9aeb8ec62a', '留宿廖融山齋', '留宿廖融山斋', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["清和春尚在，歡醉日何長。","谷鳥隨柯轉，庭花奪酒香。","初晴巖翠滴，向晚樹陰涼。","別有堪吟處，相留宿草堂。"]', '["清和春尚在，歡醉日何长。","谷鸟隨柯轉，庭花奪酒香。","初晴巖翠滴，向晚樹陰涼。","別有堪吟处，相留宿草堂。"]', '诗', 'shi', '', NULL, '留宿廖融山齋 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15609049-0152-4bfc-aca7-d5218dc8662c', '句', '句', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["新霜染楓葉，皎月借蘆花。","廢宅寒塘水，荒墳宿草煙。"]', '["新霜染楓葉，皎月借蘆花。","廢宅寒塘水，荒墳宿草煙。"]', '诗', 'shi', '', NULL, '句 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfd526d-c8f9-4afd-8abc-fa3fa170b6d4', '登祝融峰', '登祝融峰', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["草疊到孤頂，身齊高鳥翔。","勢疑撞翼軫，翠欲滴瀟湘。","雲濕幽崖滑，風梳古木香。","晴空聊縱目，杳杳極窮荒。"]', '["草叠到孤頂，身齊高鸟翔。","勢疑撞翼軫，翠欲滴瀟湘。","云濕幽崖滑，风梳古木香。","晴空聊縱目，杳杳極窮荒。"]', '诗', 'shi', '', NULL, '登祝融峰 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4468744-a0f9-40f5-b244-ae4fc19c1a7e', '懷翁宏', '懷翁宏', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["獨夜思君切，無人知此情。","滄州歸未得，華髮別來生。","孤館木初落，高空月正明。","遠書多隔歲，獨念沒前程。"]', '["独夜思君切，無人知此情。","滄州归未得，华髮別来生。","孤館木初落，高空月正明。","远书多隔歲，独念沒前程。"]', '诗', 'shi', '', NULL, '懷翁宏 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b32977ae-1a76-412c-b360-4a430274884c', '聽琴', '听琴', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["拂塵開素匣，有客獨傷時。","古調俗不樂，正聲君自知。","寒泉出澗澀，老檜倚風悲。","縱有來聽者，誰堪繼子期。"]', '["拂塵开素匣，有客独傷时。","古調俗不乐，正声君自知。","寒泉出澗澀，老檜倚风悲。","縱有来听者，誰堪繼子期。"]', '诗', 'shi', '', NULL, '聽琴 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6bf7a7-90ec-4dae-9fdc-7c2e41ec35c2', '哭李韶', '哭李韶', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["韶也命何奇，生前與世違。","貧棲古梵剎，終著舊麻衣。","雅句僧抄遍，孤墳客弔稀。","故園今孰在，應見夢中歸。"]', '["韶也命何奇，生前與世違。","貧棲古梵剎，終著旧麻衣。","雅句僧抄遍，孤墳客弔稀。","故园今孰在，應见梦中归。"]', '诗', 'shi', '', NULL, '哭李韶 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc52b54-4019-4988-895c-e29c06f787a5', '題鄧真人遺址', '題鄧真人遺址', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["三千功滿仙昇去，留得山前舊隱基。","但見白雲長掩映，不知浮世幾興衰。","松稍風觸霓旌動，椶葉霜霑鶴翅垂。","近代無人尋異事，野泉噴月瀉秋池。"]', '["三千功满仙昇去，留得山前旧隐基。","但见白云长掩映，不知浮世幾兴衰。","松稍风觸霓旌动，椶葉霜霑鹤翅垂。","近代無人尋異事，野泉噴月瀉秋池。"]', '诗', 'shi', '', NULL, '題鄧真人遺址 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5153f37a-4253-4ebd-b17b-db25a2191718', '句', '句', '42a638a4-a660-4382-8931-63c43e7254de', '唐', '["伴行惟瘦鶴，尋步入深雲。"]', '["伴行惟瘦鹤，尋步入深云。"]', '诗', 'shi', '', NULL, '句 王元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b00c212-998f-4b80-a789-09942c84b0a7', '謝翁宏以詩百篇見示', '謝翁宏以诗百篇见示', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["高奇一百篇，造化見工全。","積思遊滄海，冥搜入洞天。","神珠迷罔象，端玉匪雕鐫。","休嘆不得力，離騷千古傳。"]', '["高奇一百篇，造化见工全。","積思游滄海，冥搜入洞天。","神珠迷罔象，端玉匪雕鐫。","休嘆不得力，離騷千古傳。"]', '诗', 'shi', '', NULL, '謝翁宏以詩百篇見示 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55549b3f-ae3b-41aa-88f6-e1ee29c9f206', '贈天台逸人', '贈天台逸人', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["移檜托禪子，攜家上赤城。","拂琴天籟寂，欹枕海濤生。","雲白寒峰晚，鳥歌春谷晴。","又聞求桂檝，載月十洲行。"]', '["移檜托禪子，携家上赤城。","拂琴天籟寂，欹枕海濤生。","云白寒峰晚，鸟歌春谷晴。","又闻求桂檝，載月十洲行。"]', '诗', 'shi', '', NULL, '贈天台逸人 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b88494f5-b7ac-4cb3-a35d-4a705e665835', '古檜', '古檜', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["何人見植初，老樹梵王居。","山鬼暗棲托，樵夫難破除。","聲高秋漢迥，影倒月潭虛。","盡日無僧倚，清風長有餘。"]', '["何人见植初，老樹梵王居。","山鬼暗棲托，樵夫难破除。","声高秋漢迥，影倒月潭虛。","尽日無僧倚，清风长有餘。"]', '诗', 'shi', '', NULL, '古檜 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('211fa2a2-c8b4-4c5b-82c6-f95e92472372', '題伍彬屋壁', '題伍彬屋壁', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["圓塘綠水平，魚躍紫蓴生。","要路貧無力，深村老退耕。","犢隨原草遠，蛙傍塹籬鳴。","撥櫂茶川去，初逢穀雨晴。"]', '["圓塘綠水平，鱼躍紫蓴生。","要路貧無力，深村老退耕。","犢隨原草远，蛙傍塹籬鳴。","撥櫂茶川去，初逢穀雨晴。"]', '诗', 'shi', '', NULL, '題伍彬屋壁 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62130af3-2d9c-4905-9b16-c5df2a2899f6', '夢仙謠', '梦仙謠', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["琪木扶疎繫辟邪，麻姑夜宴紫皇家。","銀河旌節搖波影，珠閣笙簫吸月華。","翠鳳引遊三島路，赤龍齊駕五雲車。","星稀猶倚虹橋立，擬就張騫搭漢槎。"]', '["琪木扶疎繫辟邪，麻姑夜宴紫皇家。","銀河旌節搖波影，珠閣笙簫吸月华。","翠鳳引游三島路，赤龙齊駕五云车。","星稀猶倚虹橋立，擬就張騫搭漢槎。"]', '诗', 'shi', '', NULL, '夢仙謠 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf07115-ac8d-4c81-b927-e2d5e671b216', '退宮妓', '退宮妓', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["神仙風格本難儔，曾從前皇翠輦遊。","紅躑躅繁金殿暖，碧芙蓉笑水宮秋。","寶箏鈿剝陰塵覆，錦帳香消畫燭幽。","一旦色衰歸故里，月明猶夢按梁州。"]', '["神仙风格本难儔，曾從前皇翠輦游。","紅躑躅繁金殿暖，碧芙蓉笑水宮秋。","寶箏鈿剝陰塵覆，錦帳香消畫燭幽。","一旦色衰归故里，月明猶梦按梁州。"]', '诗', 'shi', '', NULL, '退宮妓 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1e399e-4e4f-4346-b3f4-aad23d952f7b', '句', '句', '591f3ab0-45b6-47e0-ab6a-667e7a0d1137', '唐', '["圭竈先知曉，盆池別見天。","古寺尋僧飯，寒巖衣鹿裘。","雲穿擣藥屋，雪壓釣魚舟。"]', '["圭竈先知晓，盆池別见天。","古寺尋僧飯，寒巖衣鹿裘。","云穿擣藥屋，雪壓釣鱼舟。"]', '诗', 'shi', '', NULL, '句 廖融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3519473-d47e-4849-8cb5-546599a0953b', '贈廖融', '贈廖融', '611cab53-8b6a-4421-896d-4cec83f6777b', '唐', '["病起正當秋閣迥，酒醒迎對夜濤寒。","爐中藥熟分僧飯，枕上琴閑借客彈。"]', '["病起正當秋閣迥，酒醒迎对夜濤寒。","爐中藥熟分僧飯，枕上琴闲借客彈。"]', '诗', 'shi', '', NULL, '贈廖融 王正己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f83fce7e-a8f3-453c-b217-3e76b04ea1ae', '句', '句', '611cab53-8b6a-4421-896d-4cec83f6777b', '唐', '["洗盂秋澗日華動，搗藥夜坐秋氣深。"]', '["洗盂秋澗日华动，捣藥夜坐秋氣深。"]', '诗', 'shi', '', NULL, '句 王正己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6711c65c-3dc9-4a48-bfe6-d5e2dfe66dac', '送廖融處士南遊', '送廖融处士南游', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["病臥瘴雲間，莓苔漬竹關。","孤吟牛渚月，老憶洞庭山。","壯志潛消盡，淳風竟未還。","今朝忽相遇，執手一開顏。"]', '["病臥瘴云间，莓苔漬竹关。","孤吟牛渚月，老憶洞庭山。","壯志潛消尽，淳风竟未還。","今朝忽相遇，執手一开顏。"]', '诗', 'shi', '', NULL, '送廖融處士南遊 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44bf70da-4f3b-4124-ba92-095ac3c016e1', '春殘', '春殘', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["又是春殘也，如何出翠幃。","落花人獨立，微雨燕雙飛。","寓目魂將斷，經年夢亦非。","那堪向愁夕，蕭颯暮蟬輝。"]', '["又是春殘也，如何出翠幃。","落花人独立，微雨燕雙飞。","寓目魂將斷，經年梦亦非。","那堪向愁夕，蕭颯暮蟬輝。"]', '诗', 'shi', '', NULL, '春殘 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cceebdfd-c751-4b3c-8ae9-1f77e182e83f', '秋殘', '秋殘', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["又是秋殘也，無聊意若何。","客程江外遠，歸思夜深多。","峴首飛黃葉，湘湄走白波。","仍聞漢都護，今歲合休戈。"]', '["又是秋殘也，無聊意若何。","客程江外远，归思夜深多。","峴首飞黄葉，湘湄走白波。","仍闻漢都護，今歲合休戈。"]', '诗', 'shi', '', NULL, '秋殘 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f66ba53-8574-4e34-b4f1-1cc8b7ec524e', '句', '句', 'a1d05118-24e3-4c82-827f-cd7965e5ee20', '唐', '["萬木橫秋裏，孤舟半夜猨。","漏光殘井甃，缺影背山椒。","風回山火斷，潮落岸冰高。"]', '["万木橫秋裏，孤舟半夜猨。","漏光殘井甃，缺影背山椒。","风回山火斷，潮落岸冰高。"]', '诗', 'shi', '', NULL, '句 翁宏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b83b81ec-247f-42dd-b890-97c672aa7a89', '過衡山贈廖處士', '過衡山贈廖处士', '6525a949-df72-47d0-a7e1-798c77972a53', '唐', '["未向漆園爲傲吏，定應明代作徵君。","傳家奕世無金玉，樂道經年有典墳。","帶雨小舟橫別澗，隔花幽犬吠深雲。","到頭終爲蒼生起，休戀耕煙楚水濆。"]', '["未向漆园爲傲吏，定應明代作徵君。","傳家奕世無金玉，乐道經年有典墳。","带雨小舟橫別澗，隔花幽犬吠深云。","到头終爲蒼生起，休戀耕煙楚水濆。"]', '诗', 'shi', '', NULL, '過衡山贈廖處士 張觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdbc2e99-1254-45ec-815d-9bfafc135a55', '竹枝詞二首 一', '竹枝词二首 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["門前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神鴉。"]', '["门前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神鴉。"]', '诗', 'shi', '', NULL, '竹枝詞二首 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4baa67a-4b44-43e8-8035-c0ffd46e860b', '竹枝詞二首 二', '竹枝词二首 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["亂繩千結絆人深，越羅萬丈表長尋。","楊柳在身垂意緒，藕花落盡見蓮心。"]', '["亂繩千結絆人深，越羅万丈表长尋。","楊柳在身垂意緒，藕花落尽见蓮心。"]', '诗', 'shi', '', NULL, '竹枝詞二首 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0877bcd-f8ae-4b1d-8e0f-41854b8ae5c6', '楊柳枝詞四首 一', '楊柳枝词四首 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["閶門風暖落花乾，飛遍江城雪不寒。","獨有晚來臨水驛，閑人多憑赤欄干。"]', '["閶门风暖落花乾，飞遍江城雪不寒。","独有晚来臨水驛，闲人多憑赤欄干。"]', '诗', 'shi', '', NULL, '楊柳枝詞四首 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d36ad41d-a989-4135-b64e-1f77a4026627', '楊柳枝詞四首 二', '楊柳枝词四首 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["有池有榭即濛濛，浸潤翻成長養功。","恰似有人長點檢，著行排立向春風。"]', '["有池有榭即濛濛，浸潤翻成长養功。","恰似有人长点檢，著行排立向春风。"]', '诗', 'shi', '', NULL, '楊柳枝詞四首 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b588be3-c7e7-45d4-ba24-01076e841854', '楊柳枝詞四首 三', '楊柳枝词四首 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["根柢雖然傍濁河，無妨終日近笙歌。","毿毿金帶誰堪比，還共黃鶯不較多。"]', '["根柢雖然傍濁河，無妨終日近笙歌。","毿毿金带誰堪比，還共黄鶯不較多。"]', '诗', 'shi', '', NULL, '楊柳枝詞四首 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf9bc7b-e420-4e63-9c3e-acf66a6b4497', '楊柳枝詞四首 四', '楊柳枝词四首 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["萬株枯槁怨亡隋，似弔吳臺各自垂。","好是淮陰明月裏，酒樓橫笛不勝吹。"]', '["万株枯槁怨亡隋，似弔吳台各自垂。","好是淮陰明月裏，酒楼橫笛不勝吹。"]', '诗', 'shi', '', NULL, '楊柳枝詞四首 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc308c6-36fd-4be3-9cd6-2014d484b745', '採蓮', '採蓮', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["菡萏香連十頃陂，小姑貪戲採蓮遲。","晚來弄水船頭濕，更脫紅裙裹鴨兒。"]', '["菡萏香連十頃陂，小姑貪戲採蓮遲。","晚来弄水船头濕，更脫紅裙裹鴨兒。"]', '诗', 'shi', '', NULL, '採蓮 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('715ce261-c362-4414-909b-4f5e3acde69a', '八拍蠻', '八拍蠻', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["孔雀尾拖金線長，怕人飛起入丁香。","越女沙頭爭拾翠，相呼歸去背斜陽。"]', '["孔雀尾拖金線长，怕人飞起入丁香。","越女沙头爭拾翠，相呼归去背斜陽。"]', '诗', 'shi', '', NULL, '八拍蠻 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b53b15-5d6f-4dab-9aa1-7e30a93474b4', '句', '句', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["晚廚烹淡菜，春杼種橦花。"]', '["晚廚烹淡菜，春杼種橦花。"]', '诗', 'shi', '', NULL, '句 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b56285-cbac-4d1a-ac48-8ac94f721ff3', '詠蒲鞋', '詠蒲鞋', '0f9c6b1d-3b4a-4a55-be09-85aa4040abd2', '唐', '["吳江浪浸白蒲春，越女初挑一樣新。","纔自繡窗離玉指，便隨羅襪上香塵。","石榴裙下從容久，玳瑁筵前整頓頻。","今日高樓鴛瓦上，不知拋擲是何人。"]', '["吳江浪浸白蒲春，越女初挑一樣新。","纔自繡窗離玉指，便隨羅襪上香塵。","石榴裙下從容久，玳瑁筵前整頓頻。","今日高楼鴛瓦上，不知拋擲是何人。"]', '诗', 'shi', '', NULL, '詠蒲鞋 劉章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25688791-c0d2-4122-99a3-c43f4a81ed74', '夜坐', '夜坐', '1098da5f-5cf9-48e3-b535-5ffde4c4424d', '唐', '["簾捲竹軒清，四鄰無語聲。","漏從吟裏轉，月自坐來明。","草木露華濕，衣裳寒氣生。","難逢知鑒者，空悅此時情。"]', '["簾捲竹軒清，四鄰無語声。","漏從吟裏轉，月自坐来明。","草木露华濕，衣裳寒氣生。","难逢知鑒者，空悅此时情。"]', '诗', 'shi', '', NULL, '夜坐 路洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0cbb5c-4d31-4233-9e47-33c62f382dcb', '荆臺道院', '荆台道院', '1dfeabeb-53a8-40ce-8401-82886826a13c', '唐', '["桑田一變賦歸來，爵祿焉能凂我哉。","黃犢依然花竹外，清風萬古凜荆臺。"]', '["桑田一变賦归来，爵祿焉能凂我哉。","黄犢依然花竹外，清风万古凜荆台。"]', '诗', 'shi', '', NULL, '荆臺道院 梁震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc774e43-41a8-4f2c-9403-0d2bc3b97af0', '寧州道中', '寧州道中', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["城枕蕭關路，胡兵日夕臨。","唯憑一炬火，以慰萬人心。","春老雪猶重，沙寒草不深。","如何驅匹馬，向此獨閑吟。"]', '["城枕蕭关路，胡兵日夕臨。","唯憑一炬火，以慰万人心。","春老雪猶重，沙寒草不深。","如何驱匹马，向此独闲吟。"]', '诗', 'shi', '', NULL, '寧州道中 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfeff78b-6dd5-4ac4-b3e4-ac3d9d25a5c7', '尋九華王山人', '尋九华王山人', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["下馬扣荆扉，相尋春半時。","捫蘿盤磴險，疊石度溪危。","松夾莓苔逕，花藏薜荔籬。","臥雲情自逸，名姓厭人知。"]', '["下马扣荆扉，相尋春半时。","捫蘿盤磴險，叠石度溪危。","松夾莓苔逕，花藏薜荔籬。","臥云情自逸，名姓厭人知。"]', '诗', 'shi', '', NULL, '尋九華王山人 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f775508-c849-4a82-8144-778a07957286', '金陵逢張喬', '金陵逢張喬', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["殊鄉會面時，辛苦兩情知。","有志年空過，無媒命共奇。","吟餘春漏急，語舊酒巡遲。","天爵如堪倚，休驚鬢上絲。"]', '["殊乡會面时，辛苦兩情知。","有志年空過，無媒命共奇。","吟餘春漏急，語旧酒巡遲。","天爵如堪倚，休驚鬢上絲。"]', '诗', 'shi', '', NULL, '金陵逢張喬 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6604b1d2-09eb-4e98-85f4-3a58e033552a', '送鄒尊師歸洞庭', '送鄒尊師归洞庭', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["衆島在波心，曾居舊隱林。","近聞飛檄急，轉憶臥雲深。","賣藥唯供酒，歸舟只載琴。","遙知明月夜，坐石自開襟。"]', '["衆島在波心，曾居旧隐林。","近闻飞檄急，轉憶臥云深。","賣藥唯供酒，归舟只載琴。","遙知明月夜，坐石自开襟。"]', '诗', 'shi', '', NULL, '送鄒尊師歸洞庭 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5326422-4669-4ebb-a98b-e82e8c0dcb69', '送日東僧遊天台', '送日东僧游天台', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["一瓶離日外，行指赤城中。","去自重雲下，來從積水東。","攀蘿躋石徑，挂錫憩松風。","迴首雞林道，唯應夢想通。"]', '["一瓶離日外，行指赤城中。","去自重云下，来從積水东。","攀蘿躋石徑，挂錫憩松风。","迴首雞林道，唯應梦想通。"]', '诗', 'shi', '', NULL, '送日東僧遊天台 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('472a45e3-d501-4c0c-8baf-694a965b9948', '題甘露寺', '題甘露寺', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["高殿拂雲霓，登臨想虎溪。","風勻帆影衆，煙亂鳥行迷。","北倚波濤闊，南窺井邑低。","滿城塵漠漠，隔岸草萋萋。","虛閣延秋磐，澄江響暮鼙。","客心還惜去，新月挂樓西。"]', '["高殿拂云霓，登臨想虎溪。","风勻帆影衆，煙亂鸟行迷。","北倚波濤闊，南窺井邑低。","满城塵漠漠，隔岸草萋萋。","虛閣延秋磐，澄江响暮鼙。","客心還惜去，新月挂楼西。"]', '诗', 'shi', '', NULL, '題甘露寺 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe665d82-69e7-478d-a14b-c722edc600ca', '送張相公出征', '送張相公出征', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["得意在當年，登壇秉國權。","漢推周勃重，晉讓趙宣賢。","儒德尼丘降，兵鈐太白傳。","援毫飛鳳藻，發匣吼龍泉。","歷火金難耗，零霜桂益堅。","從來稱玉潔，此更讓朱妍。","鴛鷺臻門下，貔貅擁帳前。","去知清朔漠，行不費陶甄。","獻畫符中旨，推誠契上玄。","願將班固筆，書頌勒燕然。"]', '["得意在當年，登壇秉国權。","漢推周勃重，晉讓趙宣賢。","儒德尼丘降，兵鈐太白傳。","援毫飞鳳藻，發匣吼龙泉。","歷火金难耗，零霜桂益堅。","從来稱玉潔，此更讓朱妍。","鴛鷺臻门下，貔貅擁帳前。","去知清朔漠，行不費陶甄。","獻畫符中旨，推誠契上玄。","願將班固笔，书頌勒燕然。"]', '诗', 'shi', '', NULL, '送張相公出征 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b1a65f6-ce42-4e58-9d11-fbb5f4a9fbc9', '題鄭山人郊居', '題鄭山人郊居', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["谷口今逢避世才，入門瀟灑絕塵埃。","漁舟下釣乘風去，藥醞留賓待月開。","數片石從青嶂得，一條泉自白雲來。","竹軒相對無言語，盡日南山不欲迴。"]', '["谷口今逢避世才，入门瀟灑絕塵埃。","漁舟下釣乘风去，藥醞留賓待月开。","數片石從青嶂得，一條泉自白云来。","竹軒相对無言語，尽日南山不欲迴。"]', '诗', 'shi', '', NULL, '題鄭山人郊居 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f121b3-ce20-48eb-ab67-2f5aeaf37617', '題宣州延慶寺益公院', '題宣州延慶寺益公院', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["嘿坐能除萬種情，臘高兼有賜衣榮。","講經舊說傾朝聽，登殿曾聞降輦迎。","幽逕北連千嶂碧，虛窗東望一川平。","長年門外無塵客，時見元戎駐斾旌。"]', '["嘿坐能除万種情，臘高兼有賜衣榮。","講經旧说傾朝听，登殿曾闻降輦迎。","幽逕北連千嶂碧，虛窗东望一川平。","长年门外無塵客，时见元戎駐斾旌。"]', '诗', 'shi', '', NULL, '題宣州延慶寺益公院 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0d93bf-937d-419a-8124-d69b874c2852', '寄當陽袁皓明府', '寄當陽袁皓明府', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["高人爲縣在南京，竹遶琴堂水遶城。","地古既資攜酒興，務閑偏長看山情。","松軒待月僧同坐，藥圃尋花鶴伴行。","百里甚堪留惠愛，莫教空說魯恭名。"]', '["高人爲縣在南京，竹遶琴堂水遶城。","地古既資携酒兴，務闲偏长看山情。","松軒待月僧同坐，藥圃尋花鹤伴行。","百里甚堪留惠愛，莫教空说魯恭名。"]', '诗', 'shi', '', NULL, '寄當陽袁皓明府 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a27ad4fa-825a-41ee-9bf5-4a606879b430', '送杜郎中入茶山修貢', '送杜郎中入茶山修貢', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["一道澄瀾徹底清，仙郎輕棹出重城。","採蘋虛得當時稱，述職那同此日榮。","劍戟步經高障黑，綺羅光動百花明。","謝公攜妓東山去，何似乘春奉昭行。"]', '["一道澄瀾徹底清，仙郎轻棹出重城。","採蘋虛得當时稱，述職那同此日榮。","劍戟步經高障黑，綺羅光动百花明。","謝公携妓东山去，何似乘春奉昭行。"]', '诗', 'shi', '', NULL, '送杜郎中入茶山修貢 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994a97c9-d9ae-4e87-ba69-2c71b2f1ec99', '送鄭谷', '送鄭谷', '2d0cd002-9c9b-46ec-b583-90bafff0bb79', '唐', '["春江瀲瀲清且急，春雨濛濛密復疎。","一曲狂歌兩行淚，送君兼寄故鄉書。"]', '["春江瀲瀲清且急，春雨濛濛密复疎。","一曲狂歌兩行泪，送君兼寄故乡书。"]', '诗', 'shi', '', NULL, '送鄭谷 楊夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24295bb5-bc88-483f-8832-61c3492962a5', '自敘', '自敘', '9dcb8e11-308f-4714-8021-6f36de08c260', '唐', '["中劍斫耳缺，被箭射胛過。","爲將須有膽，有膽即無賈。"]', '["中劍斫耳缺，被箭射胛過。","爲將須有膽，有膽即無賈。"]', '诗', 'shi', '', NULL, '自敘 杜建徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f096b926-50af-4ea6-9476-3e38e9d91046', '游西湖', '游西湖', 'fe311cf0-2263-4399-b325-7c98fec9d747', '唐', '["□□□□□□□，菰米蘋花似故鄉。","不是不歸歸未得，好風明月一思量。"]', '["□□□□□□□，菰米蘋花似故乡。","不是不归归未得，好风明月一思量。"]', '诗', 'shi', '', NULL, '游西湖 沈韜文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a7ffa4-dd17-492e-9a67-219ccf0d6797', '贈和龍妙空禪師', '贈和龙妙空禪師', 'a3107403-467c-44ce-b233-14936aed6b8b', '唐', '["白面山南靈慶院，茅齋道者雪峰禪。","只棲雲樹兩三畝，不下煙蘿四五年。","猨鳥認聲呼喚易，龍神降伏住持堅。","誰知今日秋江畔，獨步醫王闡法筵。"]', '["白面山南靈慶院，茅斋道者雪峰禪。","只棲云樹兩三畝，不下煙蘿四五年。","猨鸟認声呼喚易，龙神降伏住持堅。","誰知今日秋江畔，独步醫王闡法筵。"]', '诗', 'shi', '', NULL, '贈和龍妙空禪師 王繼勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43592b95-2043-41f6-aa40-20302d19006d', '題建造寺', '題建造寺', 'a3107403-467c-44ce-b233-14936aed6b8b', '唐', '["曾看畫圖勞健羨，如今親見畫猶麄。","減除天半石初泐，欠却幾株松未枯。","題像閣人漁浦叟，集生臺鳥謝城烏。","我來一聽支公論，自是吾身幻得吾。"]', '["曾看畫圖勞健羨，如今親见畫猶麄。","減除天半石初泐，欠却幾株松未枯。","題像閣人漁浦叟，集生台鸟謝城烏。","我来一听支公論，自是吾身幻得吾。"]', '诗', 'shi', '', NULL, '題建造寺 王繼勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5f8013-cae3-4b86-b794-4621760aa0c2', '句', '句', 'a3107403-467c-44ce-b233-14936aed6b8b', '唐', '["掃石雲隨帚，耕山鳥傍人。"]', '["掃石云隨帚，耕山鸟傍人。"]', '诗', 'shi', '', NULL, '句 王繼勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fcd646-dfca-408b-b751-38a0e6f7db44', '和贈和龍妙空禪師', '和贈和龙妙空禪師', '862855c5-0742-4b6a-9a5e-df339218e2fc', '唐', '["翰林遺跡鏡潭前，孤峭高僧此處禪。","出爲信門興化日，坐當吾國太平年。","身同瑩澈尼珠淨，語並鋒鋩慧劒堅。","道果已圓名已遂，即看千匝遶香筵。"]', '["翰林遺跡镜潭前，孤峭高僧此处禪。","出爲信门兴化日，坐當吾国太平年。","身同瑩澈尼珠淨，語並鋒鋩慧劒堅。","道果已圓名已遂，即看千匝遶香筵。"]', '诗', 'shi', '', NULL, '和贈和龍妙空禪師 夏鴻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd73268-dd29-4948-823b-3e659b372901', '題青草湖神祠', '題青草湖神祠', '3c92b38b-e75c-4e5c-9d09-ac1166ae873d', '唐', '["壞牆風雨幾經春，草色盈庭一座塵。","自是神明無感應，盛衰何得却由人。"]', '["壞牆风雨幾經春，草色盈庭一座塵。","自是神明無感應，盛衰何得却由人。"]', '诗', 'shi', '', NULL, '題青草湖神祠 劉山甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d98bf0-16c0-44ba-a264-09d3f6e9b906', '漢宗廟樂舞辭', '漢宗廟乐舞辞', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["高廟明靈再啓圖，金根玉輅幸神都。","巢阿丹鳳銜書命，入昴飛星獻寶符。","正撫薰弦娛赤子，忽登仙駕泣蒼梧。","薦櫻鶴館笳簫咽，酌鬯金楹劒珮趨。","星俎雲罍兼魯禮，朱干象箾雜巴渝。","氤氳龍麝交青瑣，髣髴錫鑾下蘂珠。","薦豆奉觴親玉几，配天合祖耀璿樞。","受釐飲酒皇歡洽，仰俟餘靈泰九區。"]', '["高廟明靈再啓圖，金根玉輅幸神都。","巢阿丹鳳銜书命，入昴飞星獻寶符。","正撫薰弦娛赤子，忽登仙駕泣蒼梧。","薦櫻鹤館笳簫咽，酌鬯金楹劒珮趨。","星俎云罍兼魯禮，朱干象箾杂巴渝。","氤氳龙麝交青瑣，髣髴錫鑾下蘂珠。","薦豆奉觴親玉几，配天合祖耀璿樞。","受釐饮酒皇歡洽，仰俟餘靈泰九區。"]', '诗', 'shi', '', NULL, '漢宗廟樂舞辭 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31427f17-532e-4aa3-8c52-a70ec72b5588', '農家', '農家', 'afdb2614-9c04-4f66-ad74-f3485d89490d', '唐', '["夜半呼兒趁曉耕，羸牛無力漸艱行。","時人不識農家苦，將謂田中穀自生。"]', '["夜半呼兒趁晓耕，羸牛無力漸艱行。","时人不識農家苦，將謂田中穀自生。"]', '诗', 'shi', '', NULL, '農家 顏仁郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90f799a-ec06-4064-bcd3-e58c0f4e9240', '山居', '山居', 'afdb2614-9c04-4f66-ad74-f3485d89490d', '唐', '["栢樹松陰覆竹齋，罷燒藥竈縱高懷。","世間應少山間景，雲遶青松水遶堦。"]', '["栢樹松陰覆竹斋，罷燒藥竈縱高懷。","世间應少山间景，云遶青松水遶堦。"]', '诗', 'shi', '', NULL, '山居 顏仁郁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0754a2f4-407d-4f84-9ec6-23eeca619c9e', '春日寓感', '春日寓感', 'c0a29737-30d9-4148-8ae9-245658078c5a', '唐', '["兩衙前後訟堂清，軟錦披袍擁鼻行。","雨後綠苔侵履跡，春深紅杏鎖鶯聲。","因攜久醞松醪酒，自煮新抽竹筍羹。","也解爲詩也爲政，儂家何似謝宣城。"]', '["兩衙前後訟堂清，軟錦披袍擁鼻行。","雨後綠苔侵履跡，春深紅杏鎖鶯声。","因携久醞松醪酒，自煮新抽竹筍羹。","也解爲诗也爲政，儂家何似謝宣城。"]', '诗', 'shi', '', NULL, '春日寓感 王延彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38412bc-17aa-4870-b73b-e823ab8f77d4', '哭徐夤', '哭徐夤', 'c0a29737-30d9-4148-8ae9-245658078c5a', '唐', '["延壽溪頭歎逝波，古今人事半銷磨。","昔除正字今何在，所謂人生能幾何。"]', '["延壽溪头歎逝波，古今人事半銷磨。","昔除正字今何在，所謂人生能幾何。"]', '诗', 'shi', '', NULL, '哭徐夤 王延彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a88977-cdaf-4b98-a354-df1455f62106', '塞上 一', '塞上 一', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["秋風漢北雁飛天，單騎那堪遶賀蘭。","磧暗更無巖樹影，地平時有野燒瘢。","貂披寒色和衣冷，劒佩胡霜隔匣寒。","早晚橫戈似飛尉，擁旄深入異田單。"]', '["秋风漢北雁飞天，單騎那堪遶賀蘭。","磧暗更無巖樹影，地平时有野燒瘢。","貂披寒色和衣冷，劒佩胡霜隔匣寒。","早晚橫戈似飞尉，擁旄深入異田單。"]', '诗', 'shi', '', NULL, '塞上 一 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b6343ba-5951-4501-a0f9-4d3eb18bea8e', '塞上 二', '塞上 二', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["鉢略城邊日欲西，遊人却憶舊山歸。","牛羊集水煙黏步，鵰鶚盤空雪滿圍。","獵騎靜逢邊氣薄，戍樓寒對暮煙微。","橫行總是男兒事，早晚重來似漢飛。"]', '["鉢略城邊日欲西，游人却憶旧山归。","牛羊集水煙黏步，鵰鶚盤空雪满圍。","獵騎静逢邊氣薄，戍楼寒对暮煙微。","橫行總是男兒事，早晚重来似漢飞。"]', '诗', 'shi', '', NULL, '塞上 二 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a18180f-bc27-4a22-b633-56912b5f4845', '贈索處士', '贈索处士', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["不將桂子種諸天，長得尋君水石邊。","玄豹夜寒和霧隱，驪龍春暖抱珠眠。","山中宰相陶弘景，洞裏真人葛稚川。","一度相思一惆悵，水寒煙澹落花前。"]', '["不將桂子種諸天，长得尋君水石邊。","玄豹夜寒和霧隐，驪龙春暖抱珠眠。","山中宰相陶弘景，洞裏真人葛稚川。","一度相思一惆悵，水寒煙澹落花前。"]', '诗', 'shi', '', NULL, '贈索處士 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08421bc-b993-42bd-9293-84de33af3dde', '別雒下一二知己', '別雒下一二知己', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["金鼎光輝照雪袍，雒陽春夢憶波濤。","塵埃滿眼人情異，風雨前程馬足勞。","接塞峨眉通蜀險，過山仙掌倚秦高。","別來無限幽求子，應笑區區味六韜。"]', '["金鼎光輝照雪袍，雒陽春梦憶波濤。","塵埃满眼人情異，风雨前程马足勞。","接塞峨眉通蜀險，過山仙掌倚秦高。","別来無限幽求子，應笑區區味六韜。"]', '诗', 'shi', '', NULL, '別雒下一二知己 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79883e4d-9f24-4ec1-8116-00328b108dce', '約張處士遊梁', '約張处士游梁', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["莫學區區老一經，夷門關吏舊書生。","晉朝滅後無中散，韓國亡來絕上卿。","龍變洞中千谷冷，劒橫天外八風清。","好攜長策干時去，免逐漁樵度太平。"]', '["莫学區區老一經，夷门关吏旧书生。","晉朝滅後無中散，韓国亡来絕上卿。","龙变洞中千谷冷，劒橫天外八风清。","好携长策干时去，免逐漁樵度太平。"]', '诗', 'shi', '', NULL, '約張處士遊梁 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11697ae-8d15-4e35-bbbc-c9dd9f227a4f', '送友人歸青社', '送友人归青社', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["鵰鶚途程在碧天，綵衣東去復何言。","二千賓客舊知己，十二山河新故園。","吟看桂生溪月上，醉聽鯤化海濤翻。","好期聖代重相見，莫學袁生老竹軒。"]', '["鵰鶚途程在碧天，綵衣东去复何言。","二千賓客旧知己，十二山河新故园。","吟看桂生溪月上，醉听鯤化海濤翻。","好期聖代重相见，莫学袁生老竹軒。"]', '诗', 'shi', '', NULL, '送友人歸青社 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c16cc5-de29-47ea-9ccc-63b2fcc2580b', '送丁道士歸南中', '送丁道士归南中', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["孤雲無定鶴辭巢，自負焦桐不說勞。","服藥幾年期碧落，驗符何處呪丹毫。","子陵山曉紅雲密，青草湖平雪浪高。","從此人稀見蹤跡，還應選地種仙桃。"]', '["孤云無定鹤辞巢，自負焦桐不说勞。","服藥幾年期碧落，驗符何处呪丹毫。","子陵山晓紅云密，青草湖平雪浪高。","從此人稀见蹤跡，還應選地種仙桃。"]', '诗', 'shi', '', NULL, '送丁道士歸南中 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d956b477-89b3-48dc-8064-8cfb1dced543', '月夜懷寄友人', '月夜懷寄友人', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["劒氣徒勞望斗牛，故人別後阻仙舟。","殘春謾道深傾酒，好月那堪獨上樓。","何處是非隨馬足，由來得喪白人頭。","清風未許重攜手，幾度高吟寄水流。"]', '["劒氣徒勞望斗牛，故人別後阻仙舟。","殘春謾道深傾酒，好月那堪独上楼。","何处是非隨马足，由来得喪白人头。","清风未許重携手，幾度高吟寄水流。"]', '诗', 'shi', '', NULL, '月夜懷寄友人 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8652e814-2fda-4e22-9d08-753e0e01e8ee', '閑居寄陳山人', '闲居寄陳山人', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["閑居何處得閑名，坐掩衡茅損性靈。","破夢曉鐘聞竹寺，沁心秋雨浸莎庭。","甕邊難負千杯綠，海上終眠萬仞青。","珍重先生全太古，應看名利似浮[萍]。"]', '["闲居何处得闲名，坐掩衡茅損性靈。","破梦晓鐘闻竹寺，沁心秋雨浸莎庭。","甕邊难負千杯綠，海上終眠万仞青。","珍重先生全太古，應看名利似浮[萍]。"]', '诗', 'shi', '', NULL, '閑居寄陳山人 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f0a4d8-c0b2-480a-9f87-78504832fc26', '憶南中', '憶南中', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["碧江頭與白雲門，別後秋霜點鬢根。","長記學禪青石寺，最思共醉落花村。","林間竹有湘妃淚，窗外禽多杜宇魂。","未棹扁舟重回首，采薇收橘不堪論。"]', '["碧江头與白云门，別後秋霜点鬢根。","长記学禪青石寺，最思共醉落花村。","林间竹有湘妃泪，窗外禽多杜宇魂。","未棹扁舟重回首，采薇收橘不堪論。"]', '诗', 'shi', '', NULL, '憶南中 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4109bc76-ad12-4d37-8fd0-459c3599f208', '寄友人', '寄友人', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["病多慵引架書看，官職無才思已闌。","穴鳳瑞時來却易，人龍別後見何難。","琴樽風月閑生計，金玉松筠舊歲寒。","早晚煙村碧江畔，挂罾重對蓼花灘。"]', '["病多慵引架书看，官職無才思已闌。","穴鳳瑞时来却易，人龙別後见何难。","琴樽风月闲生計，金玉松筠旧歲寒。","早晚煙村碧江畔，挂罾重对蓼花灘。"]', '诗', 'shi', '', NULL, '寄友人 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954fbc7a-2615-42b8-94fa-49d4158a5a12', '別江上一二友生', '別江上一二友生', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["國風千載務重華，須逐浮雲背若耶。","無地可歸堪種玉，有天教上且乘槎。","白綸巾卸蘇門月，紅錦衣裁御苑花。","他日成都却回首，東山看取謝鯤家。"]', '["国风千載務重华，須逐浮云背若耶。","無地可归堪種玉，有天教上且乘槎。","白綸巾卸蘇门月，紅錦衣裁御苑花。","他日成都却回首，东山看取謝鯤家。"]', '诗', 'shi', '', NULL, '別江上一二友生 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed040e9-0c8d-4370-a5ed-63002d4568f6', '寄岐山林逢吉明府', '寄岐山林逢吉明府', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["岐山高與隴山連，製錦無私服晏眠。","鸚鵡語中分百里，鳳凰聲裏過三年。","秦無舊俗雲煙媚，周有遺風父老賢。","莫役生靈種楊柳，一枝枝折灞橋邊。"]', '["岐山高與隴山連，製錦無私服晏眠。","鸚鵡語中分百里，鳳凰声裏過三年。","秦無旧俗云煙媚，周有遺风父老賢。","莫役生靈種楊柳，一枝枝折灞橋邊。"]', '诗', 'shi', '', NULL, '寄岐山林逢吉明府 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb845bb5-2ae9-4d16-bef1-a49d27bce731', '感懷呈所知', '感懷呈所知', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["十年流落賦歸鴻，誰傍昏衢駕燭龍。","竹屋亂煙思梓澤，酒家疎雨夢臨邛。","千年別恨調琴懶，一片年光覽鏡慵。","早晚休歌白石爛，放教歸去臥羣峰。"]', '["十年流落賦归鴻，誰傍昏衢駕燭龙。","竹屋亂煙思梓澤，酒家疎雨梦臨邛。","千年別恨調琴懶，一片年光覽镜慵。","早晚休歌白石爛，放教归去臥羣峰。"]', '诗', 'shi', '', NULL, '感懷呈所知 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd8057a1-0811-46b9-adc7-a53bd6af094e', '江上聞笛', '江上闻笛', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["誰爲梅花怨未平，一聲高喚百龍驚。","風當閶闔庭初靜，月在姑蘇秋正明。","曲盡綠楊涵野渡，管吹青玉動江城。","臨流不欲殷勤聽，芳草王孫舊有情。"]', '["誰爲梅花怨未平，一声高喚百龙驚。","风當閶闔庭初静，月在姑蘇秋正明。","曲尽綠楊涵野渡，管吹青玉动江城。","臨流不欲殷勤听，芳草王孫旧有情。"]', '诗', 'shi', '', NULL, '江上聞笛 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68dbfdcd-54c9-473e-b0f5-32775afabaac', '寄孟進士', '寄孟進士', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["依舊池邊草色芳，故人何處憶山陽。","書回科斗江帆暮，曲罷騶虞海樹蒼。","吟望曉煙思桂渚，醉依殘月夢餘杭。","別來南國知誰在，空對襜褕一斷腸。"]', '["依旧池邊草色芳，故人何处憶山陽。","书回科斗江帆暮，曲罷騶虞海樹蒼。","吟望晓煙思桂渚，醉依殘月梦餘杭。","別来南国知誰在，空对襜褕一斷腸。"]', '诗', 'shi', '', NULL, '寄孟進士 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e33ac15-1801-40e4-bc21-f49c2fb66a1f', '寄閻記室', '寄閻記室', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["織錦歌成下翠微，豈勞西去問搘機。","未開水府珠先見，不掘豐城劒自輝。","鼇逐玉蟾攀桂上，馬隨青帝踏花歸。","相逢半是雲霄客，應笑歌牛一布衣。"]', '["织錦歌成下翠微，豈勞西去问搘機。","未开水府珠先见，不掘豐城劒自輝。","鼇逐玉蟾攀桂上，马隨青帝踏花归。","相逢半是云霄客，應笑歌牛一布衣。"]', '诗', 'shi', '', NULL, '寄閻記室 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e751f62a-c733-4126-bd5b-ed000d4eea67', '幽居寄李祕書', '幽居寄李祕书', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["幾年帝里阻煙波，敢向明時叩角歌。","看盡好花春臥穩，醉殘紅日夜吟多。","印開夕照垂楊柳，畫破寒潭老芰荷。","昨夜前溪有龍鬬，石橋風雨少人過。"]', '["幾年帝里阻煙波，敢向明时叩角歌。","看尽好花春臥穩，醉殘紅日夜吟多。","印开夕照垂楊柳，畫破寒潭老芰荷。","昨夜前溪有龙鬬，石橋风雨少人過。"]', '诗', 'shi', '', NULL, '幽居寄李祕書 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9ed2e7-f3e1-47cb-b382-e0e1a8338eb7', '貽釣魚李處士', '貽釣鱼李处士', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["罷吟鸚鵡草芊芊，又泛鴛鴦水上天。","一棹冷涵楊柳雨，片帆香挂芰荷煙。","綠搖江澹萍離岸，紅點雲疎橘滿川。","何處邈將歸畫府，數莖紅蓼一漁船。"]', '["罷吟鸚鵡草芊芊，又泛鴛鴦水上天。","一棹冷涵楊柳雨，片帆香挂芰荷煙。","綠搖江澹萍離岸，紅点云疎橘满川。","何处邈將归畫府，數莖紅蓼一漁船。"]', '诗', 'shi', '', NULL, '貽釣魚李處士 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e595921f-d85b-41cb-ac74-fcacbb367e55', '河橋樓賦得羣公夜讌', '河橋楼賦得羣公夜讌', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["芙蓉簾幕扇秋紅，蠻府新郎夜讌同。","滿座馬融吹笛月，一樓張翰過江風。","杯黏紫酒金螺重，談轉琱璫玉麈空。","深荷良宵慰顦顇，德星池館在江東。"]', '["芙蓉簾幕扇秋紅，蠻府新郎夜讌同。","满座马融吹笛月，一楼張翰過江风。","杯黏紫酒金螺重，談轉琱璫玉麈空。","深荷良宵慰顦顇，德星池館在江东。"]', '诗', 'shi', '', NULL, '河橋樓賦得羣公夜讌 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6cb2d85-b8c5-4610-88a5-683111b70f01', '寄左先輩', '寄左先輩', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["狂歌白鹿上青天，何似蘭塘釣紫煙。","萬卷祖龍坑外物，一泓孫楚耳中泉。","翩翾蠻榼薰晴浦，轂轆魚車響夜船。","學取青蓮李居士，一生杯酒在神仙。"]', '["狂歌白鹿上青天，何似蘭塘釣紫煙。","万卷祖龙坑外物，一泓孫楚耳中泉。","翩翾蠻榼薰晴浦，轂轆鱼车响夜船。","学取青蓮李居士，一生杯酒在神仙。"]', '诗', 'shi', '', NULL, '寄左先輩 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f14490e-3ac2-4a00-bc12-244411457d72', '貽費道人', '貽費道人', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["誰如南浦傲煙霞，白葛衣青稱帽紗。","碧玉蜉蝣迎客酒，黃金轂轆釣魚車。","吟歌雲鳥歸樵谷，臥愛神仙入畫家。","他日鳳書何處覓，武陵煙樹半桃花。"]', '["誰如南浦傲煙霞，白葛衣青稱帽紗。","碧玉蜉蝣迎客酒，黄金轂轆釣鱼车。","吟歌云鸟归樵谷，臥愛神仙入畫家。","他日鳳书何处覓，武陵煙樹半桃花。"]', '诗', 'shi', '', NULL, '貽費道人 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cbc98b-de29-4682-96dc-6b745abf1a00', '寄許下前管記王侍御', '寄許下前管記王侍御', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["昔年南去得娛賓，頓遜杯前共好春。","螘泛羽觴蠻酒膩，鳳銜瑤句蜀牋新。","花憐遊騎紅隨轡，草戀征車碧遶輪。","別後青青鄭南陌，不知風月屬何人。"]', '["昔年南去得娛賓，頓遜杯前共好春。","螘泛羽觴蠻酒膩，鳳銜瑤句蜀牋新。","花怜游騎紅隨轡，草戀征车碧遶輪。","別後青青鄭南陌，不知风月屬何人。"]', '诗', 'shi', '', NULL, '寄許下前管記王侍御 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d03a8244-7fdf-4415-874c-85c8de64a49b', '秋日圃田送人隨計', '秋日圃田送人隨計', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["僕射陂前是傳郵，去程鵰鶚弄高秋。","吟拋芍藥裁詩圃，醉下茱萸飲酒樓。","向日迥飛駒皎皎，臨風誰和鹿呦呦。","明年二月仙山下，莫遣桃花逐水流。"]', '["僕射陂前是傳郵，去程鵰鶚弄高秋。","吟拋芍藥裁诗圃，醉下茱萸饮酒楼。","向日迥飞駒皎皎，臨风誰和鹿呦呦。","明年二月仙山下，莫遣桃花逐水流。"]', '诗', 'shi', '', NULL, '秋日圃田送人隨計 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38cbdfcd-fe34-4e15-b2e5-e2594156d018', '途次宿友人別墅', '途次宿友人別墅', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["千里崤函一夢勞，豈知雲館共蕭騷。","半簾綠透偎寒竹，一榻紅侵墜晚桃。","蠻酒客稀知味長，蜀琴風定覺弦高。","感君巖下閑招隱，細縷金盤鱠錯刀。"]', '["千里崤函一梦勞，豈知云館共蕭騷。","半簾綠透偎寒竹，一榻紅侵墜晚桃。","蠻酒客稀知味长，蜀琴风定覺弦高。","感君巖下闲招隐，細縷金盤鱠錯刀。"]', '诗', 'shi', '', NULL, '途次宿友人別墅 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d42eb3-a8e9-4fe7-a1a7-c527330cc62c', '春日期巢湖舊事', '春日期巢湖旧事', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["暖掠紅香燕燕飛，五雲仙珮曉相攜。","花開鸚鵡韋郎曲，竹亞虬龍白帝溪。","富貴萬場歸紫酒，是非千載逐芳泥。","不知多少開元事，露泣春叢向日低。"]', '["暖掠紅香燕燕飞，五云仙珮晓相携。","花开鸚鵡韋郎曲，竹亞虬龙白帝溪。","富貴万場归紫酒，是非千載逐芳泥。","不知多少开元事，露泣春叢向日低。"]', '诗', 'shi', '', NULL, '春日期巢湖舊事 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0403745c-78f8-4d78-9213-f00dd4ef2681', '再遊韋曲山寺', '再游韋曲山寺', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["鵲巖煙斷玉巢欹，罨畫春塘太白低。","馬踏翠開垂柳寺，人耕紅破落花蹊。","千年勝概咸原上，幾代荒涼繡嶺西。","碧吐紅芳舊行處，豈堪回首草萋萋。"]', '["鵲巖煙斷玉巢欹，罨畫春塘太白低。","马踏翠开垂柳寺，人耕紅破落花蹊。","千年勝概咸原上，幾代荒涼繡嶺西。","碧吐紅芳旧行处，豈堪回首草萋萋。"]', '诗', 'shi', '', NULL, '再遊韋曲山寺 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5931bd5-62a4-4bd1-b87f-d993d8e3c084', '寄徐拾遺', '寄徐拾遺', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["長竿一繫白龍吟，誰和騶虞發素琴。","野客碧雲魂易斷，故人芳草夢難尋。","天從補後星辰穩，海自潮來島嶼深。","好向明庭拾遺事，莫教玄豹老泉林。"]', '["长竿一繫白龙吟，誰和騶虞發素琴。","野客碧云魂易斷，故人芳草梦难尋。","天從補後星辰穩，海自潮来島嶼深。","好向明庭拾遺事，莫教玄豹老泉林。"]', '诗', 'shi', '', NULL, '寄徐拾遺 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a4a9d6-5dab-43f2-bd05-009dc5712b62', '秋宿湘江遇雨', '秋宿湘江遇雨', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["江上陰雲鎖夢魂，江邊深夜舞劉琨。","秋風萬里芙蓉國，暮雨千家薜荔村。","鄉思不堪悲橘柚，旅遊誰肯重王孫。","漁人相見不相問，長笛一聲歸島門。"]', '["江上陰云鎖梦魂，江邊深夜舞劉琨。","秋风万里芙蓉国，暮雨千家薜荔村。","乡思不堪悲橘柚，旅游誰肯重王孫。","漁人相见不相问，长笛一声归島门。"]', '诗', 'shi', '', NULL, '秋宿湘江遇雨 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc8b48a-691d-4af3-8155-28d22f5f0432', '貽南康陳處士陶', '貽南康陳处士陶', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["白玉堆邊蔣逕橫，空涵二十四灘聲。","老無征戰軒轅國，貧有茅茨帝舜城。","丹鳳晝飛羣木冷，一龍秋臥九江清。","時人莫笑非經濟，還待中原致太平。"]', '["白玉堆邊蔣逕橫，空涵二十四灘声。","老無征戰軒轅国，貧有茅茨帝舜城。","丹鳳晝飞羣木冷，一龙秋臥九江清。","时人莫笑非經濟，還待中原致太平。"]', '诗', 'shi', '', NULL, '貽南康陳處士陶 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527ad3af-c6b3-4d0b-9986-435da77e6041', '渭城春晚', '渭城春晚', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["秦樹朦朧春色微，香風煙煖樹依依。","邊城夜靜月初上，芳草路長人未歸。","折柳且堪吟晚檻，弄花何處醉殘暉。","釣鄉千里斷消息，滿目碧雲空自飛。"]', '["秦樹朦朧春色微，香风煙煖樹依依。","邊城夜静月初上，芳草路长人未归。","折柳且堪吟晚檻，弄花何处醉殘暉。","釣乡千里斷消息，满目碧云空自飞。"]', '诗', 'shi', '', NULL, '渭城春晚 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74acc08d-d1b6-415d-98ed-dd84959f28b4', '山中春晚寄賈員外', '山中春晚寄賈員外', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["不隨黃鶴起煙波，應笑無成返薜蘿。","看盡好花春臥穩，醉殘紅日夜吟多。","高添雅興松千尺，暗養清音竹數科。","珍重仙曹舊知己，往來星騎一相過。"]', '["不隨黄鹤起煙波，應笑無成返薜蘿。","看尽好花春臥穩，醉殘紅日夜吟多。","高添雅兴松千尺，暗養清音竹數科。","珍重仙曹旧知己，往来星騎一相過。"]', '诗', 'shi', '', NULL, '山中春晚寄賈員外 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b776fd4-28ac-4c6a-a84d-2babe0bbc17a', '貽淨居寺新及第', '貽淨居寺新及第', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["秋池雲下白蓮香，池上吟仙寄竹房。","閑頌國風文字古，靜消心火夢魂涼。","三春蓬島花無限，八月銀河路更長。","此境空門不曾有，從頭好語與醫王。"]', '["秋池云下白蓮香，池上吟仙寄竹房。","闲頌国风文字古，静消心火梦魂涼。","三春蓬島花無限，八月銀河路更长。","此境空门不曾有，從头好語與醫王。"]', '诗', 'shi', '', NULL, '貽淨居寺新及第 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051a88e1-e5db-4feb-a8d3-2b11d9f9ddef', '江邊秋夕', '江邊秋夕', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["千鍾紫酒薦菖蒲，松島蘭舟瀲灩居。","曲內橘香江客笛，字中嵐氣岳僧書。","吟期汗漫驅金虎，坐約丹青跨玉魚。","七色花虬一聲鶴，幾時乘興上清虛。"]', '["千鍾紫酒薦菖蒲，松島蘭舟瀲灩居。","曲內橘香江客笛，字中嵐氣岳僧书。","吟期汗漫驱金虎，坐約丹青跨玉鱼。","七色花虬一声鹤，幾时乘兴上清虛。"]', '诗', 'shi', '', NULL, '江邊秋夕 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a57110-6617-42c4-884f-bc1ee5591edb', '送僧中孚南歸', '送僧中孚南归', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["琵琶峽口月溪邊，玉乳頭佗憶舊川。","一錫冷涵蘭徑路，片帆香挂橘洲煙。","苔封石錦棲霞室，水迸衣珠噴玉蟬。","莫道翩翩去如夢，本來吟鳥在林泉。"]', '["琵琶峽口月溪邊，玉乳头佗憶旧川。","一錫冷涵蘭徑路，片帆香挂橘洲煙。","苔封石錦棲霞室，水迸衣珠噴玉蟬。","莫道翩翩去如梦，本来吟鸟在林泉。"]', '诗', 'shi', '', NULL, '送僧中孚南歸 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376f0416-146f-4c98-af12-b5dba587fd42', '江館秋夕', '江館秋夕', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["耿耿銀河鴈半橫，夢欹金碧轆轤輕。","滿窗謝練江風白，一枕齊紈海月明。","楊柳敗梢飛葉響，芰荷香柄折秋鳴。","誰人更唱陽關曲，牢落煙霞夢不成。"]', '["耿耿銀河鴈半橫，梦欹金碧轆轤轻。","满窗謝練江风白，一枕齊紈海月明。","楊柳敗梢飞葉响，芰荷香柄折秋鳴。","誰人更唱陽关曲，牢落煙霞梦不成。"]', '诗', 'shi', '', NULL, '江館秋夕 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9522df-c600-404e-a022-71045b77fff9', '秋夜同友人話舊', '秋夜同友人話旧', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["露下銀河鴈度頻，囊中壚火幾時真。","數莖白髮生浮世，一盞寒燈共故人。","雲外簟涼吟嶠月，島邊花暖釣江春。","何當歸去重攜手，依舊紅霞作近鄰。"]', '["露下銀河鴈度頻，囊中壚火幾时真。","數莖白髮生浮世，一盞寒灯共故人。","云外簟涼吟嶠月，島邊花暖釣江春。","何當归去重携手，依旧紅霞作近鄰。"]', '诗', 'shi', '', NULL, '秋夜同友人話舊 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df0c4e2-5e24-4021-aae3-b25b66129fd6', '古劍', '古劍', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["鑄時天匠待英豪，紫焰寒星匣倍牢。","三尺何年拂塵土，四溟今日絕波濤。","雄應垓下收蛇陣，滯想溪頭伴豹韜。","惜是真龍懶拋擲，夜來衝斗氣何高。"]', '["鑄时天匠待英豪，紫焰寒星匣倍牢。","三尺何年拂塵土，四溟今日絕波濤。","雄應垓下收蛇陣，滯想溪头伴豹韜。","惜是真龙懶拋擲，夜来衝斗氣何高。"]', '诗', 'shi', '', NULL, '古劍 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c586d8b2-d403-4237-88b5-b1337c6b48d9', '寄王侍御', '寄王侍御', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["鳥盡弓藏良可哀，誰知歸釣子陵臺。","鍊多不信黃金耗，吟苦須驚白髮催。","喘月吳牛知夜至，嘶風胡馬識秋來。","燕歌別後休惆悵，黍已成畦菊已開。"]', '["鸟尽弓藏良可哀，誰知归釣子陵台。","鍊多不信黄金耗，吟苦須驚白髮催。","喘月吳牛知夜至，嘶风胡马識秋来。","燕歌別後休惆悵，黍已成畦菊已开。"]', '诗', 'shi', '', NULL, '寄王侍御 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51fc6e1-c699-47a6-a71b-fc5e9d5845d8', '別何處士陵俊老', '別何处士陵俊老', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["三皇上人春夢醒，東侯老大麒麟生。","洞連龍穴全山冷，窗透鼇波盡室清。","計拙恥居巖麓老，氣狂慙與斗牛平。","誰人爲向青編上，直傍巢由寫一名。"]', '["三皇上人春梦醒，东侯老大麒麟生。","洞連龙穴全山冷，窗透鼇波尽室清。","計拙恥居巖麓老，氣狂慙與斗牛平。","誰人爲向青編上，直傍巢由寫一名。"]', '诗', 'shi', '', NULL, '別何處士陵俊老 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d761762-f5ee-4a31-af1c-718a4b839c63', '句', '句', 'ff6cf23b-5732-4221-9c9d-0067b57c72de', '唐', '["流水物情諳世態，落花春夢壓塵勞。","織檻錦紋苔乍結，墮書花印菊初殘。","光陰老去無成事，富貴不來爭奈何。","眠雲無限好知己，應笑不歸花滿樽。"]', '["流水物情諳世態，落花春梦壓塵勞。","织檻錦紋苔乍結，墮书花印菊初殘。","光陰老去無成事，富貴不来爭奈何。","眠云無限好知己，應笑不归花满樽。"]', '诗', 'shi', '', NULL, '句 譚用之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ead31d-ce9e-4854-b981-847252b4b3ee', '泊姑熟口', '泊姑熟口', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["杳杳金陵路，難禁欲斷魂。","雨晴山有態，風晚水無痕。","遠色千檣岸，愁聲一笛村。","如何遣懷抱，詩畢自開尊。"]', '["杳杳金陵路，难禁欲斷魂。","雨晴山有態，风晚水無痕。","远色千檣岸，愁声一笛村。","如何遣懷抱，诗畢自开尊。"]', '诗', 'shi', '', NULL, '泊姑熟口 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c53ed0-4fd7-4bad-b3b2-91e6ba802fb4', '湖口縣', '湖口縣', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["柴桑分邑載圖經，屈曲山光展畫屏。","最是蘆洲東北望，人家殘照隔煙汀。"]', '["柴桑分邑載圖經，屈曲山光展畫屏。","最是蘆洲东北望，人家殘照隔煙汀。"]', '诗', 'shi', '', NULL, '湖口縣 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6e6303-7dfe-422f-aa6b-4c7fc3e4f694', '岳州衆湖阻風二首 一', '岳州衆湖阻风二首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["衆湖湖口繫蘭船，睡起中餐又却眠。","風伯如何解迴怒，數宵檣倚碧蘆煙。"]', '["衆湖湖口繫蘭船，睡起中餐又却眠。","风伯如何解迴怒，數宵檣倚碧蘆煙。"]', '诗', 'shi', '', NULL, '岳州衆湖阻風二首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f53b0daa-1785-4364-9cd4-0bd441beff63', '岳州衆湖阻風二首 二', '岳州衆湖阻风二首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["偶繫扁舟枕綠莎，旋移深處避驚波。","曉來閑共漁人話，此去巴陵路幾多。"]', '["偶繫扁舟枕綠莎，旋移深处避驚波。","晓来闲共漁人話，此去巴陵路幾多。"]', '诗', 'shi', '', NULL, '岳州衆湖阻風二首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80121679-1d9f-4e8b-95ef-a5df953cf296', '問春', '问春', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["遊絲垂幄雨依依，枝上紅香片片飛。","把酒問春因底意，爲誰來後爲誰歸。"]', '["游絲垂幄雨依依，枝上紅香片片飞。","把酒问春因底意，爲誰来後爲誰归。"]', '诗', 'shi', '', NULL, '問春 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda42d82-acea-4e4f-bee2-f83b23b6975e', '春荅', '春荅', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["花枝千萬趁春開，三月瓓珊即自回。","剩向東園種桃李，明年依舊爲君來。"]', '["花枝千万趁春开，三月瓓珊即自回。","剩向东园種桃李，明年依旧爲君来。"]', '诗', 'shi', '', NULL, '春荅 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01692ff-b859-416e-a3c7-cf7ba9dbdfeb', '西塞山二首 一', '西塞山二首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["西塞名山立翠屏，濃嵐橫入半江青。","千尋鐵鏁無由問，石壁空存道者形。"]', '["西塞名山立翠屏，濃嵐橫入半江青。","千尋鐵鏁無由问，石壁空存道者形。"]', '诗', 'shi', '', NULL, '西塞山二首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e58b4c8-7f40-4737-9eef-55eac0808d87', '西塞山二首 二', '西塞山二首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["匹婦頑然莫問因，匹夫何去望千春。","翻思岵屺傳詩什，舉世曾無化石人。"]', '["匹婦頑然莫问因，匹夫何去望千春。","翻思岵屺傳诗什，舉世曾無化石人。"]', '诗', 'shi', '', NULL, '西塞山二首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c989a1-0e6e-41da-801e-12bf82274e69', '使風', '使风', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["風起即千里，風回翻問津。","沈思宦遊者，何啻使風人。"]', '["风起即千里，风回翻问津。","沈思宦游者，何啻使风人。"]', '诗', 'shi', '', NULL, '使風 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d427f29d-3355-4574-8a32-c5cd2e53bcf7', '石首山', '石首山', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["首出崔嵬占上遊，迥存濃翠向荆州。","空聞別有回山力，却見長江曲尺流。"]', '["首出崔嵬占上游，迥存濃翠向荆州。","空闻別有回山力，却见长江曲尺流。"]', '诗', 'shi', '', NULL, '石首山 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce50fcd-ef55-4507-abc8-08df406bbf21', '金口步', '金口步', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["兩山鬬咽喉，羣石矗牙齒。","行客無限怨，橫吞一江水。"]', '["兩山鬬咽喉，羣石矗牙齒。","行客無限怨，橫吞一江水。"]', '诗', 'shi', '', NULL, '金口步 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c784dee4-e753-4ad6-aaa0-4917781e0608', '采桑女二首 一', '采桑女二首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["渡水采桑歸，蠶老催上機。","扎扎得盈尺，輕素何人衣。"]', '["渡水采桑归，蠶老催上機。","扎扎得盈尺，轻素何人衣。"]', '诗', 'shi', '', NULL, '采桑女二首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccdd125f-6b25-448e-89f8-c876fc6703e6', '采桑女二首 二', '采桑女二首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["採桑知蠶飢，投梭惜夜遲。","誰誇羅綺叢，新畫學月眉。"]', '["採桑知蠶飢，投梭惜夜遲。","誰誇羅綺叢，新畫学月眉。"]', '诗', 'shi', '', NULL, '采桑女二首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a12caab-9bd4-4b27-9862-381df992761d', '渡溪', '渡溪', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["渡溪溪水急，水濺羅衣濕。","日暮猶未歸，盈盈水邊立。"]', '["渡溪溪水急，水濺羅衣濕。","日暮猶未归，盈盈水邊立。"]', '诗', 'shi', '', NULL, '渡溪 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb2b70d6-9985-4b06-a850-5b51f2c98e1b', '落葉', '落葉', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["素律鑠欲脆，青女妒復稀。","月冷天風吹，葉葉乾紅飛。"]', '["素律鑠欲脆，青女妒复稀。","月冷天风吹，葉葉乾紅飞。"]', '诗', 'shi', '', NULL, '落葉 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfefbd7-5c69-4928-80a8-91c582aa7b11', '宿疎陂驛', '宿疎陂驛', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["秋染棠梨葉半紅，荆州東望草平空。","誰知孤宦天涯意，微雨蕭蕭古驛中。"]', '["秋染棠梨葉半紅，荆州东望草平空。","誰知孤宦天涯意，微雨蕭蕭古驛中。"]', '诗', 'shi', '', NULL, '宿疎陂驛 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b552e4ac-7559-495b-af36-aa85f4be0013', '再經秭歸二首 一', '再經秭归二首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["總角曾隨上峽船，尋思如夢可悽然。","夜來孤館重來宿，枕底灘聲似舊年。"]', '["總角曾隨上峽船，尋思如梦可悽然。","夜来孤館重来宿，枕底灘声似旧年。"]', '诗', 'shi', '', NULL, '再經秭歸二首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da2a5d28-ff7a-4cc1-8822-2d51e6eaafb5', '再經秭歸二首 二', '再經秭归二首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["秭歸城邑昔曾過，舊識無人奈老何。","獨有淒清難改處，月明聞唱竹枝歌。"]', '["秭归城邑昔曾過，旧識無人奈老何。","独有淒清难改处，月明闻唱竹枝歌。"]', '诗', 'shi', '', NULL, '再經秭歸二首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811552b4-5ca3-489e-8e5c-7ae7f0f3487b', '霞', '霞', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["拂拂生殘暉，層層如裂緋。","天風翦成片，疑作仙人衣。"]', '["拂拂生殘暉，層層如裂緋。","天风翦成片，疑作仙人衣。"]', '诗', 'shi', '', NULL, '霞 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('868f376b-2a60-4eac-8020-4ef885998e00', '巫山公署壁有無名氏戲書二韻', '巫山公署壁有無名氏戲书二韻', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["南陵直上路盤盤，平地凌雲勢萬端。","堪笑巴民不厭足，更嫌山少畫山看。"]', '["南陵直上路盤盤，平地凌云勢万端。","堪笑巴民不厭足，更嫌山少畫山看。"]', '诗', 'shi', '', NULL, '巫山公署壁有無名氏戲書二韻 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e115bf-547d-4ed4-a20d-97bd569a4507', '道院', '道院', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["白日人稀到，簾垂道院深。","雨苔生古壁，雪雀聚寒林。","忘慮憑三樂，消閑信五禽。","誰知是官府，煙縷滿鑪沈。"]', '["白日人稀到，簾垂道院深。","雨苔生古壁，雪雀聚寒林。","忘慮憑三乐，消闲信五禽。","誰知是官府，煙縷满鑪沈。"]', '诗', 'shi', '', NULL, '道院 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d4aca2-85f0-43af-addd-88372e695c7a', '會噲岑山人', '會噲岑山人', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["渝州江上忽相逢，說隱西山最上峰。","略坐移時又分別，片雲孤鶴一枝筇。"]', '["渝州江上忽相逢，说隐西山最上峰。","略坐移时又分別，片云孤鹤一枝筇。"]', '诗', 'shi', '', NULL, '會噲岑山人 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92b8618c-a6fb-4a9e-86f3-5325206046b3', '巴江', '巴江', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["巴江江水色，一帶濃藍碧。","仙女瑟瑟衣，風梭晚來織。"]', '["巴江江水色，一带濃藍碧。","仙女瑟瑟衣，风梭晚来织。"]', '诗', 'shi', '', NULL, '巴江 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d7f1a7-1852-4c68-880a-45c0db5c68ad', '小園桃李始花偶以成詠', '小园桃李始花偶以成詠', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["桃李栽成豔格新，數枝留得小園春。","半紅半白無風雨，隨分夭容解笑人。"]', '["桃李栽成豔格新，數枝留得小园春。","半紅半白無风雨，隨分夭容解笑人。"]', '诗', 'shi', '', NULL, '小園桃李始花偶以成詠 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f156b7cb-fdd1-4c46-97f5-b69ae429d901', '公居', '公居', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["公居門館靜，旅寄萬州城。","山共秋煙紫，霜幷夜月清。","無愁干酒律，有句入詩評。","何必須林下，方馳吏隱名。"]', '["公居门館静，旅寄万州城。","山共秋煙紫，霜幷夜月清。","無愁干酒律，有句入诗評。","何必須林下，方驰吏隐名。"]', '诗', 'shi', '', NULL, '公居 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('945f9cb4-87f4-47ea-a420-143c24be16b2', '富池口', '富池口', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["扁舟閑引望，望極更盤桓。","山密礙江曲，雨多饒地寒。","短莎煙苒苒，驚浪雪漫漫。","難寫愁何限，鄉關在一端。"]', '["扁舟闲引望，望極更盤桓。","山密礙江曲，雨多饒地寒。","短莎煙苒苒，驚浪雪漫漫。","难寫愁何限，乡关在一端。"]', '诗', 'shi', '', NULL, '富池口 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09b6ee3-1732-42ad-a6ff-b743b7e5d324', '夔州病中', '夔州病中', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["隱几經旬疾未痊，孤燈孤驛若爲眠。","郡樓昨夜西風急，一一更籌到枕前。"]', '["隐几經旬疾未痊，孤灯孤驛若爲眠。","郡楼昨夜西风急，一一更籌到枕前。"]', '诗', 'shi', '', NULL, '夔州病中 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ccc4d9-5b01-4c63-8176-865b9002617a', '題廳壁', '題廳壁', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["永日無他念，孤清吏隱心。","竹聲幷雪碎，溪色共煙深。","數息閑凭几，緣情默寄琴。","誰知同寂寞，相與結知音。"]', '["永日無他念，孤清吏隐心。","竹声幷雪碎，溪色共煙深。","數息闲凭几，緣情默寄琴。","誰知同寂寞，相與結知音。"]', '诗', 'shi', '', NULL, '題廳壁 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c489ed-8305-4fd7-b7f4-cd58853c41fa', '過武寧縣', '過武寧縣', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["行過武寧縣，初晴物景和。","岸回驚水急，山淺見天多。","細草濃藍潑，輕煙匹練拖。","晚來何處宿，一笛起漁歌。"]', '["行過武寧縣，初晴物景和。","岸回驚水急，山淺见天多。","細草濃藍潑，轻煙匹練拖。","晚来何处宿，一笛起漁歌。"]', '诗', 'shi', '', NULL, '過武寧縣 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9551e6ce-9f46-4162-8d67-602b5eec2e27', '路次覆盆驛', '路次覆盆驛', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["曾上青泥蜀道難，架空成路入雲寒。","如何却向巴東去，三十六盤天外盤。"]', '["曾上青泥蜀道难，架空成路入云寒。","如何却向巴东去，三十六盤天外盤。"]', '诗', 'shi', '', NULL, '路次覆盆驛 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57cab9d3-0ccb-4f50-9d20-d18142571cae', '藕池阻風寄同行撫牧裘駕', '藕池阻风寄同行撫牧裘駕', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["船檣相望荆江中，岸蘆汀樹煙濛濛。","路聞隄缺水如箭，未知何日生南風。"]', '["船檣相望荆江中，岸蘆汀樹煙濛濛。","路闻隄缺水如箭，未知何日生南风。"]', '诗', 'shi', '', NULL, '藕池阻風寄同行撫牧裘駕 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efe5901e-d44e-4622-a101-e05d9993ed72', '無題二首 一', '無題二首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["冰雪肌膚力不勝，落花飛絮遶風亭。","不知何事鞦韆下，蹙破愁眉兩點青。"]', '["冰雪肌膚力不勝，落花飞絮遶风亭。","不知何事鞦韆下，蹙破愁眉兩点青。"]', '诗', 'shi', '', NULL, '無題二首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85fedb0b-a224-4ece-ba5b-7acbc7153e65', '無題二首 二', '無題二首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["梨花如雪已相迷，更被驚烏半夜啼。","簾捲玉樓人寂寂，一鉤新月未沈西。"]', '["梨花如雪已相迷，更被驚烏半夜啼。","簾捲玉楼人寂寂，一鉤新月未沈西。"]', '诗', 'shi', '', NULL, '無題二首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d5159c8-0294-4685-85b2-2c09c0289b0a', '泊巴東', '泊巴东', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["偶泊巴東古縣前，宦情鄉思兩綿綿。","不堪蠟炬燒殘淚，雨打船窗半夜天。"]', '["偶泊巴东古縣前，宦情乡思兩綿綿。","不堪蠟炬燒殘泪，雨打船窗半夜天。"]', '诗', 'shi', '', NULL, '泊巴東 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a0eee6-4f26-4c13-bfab-33d55f7c837e', '道中未開木杏花', '道中未开木杏花', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["粉英香萼一般般，無限行人立馬看。","村女浴蠶桑柘綠，枉將顏色忍春寒。"]', '["粉英香萼一般般，無限行人立马看。","村女浴蠶桑柘綠，枉將顏色忍春寒。"]', '诗', 'shi', '', NULL, '道中未開木杏花 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4c9152-51b1-4351-bc6f-c4f975b17c1a', '西山晚景', '西山晚景', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["公局長清淡，池亭晚景中。","蔗竿閑倚碧，蓮朵靜淹紅。","半引彎彎月，微生飋飋風。","無思復無慮，此味幾人同。"]', '["公局长清淡，池亭晚景中。","蔗竿闲倚碧，蓮朵静淹紅。","半引彎彎月，微生飋飋风。","無思复無慮，此味幾人同。"]', '诗', 'shi', '', NULL, '西山晚景 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95ddac5f-5d57-441e-9f83-8d37a19a02d4', '自和', '自和', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["一片殘陽景，朦朧淡月中。","蘭芽紆嫩紫，棃頰抹生紅。","琴阮資清格，冠簪養素風。","煙霄半知足，吏隱少相同。"]', '["一片殘陽景，朦朧淡月中。","蘭芽紆嫩紫，棃頰抹生紅。","琴阮資清格，冠簪養素风。","煙霄半知足，吏隐少相同。"]', '诗', 'shi', '', NULL, '自和 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd8fd96-8fa5-4475-b157-06ae7d4966b6', '齒落詞', '齒落词', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["己卯至庚辰，仲夏晦之暮。","吾齒右排上，一齒脫而去。","呼吸缺吾防，咀嚼欠吾助。","年籥惜不返，日馭走爲蠹。","脣亡得無寒，舌在從何訴。","輔車宜長依，髮膚可增懼。","不須考前古，聊且爲近喻。","有如雲中雨，雨散絕回顧。","有如枝上葉，葉脫難再附。","白髮非獨愁，紅顏豈私駐。","何必鬱九回，何必牽百慮。","開尊復開懷，引筆作長句。"]', '["己卯至庚辰，仲夏晦之暮。","吾齒右排上，一齒脫而去。","呼吸缺吾防，咀嚼欠吾助。","年籥惜不返，日馭走爲蠹。","脣亡得無寒，舌在從何訴。","輔车宜长依，髮膚可增懼。","不須考前古，聊且爲近喻。","有如云中雨，雨散絕回顧。","有如枝上葉，葉脫难再附。","白髮非独愁，紅顏豈私駐。","何必鬱九回，何必牽百慮。","开尊复开懷，引笔作长句。"]', '诗', 'shi', '', NULL, '齒落詞 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('799ce138-8f5d-4bca-a8c1-288e9697e671', '淘金磧', '淘金磧', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["畫船晚過淘金磧，不見黃金惟見石。","猶恐黃金價未高，見得錙銖幾多力。"]', '["畫船晚過淘金磧，不见黄金惟见石。","猶恐黄金價未高，见得錙銖幾多力。"]', '诗', 'shi', '', NULL, '淘金磧 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ba9138-357c-4a50-9204-83f39bd2c02c', '施南路偶書', '施南路偶书', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["大石嶺南梅欲發，南陵陂上雪初飛。","苦無酒解愁成陣，又附蘭橈向秭歸。"]', '["大石嶺南梅欲發，南陵陂上雪初飞。","苦無酒解愁成陣，又附蘭橈向秭归。"]', '诗', 'shi', '', NULL, '施南路偶書 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8da991e-92a4-4214-a98e-dbcf7d4df447', '大石嶺驛梅花', '大石嶺驛梅花', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["仙中姑射接瑤姬，成陣清香擁路岐。","半出驛牆誰畫得，雪英相倚兩三枝。"]', '["仙中姑射接瑤姬，成陣清香擁路岐。","半出驛牆誰畫得，雪英相倚兩三枝。"]', '诗', 'shi', '', NULL, '大石嶺驛梅花 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70c3591f-3d13-4637-970f-53f0a355dd6b', '贈怤師', '贈怤師', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["水中有片月，照耀嬋娟姿。","庭前有孤栢，竦秀歲寒期。","堅然物莫遷，寂焉心爲師。","聲發響必荅，形存影即隨。","雪花安結子，雪葉寧附枝。","蘭死不改香，井寒豈生澌。","晨鑪煙褭褭，病髮霜絲絲。","丈室冰凜冽，一衲雲離披。","顧此名利場，得不慙冠綏。"]', '["水中有片月，照耀嬋娟姿。","庭前有孤栢，竦秀歲寒期。","堅然物莫遷，寂焉心爲師。","声發响必荅，形存影即隨。","雪花安結子，雪葉寧附枝。","蘭死不改香，井寒豈生澌。","晨鑪煙褭褭，病髮霜絲絲。","丈室冰凜冽，一衲云離披。","顧此名利場，得不慙冠綏。"]', '诗', 'shi', '', NULL, '贈怤師 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4278d8-f0ec-45e5-89e8-accdbba225fa', '遊仙都觀', '游仙都观', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["冷杉枯栢路盤空，毛髮生寒略略風。","兩漢真仙在何處，巡香行遶蘂珠宮。"]', '["冷杉枯栢路盤空，毛髮生寒略略风。","兩漢真仙在何处，巡香行遶蘂珠宮。"]', '诗', 'shi', '', NULL, '遊仙都觀 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7b08427-a4b6-48c9-9d30-18b5b18405ee', '誌峽船具詩 梢', '誌峽船具诗 梢', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["制之居首尾，俾之辨斜正。","首動尾聿隨，斜取正爲定。","有如提吏筆，有如執時柄。","有如秉師律，有如宣命令。","守彼方與直，得其剛且勁。","既能濟險難，何畏涉遼敻。","招招俾作主，汎汎實司命。","風烏愧斟酌，畫鷁空輝映。","古人存豐規，猗歟聊引證。"]', '["制之居首尾，俾之辨斜正。","首动尾聿隨，斜取正爲定。","有如提吏笔，有如執时柄。","有如秉師律，有如宣命令。","守彼方與直，得其剛且勁。","既能濟險难，何畏涉遼敻。","招招俾作主，汎汎實司命。","风烏愧斟酌，畫鷁空輝映。","古人存豐規，猗歟聊引證。"]', '诗', 'shi', '', NULL, '誌峽船具詩 梢 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c0a73c-17c9-4a0c-8315-d8e2c5830393', '誌峽船具詩 艣', '誌峽船具诗 艣', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["用之大曰艫，冠乎小者楫。","通津既能濟，巨浸即橫涉。","身之使者頰，虎之拏者爪。","魚之撥者鬣，弩之進者筴。","此實爲相須，相須航一葉。"]', '["用之大曰艫，冠乎小者楫。","通津既能濟，巨浸即橫涉。","身之使者頰，虎之拏者爪。","鱼之撥者鬣，弩之進者筴。","此實爲相須，相須航一葉。"]', '诗', 'shi', '', NULL, '誌峽船具詩 艣 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53f4491-47b8-4cb8-8ff5-31c85a0a6946', '誌峽船具詩 戙', '誌峽船具诗 戙', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["箭飛峽中水，鋸立峽中石。","峽與水爲隘，水與石相擊。","濆爲生險艱，聲發甚霹靂。","三老航一葉，百丈空千尺。","蒼黃徒爾爲，倏忽何可測。","篙之小難制，戙之獨有力。","猗嗟戙之爲，彬彬堅且直。","有如用武人，森森矗戈戟。","有如敢言士，落落吐胸臆。","拯危居坦夷，濟險免兢惕。","誌彼哲匠心，俾其來者識。"]', '["箭飞峽中水，鋸立峽中石。","峽與水爲隘，水與石相擊。","濆爲生險艱，声發甚霹靂。","三老航一葉，百丈空千尺。","蒼黄徒爾爲，倏忽何可測。","篙之小难制，戙之独有力。","猗嗟戙之爲，彬彬堅且直。","有如用武人，森森矗戈戟。","有如敢言士，落落吐胸臆。","拯危居坦夷，濟險免兢惕。","誌彼哲匠心，俾其来者識。"]', '诗', 'shi', '', NULL, '誌峽船具詩 戙 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('176ca419-0dac-4f58-ba00-de6345b91e88', '誌峽船具詩 百丈', '誌峽船具诗 百丈', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["少嘗侍先君，餘閑誦白氏。","始得入峽詩，深味作詩旨。","云有萬仞山，云有千丈水。","自念坎壈時，尤多兢慎理。","山束峽如口，水漱石如齒。","孤舟行其中，薄冰猶坦履。","孱顏屹焉立，洶湧勃然起。","百丈爲前牽，萬險即平砥。","破之以篔簹，續之以麻枲。","礪之堅以節，引之直如矢。","杼軸連半空，長短隨兩涘。","鐵鎖枉馳名，錦纜謾稱美。","長繩豈能繫，朽索何足擬。","苟非𦁤之爲，胡可力行此。"]', '["少嘗侍先君，餘闲誦白氏。","始得入峽诗，深味作诗旨。","云有万仞山，云有千丈水。","自念坎壈时，尤多兢慎理。","山束峽如口，水漱石如齒。","孤舟行其中，薄冰猶坦履。","孱顏屹焉立，洶湧勃然起。","百丈爲前牽，万險即平砥。","破之以篔簹，續之以麻枲。","礪之堅以節，引之直如矢。","杼軸連半空，长短隨兩涘。","鐵鎖枉驰名，錦纜謾稱美。","长繩豈能繫，朽索何足擬。","苟非𦁤之爲，胡可力行此。"]', '诗', 'shi', '', NULL, '誌峽船具詩 百丈 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fccb9aa6-0d69-44af-897d-97965138d613', '早春西園', '早春西园', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["引步攜筇竹，西園小徑通。","雪欹梅蔕綠，春入杏梢紅。","靜意崖穿溜，孤愁笛破空。","如何將此景，收拾向圖中。"]', '["引步携筇竹，西园小徑通。","雪欹梅蔕綠，春入杏梢紅。","静意崖穿溜，孤愁笛破空。","如何將此景，收拾向圖中。"]', '诗', 'shi', '', NULL, '早春西園 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3fcccb-46f3-41f8-be2d-db176311f5a7', '金盤草詩', '金盤草诗', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["今春從南陵，得草名金盤。","金盤有仁性，生在林一端。","根節歲一節，食之甘而酸。","風俗競採掇，俾人防急難。","巴中虵虺毒，解之如走丸。","巨葉展六出，軟幹分長竿。","搖搖綠玉活，褭褭香荷寒。","世云暑酷月，鬱有神物看。","天之產於此，意欲生民安。","今之爲政者，何不反此觀。","知彼苛且猛，慎勿虐而殘。","一物苟失所，萬金惟可歎。","莫並蒿與萊，豈羨芝及蘭。","勤渠護根本，栽植當庭欄。","寄言好生者，休說神仙丹。"]', '["今春從南陵，得草名金盤。","金盤有仁性，生在林一端。","根節歲一節，食之甘而酸。","风俗競採掇，俾人防急难。","巴中虵虺毒，解之如走丸。","巨葉展六出，軟幹分长竿。","搖搖綠玉活，褭褭香荷寒。","世云暑酷月，鬱有神物看。","天之產於此，意欲生民安。","今之爲政者，何不反此观。","知彼苛且猛，慎勿虐而殘。","一物苟失所，万金惟可歎。","莫並蒿與萊，豈羨芝及蘭。","勤渠護根本，栽植當庭欄。","寄言好生者，休说神仙丹。"]', '诗', 'shi', '', NULL, '金盤草詩 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972d5f94-468b-428c-9a94-610f5c3777c5', '和程刑部三首 公會亭', '和程刑部三首 公會亭', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["公事公言地，標名姓必臧。","江山如得助，談笑若爲妨。","均賦鄉原肅，詳刑郡邑康。","官箴居座右，夙夜算難忘。"]', '["公事公言地，標名姓必臧。","江山如得助，談笑若爲妨。","均賦乡原肅，詳刑郡邑康。","官箴居座右，夙夜算难忘。"]', '诗', 'shi', '', NULL, '和程刑部三首 公會亭 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b777d7c1-474f-4f60-bff2-4061159aa0c5', '和程刑部三首 碧鮮亭', '和程刑部三首 碧鲜亭', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["飋飋籠清籟，蕭蕭鏁翠陰。","向高思盡節，從直美虛心。","迥砌滋蒼蘚，幽窗伴素琴。","公餘時引步，一徑靜中深。"]', '["飋飋籠清籟，蕭蕭鏁翠陰。","向高思尽節，從直美虛心。","迥砌滋蒼蘚，幽窗伴素琴。","公餘时引步，一徑静中深。"]', '诗', 'shi', '', NULL, '和程刑部三首 碧鮮亭 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3acda17e-2d18-4c03-8e25-34c6ef7bcd7b', '和程刑部三首 清漣閤', '和程刑部三首 清漣閤', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["照影翻窗綺，層紋滉額波。","絲青迷岸柳，茸綠蘸汀莎。","片雪翹飢鷺，孤香卷嫩荷。","憑欄堪入畫，時聽竹枝歌。"]', '["照影翻窗綺，層紋滉額波。","絲青迷岸柳，茸綠蘸汀莎。","片雪翹飢鷺，孤香卷嫩荷。","憑欄堪入畫，时听竹枝歌。"]', '诗', 'shi', '', NULL, '和程刑部三首 清漣閤 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f12f0006-8935-43bc-9873-29cacf1d4c40', '自喻', '自喻', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["予念天之生，生本空疎器。","五歲稟慈訓，憤悱讀書志。","七歲辨聲律，勤苦會詩賦。","九歲執公卷，倜儻干名意。","乞薦鄉老書，幸會春官試。","折桂愧巍峩，依蓮何氣味。","性拙絕不佞，才短無餘地。","前年會知己，薦章實非據。","寧見民說平，空荷君恩寄。","瞿唐抵巴渝，往來名攬轡。","孤舟一水中，艱險實可畏。","羣操百丈牽，臨難無苟避。","濆向江底發，水在石中沸。","槌鼓稱打寬，繫紉呼下緯。","善惡胡可分，死生何足諱。","騎衡與垂堂，非不知前喻。","臨淵與履冰，非不知深慮。","我今縻搢紳，善地誰人致。","城孤與社鼠，巧佞誰從庇。","奴顏與婢膝，醜直誰從媚。","妻兒敻限越，容顏幾憔悴。","致身霄漢人，呝嚱盡賢智。"]', '["予念天之生，生本空疎器。","五歲稟慈訓，憤悱读书志。","七歲辨声律，勤苦會诗賦。","九歲執公卷，倜儻干名意。","乞薦乡老书，幸會春官試。","折桂愧巍峩，依蓮何氣味。","性拙絕不佞，才短無餘地。","前年會知己，薦章實非據。","寧见民说平，空荷君恩寄。","瞿唐抵巴渝，往来名攬轡。","孤舟一水中，艱險實可畏。","羣操百丈牽，臨难無苟避。","濆向江底發，水在石中沸。","槌鼓稱打寬，繫紉呼下緯。","善惡胡可分，死生何足諱。","騎衡與垂堂，非不知前喻。","臨淵與履冰，非不知深慮。","我今縻搢紳，善地誰人致。","城孤與社鼠，巧佞誰從庇。","奴顏與婢膝，醜直誰從媚。","妻兒敻限越，容顏幾憔悴。","致身霄漢人，呝嚱尽賢智。"]', '诗', 'shi', '', NULL, '自喻 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e0edb2-364d-4305-ab53-e03cf18570dc', '巫山廟', '巫山廟', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["廟前溪水流潺潺，廟中修竹聲珊珊。","襄王一夢杳難問，晚晴天氣歸雲閑。"]', '["廟前溪水流潺潺，廟中修竹声珊珊。","襄王一梦杳难问，晚晴天氣归云闲。"]', '诗', 'shi', '', NULL, '巫山廟 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45970138-c1e8-4810-815f-1bfae5bc8f7f', '下瞿塘寄時同年', '下瞿塘寄时同年', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["春寒天氣下瞿塘，大壤溪前柳線長。","須信孤雲是孤宦，莫將鄉思附歸艎。"]', '["春寒天氣下瞿塘，大壤溪前柳線长。","須信孤云是孤宦，莫將乡思附归艎。"]', '诗', 'shi', '', NULL, '下瞿塘寄時同年 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19eac081-6e47-40d2-8349-7836f83ae843', '和杜運使巴峽地暖節物與中土異黯然有感詩三首 一', '和杜運使巴峽地暖節物與中土異黯然有感诗三首 一', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["隨柳參差破綠芽，此中依約欲飛花。","春光是處傷離思，何況歸期未有涯。"]', '["隨柳參差破綠芽，此中依約欲飞花。","春光是处傷離思，何況归期未有涯。"]', '诗', 'shi', '', NULL, '和杜運使巴峽地暖節物與中土異黯然有感詩三首 一 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf3556a-26c9-42ae-a974-30001fdeb5b1', '和杜運使巴峽地暖節物與中土異黯然有感詩三首 二', '和杜運使巴峽地暖節物與中土異黯然有感诗三首 二', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["始看菊蘂開籬下，又見梅花寄嶺頭。","攬轡巴西官局冷，幾憑春酒沃鄉愁。"]', '["始看菊蘂开籬下，又见梅花寄嶺头。","攬轡巴西官局冷，幾憑春酒沃乡愁。"]', '诗', 'shi', '', NULL, '和杜運使巴峽地暖節物與中土異黯然有感詩三首 二 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afeaa38c-ca21-4596-b889-787a0a1c5e45', '和杜運使巴峽地暖節物與中土異黯然有感詩三首 三', '和杜運使巴峽地暖節物與中土異黯然有感诗三首 三', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["花品姚黃冠洛陽，巴中春早羨孤芳。","不知別有栽培力，流詠新詩與激昂。"]', '["花品姚黄冠洛陽，巴中春早羨孤芳。","不知別有栽培力，流詠新诗與激昂。"]', '诗', 'shi', '', NULL, '和杜運使巴峽地暖節物與中土異黯然有感詩三首 三 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a205a516-bef3-4a90-9158-4a6380280ccf', '施南太守以猨兒爲寄作詩答之', '施南太守以猨兒爲寄作诗答之', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["虞人初獲酉江西，長臂難將意馬齊。","今日未啼頭已白，不堪深入白雲啼。"]', '["虞人初獲酉江西，长臂难將意马齊。","今日未啼头已白，不堪深入白云啼。"]', '诗', 'shi', '', NULL, '施南太守以猨兒爲寄作詩答之 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed238c5-0d65-472b-8bdc-4eda7f3b588b', '巫廟', '巫廟', '7b6d8415-22d9-4243-9f8a-59a5e37f8fb8', '唐', '["巴水走若箭，峽山開如屏。","洶湧匹練白，𡷾崒濃藍青。","崖空蓄雲雨，灘惡驚雷霆。","神仙宅幽邃，廟貌橫杳冥。","隱約可一夢，縹緲餘千齡。","名利有所役，舟楫無暫停。","悉宰垂[肸]蠁，祠禱希安寧。","鵶鵶爾何物，飛飛來廟庭。","紛紛颺寥泬，遠近隨虛舲。","鐵石礪觜爪，金碧輝光翎。","翔集託陰險，鵮啄貪羶腥。","日既恃威福，歲久爲精靈。","依草與附木，誣詭殊不經。","城狐與社鼠，瑣細何足聽。","況乎人假人，心闊吞滄溟。"]', '["巴水走若箭，峽山开如屏。","洶湧匹練白，𡷾崒濃藍青。","崖空蓄云雨，灘惡驚雷霆。","神仙宅幽邃，廟貌橫杳冥。","隐約可一梦，縹緲餘千齡。","名利有所役，舟楫無暫停。","悉宰垂[肸]蠁，祠禱希安寧。","鵶鵶爾何物，飞飞来廟庭。","紛紛颺寥泬，远近隨虛舲。","鐵石礪觜爪，金碧輝光翎。","翔集託陰險，鵮啄貪羶腥。","日既恃威福，歲久爲精靈。","依草與附木，誣詭殊不經。","城狐與社鼠，瑣細何足听。","況乎人假人，心闊吞滄溟。"]', '诗', 'shi', '', NULL, '巫廟 王周 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ffcf8c-a46f-48be-bdb5-31f4a2e66a45', '貴遊', '貴游', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["繡衣公子宴池塘，淑景融融萬卉芳。","珠翠照天春未老，管弦臨水日初長。","風飄柳線金成穗，雨洗梨花玉有香。","醉後不能離綺席，擬憑青帝繫斜陽。"]', '["繡衣公子宴池塘，淑景融融万卉芳。","珠翠照天春未老，管弦臨水日初长。","风飄柳線金成穗，雨洗梨花玉有香。","醉後不能離綺席，擬憑青帝繫斜陽。"]', '诗', 'shi', '', NULL, '貴遊 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a5aa76-391b-4cd6-b95d-465cf9570e73', '夢歸故園 一', '梦归故园 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["桐葉飛霜落井欄，菱花藏雪助衰顏。","夜窗颯颯搖寒竹，秋枕迢迢夢故山。","臨水釣舟橫荻岸，隔溪禪侶啓柴關。","覺來依舊三更月，離緒鄉心起萬端。"]', '["桐葉飞霜落井欄，菱花藏雪助衰顏。","夜窗颯颯搖寒竹，秋枕迢迢梦故山。","臨水釣舟橫荻岸，隔溪禪侶啓柴关。","覺来依旧三更月，離緒乡心起万端。"]', '诗', 'shi', '', NULL, '夢歸故園 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad36f629-19a6-409f-86e3-769bf641b698', '夢歸故園 二', '梦归故园 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["舊館秋寒夜夢長，水簾疎影入迴塘。","宦情率爾拖魚艇，客恨依然在燕梁。","白鷺獨飄山面雪，紅蕖全謝鏡心香。","起來不語無人會，醉倚東軒半夕陽。"]', '["旧館秋寒夜梦长，水簾疎影入迴塘。","宦情率爾拖鱼艇，客恨依然在燕梁。","白鷺独飄山面雪，紅蕖全謝镜心香。","起来不語無人會，醉倚东軒半夕陽。"]', '诗', 'shi', '', NULL, '夢歸故園 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2d5341-21a9-4a95-a4c2-9a9d8b14842b', '蜀都春晚感懷', '蜀都春晚感懷', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["蜀都春色漸離披，夢斷雲空事莫追。","宮闕一城荒作草，王孫猶自醉如泥。","誰家玉笛吹殘照，柳市金絲拂舊堤。","可惜錦江無錦濯，海棠花下杜鵑啼。"]', '["蜀都春色漸離披，梦斷云空事莫追。","宮闕一城荒作草，王孫猶自醉如泥。","誰家玉笛吹殘照，柳市金絲拂旧堤。","可惜錦江無錦濯，海棠花下杜鵑啼。"]', '诗', 'shi', '', NULL, '蜀都春晚感懷 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62426e88-a7e8-4862-b816-f26d6b7505c3', '對雨', '对雨', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["幽庭凝碧亦漣漪，簷霤聲繁聒夢歸。","半岫金烏纔委照，一川石燕又交飛。","濯枝霢霂榴花吐，吹渚飄颻暑氣微。","因憶故園閑釣處，蒼苔斑駁滿漁磯。"]', '["幽庭凝碧亦漣漪，簷霤声繁聒梦归。","半岫金烏纔委照，一川石燕又交飞。","濯枝霢霂榴花吐，吹渚飄颻暑氣微。","因憶故园闲釣处，蒼苔斑駁满漁磯。"]', '诗', 'shi', '', NULL, '對雨 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6382c01f-4a54-434f-a784-51228010162c', '春霽', '春霽', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["春霽江山似畫圖，醉垂鞭袂出康衢。","猖狂亂打貔貅鼓，懶慢遲修鴛鷺書。","老色漸來欺鬢髮，閑晴將欲傲簪裾。","苔錢遍地知多少，買得花枝不落無。"]', '["春霽江山似畫圖，醉垂鞭袂出康衢。","猖狂亂打貔貅鼓，懶慢遲修鴛鷺书。","老色漸来欺鬢髮，闲晴將欲傲簪裾。","苔錢遍地知多少，買得花枝不落無。"]', '诗', 'shi', '', NULL, '春霽 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755ee7db-5806-45b1-a48a-3fa1e39657e7', '秋夕書懷 一', '秋夕书懷 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["荒僻淹留歲已深，解龜無計恨難任。","守方半會蠻夷語，賀廈全忘燕雀心。","夜靜倚樓悲月笛，秋寒欹枕泣霜砧。","宦情總逐愁腸斷，一筯鱸魚直萬金。"]', '["荒僻淹留歲已深，解龟無計恨难任。","守方半會蠻夷語，賀廈全忘燕雀心。","夜静倚楼悲月笛，秋寒欹枕泣霜砧。","宦情總逐愁腸斷，一筯鱸鱼直万金。"]', '诗', 'shi', '', NULL, '秋夕書懷 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429b2294-e37e-4414-bec8-7ec536cba78a', '秋夕書懷 二', '秋夕书懷 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["直氣從來不入時，掩關慵更釣磻溪。","斯文未喪宣尼歎，吾道將窮阮籍悲。","輕粉覆霜凝夜砌，亂金鋪菊織秋籬。","南陽臥久無人問，薄命非才有可疑。"]', '["直氣從来不入时，掩关慵更釣磻溪。","斯文未喪宣尼歎，吾道將窮阮籍悲。","轻粉覆霜凝夜砌，亂金鋪菊织秋籬。","南陽臥久無人问，薄命非才有可疑。"]', '诗', 'shi', '', NULL, '秋夕書懷 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92574db-dd5b-45b2-a504-3fac65e0d6cb', '春霄', '春霄', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["春雲春日共朦朧，滿院梨花半夜風。","宿酒未醒珠箔捲，豔歌初闋玉樓空。","五湖范蠡才堪重，六印蘇秦道不同。","再取素琴聊假寐，南柯靈夢莫相通。"]', '["春云春日共朦朧，满院梨花半夜风。","宿酒未醒珠箔捲，豔歌初闋玉楼空。","五湖范蠡才堪重，六印蘇秦道不同。","再取素琴聊假寐，南柯靈梦莫相通。"]', '诗', 'shi', '', NULL, '春霄 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c553c8d1-3f42-41e4-8216-76df46dc4dff', '秋夕書懷呈戎州郎中 一', '秋夕书懷呈戎州郎中 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["素律初迴枕簟涼，松風飄泊入華堂。","譚雞寂默紗窗靜，夢蝶蕭條玉漏長。","歸去水雲多阻隔，別來情緒足悲傷。","霜砧月笛休相引，只有離襟淚兩行。"]', '["素律初迴枕簟涼，松风飄泊入华堂。","譚雞寂默紗窗静，梦蝶蕭條玉漏长。","归去水云多阻隔，別来情緒足悲傷。","霜砧月笛休相引，只有離襟泪兩行。"]', '诗', 'shi', '', NULL, '秋夕書懷呈戎州郎中 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70220e10-577b-431d-a51e-c928b1a88b08', '秋夕書懷呈戎州郎中 二', '秋夕书懷呈戎州郎中 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["風送秋荷滿鼻香，竹聲敲玉近虛廊。","夢迴故國情方黯，月過疎簾夜正涼。","菱鏡也知移豔態，錦書其奈隔年光。","鸞膠處處難尋覓，斷盡相思寸寸腸。"]', '["风送秋荷满鼻香，竹声敲玉近虛廊。","梦迴故国情方黯，月過疎簾夜正涼。","菱镜也知移豔態，錦书其奈隔年光。","鸾膠处处难尋覓，斷尽相思寸寸腸。"]', '诗', 'shi', '', NULL, '秋夕書懷呈戎州郎中 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1f63af2-2b60-4ca1-bbb5-9c0d65cf44df', '晚樓寓懷', '晚楼寓懷', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["薄暮疎林宿鳥還，倚樓垂袂復憑欄。","月沈江底珠輪淨，雲鎖峰頭玉葉寒。","劉毅暫貧雖壯志，馮唐將老自低顏。","無言獨對秋風立，擬把朝簪換釣竿。"]', '["薄暮疎林宿鸟還，倚楼垂袂复憑欄。","月沈江底珠輪淨，云鎖峰头玉葉寒。","劉毅暫貧雖壯志，馮唐將老自低顏。","無言独对秋风立，擬把朝簪換釣竿。"]', '诗', 'shi', '', NULL, '晚樓寓懷 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01963000-36cb-4f71-ac7d-3575177a05bf', '征婦怨', '征婦怨', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["金閨寂寞罷妝臺，玉筯闌干界粉腮。","花落掩關春欲暮，月圓欹枕夢初迴。","鸞膠豈續愁腸斷，龍劒難揮別緒開。","曾寄錦書無限意，塞鴻何事不歸來。"]', '["金閨寂寞罷妝台，玉筯闌干界粉腮。","花落掩关春欲暮，月圓欹枕梦初迴。","鸾膠豈續愁腸斷，龙劒难揮別緒开。","曾寄錦书無限意，塞鴻何事不归来。"]', '诗', 'shi', '', NULL, '征婦怨 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77fc7fc0-1bee-44f7-8e26-7d1fe5f8b7a3', '對鏡', '对镜', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["青鏡重磨照白鬚，白鬚撚閑意何如。","故園迢遰千山外，荒郡淹留四載餘。","風送竹聲侵枕簟，月移花影過庭除。","秋霜滿領難消釋，莫讀離騷失意書。"]', '["青镜重磨照白鬚，白鬚撚闲意何如。","故园迢遰千山外，荒郡淹留四載餘。","风送竹声侵枕簟，月移花影過庭除。","秋霜满領难消釋，莫读離騷失意书。"]', '诗', 'shi', '', NULL, '對鏡 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0767304f-1005-41ca-9d41-5595c932082a', '春燕', '春燕', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["多時窗外語呢喃，只要佳人捲繡簾。","大廈已成須慶賀，高門頻入莫憎嫌。","花間舞蝶和香趁，江畔春泥帶雨銜。","栖息數年情已厚，營巢爭肯傍他簷。"]', '["多时窗外語呢喃，只要佳人捲繡簾。","大廈已成須慶賀，高门頻入莫憎嫌。","花间舞蝶和香趁，江畔春泥带雨銜。","栖息數年情已厚，營巢爭肯傍他簷。"]', '诗', 'shi', '', NULL, '春燕 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afbe626e-344a-4905-b911-cbfa5155a4b7', '春晚寓懷', '春晚寓懷', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["一承兌澤蒞方州，八度春光照郡樓。","好景幾將官吏醉，名山時領管弦遊。","空花任爾頻侵眼，老雪從他漸滿頭。","歸去杜陵池閣在，只能歡笑不能愁。"]', '["一承兌澤蒞方州，八度春光照郡楼。","好景幾將官吏醉，名山时領管弦游。","空花任爾頻侵眼，老雪從他漸满头。","归去杜陵池閣在，只能歡笑不能愁。"]', '诗', 'shi', '', NULL, '春晚寓懷 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8acdfdd7-03f4-49a5-99d5-cda2e34ea30e', '中春宴遊', '中春宴游', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["二月風光似洞天，紅英翠萼簇芳筵。","楚王雲雨迷巫峽，江令文章媚蜀箋。","歌黛入顰春袖斂，舞衣新繡曉霞鮮。","酒闌香袂初分散，笑指漁翁釣暮煙。"]', '["二月风光似洞天，紅英翠萼簇芳筵。","楚王云雨迷巫峽，江令文章媚蜀箋。","歌黛入顰春袖斂，舞衣新繡晓霞鲜。","酒闌香袂初分散，笑指漁翁釣暮煙。"]', '诗', 'shi', '', NULL, '中春宴遊 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4d93918-3bf9-44ab-adfe-3a27ef6cf590', '春晚閑望', '春晚闲望', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["東風滿地是梨花，只把琴心殢酒家。","立處晚樓橫短笛，望中春草接平沙。","雁行斷續晴天遠，燕翼參差翠幕斜。","歸計未成頭欲白，釣舟煙浪思無涯。"]', '["东风满地是梨花，只把琴心殢酒家。","立处晚楼橫短笛，望中春草接平沙。","雁行斷續晴天远，燕翼參差翠幕斜。","归計未成头欲白，釣舟煙浪思無涯。"]', '诗', 'shi', '', NULL, '春晚閑望 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368889f8-4a3d-46c4-8338-b98a706f5135', '秋夕書事', '秋夕书事', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["搖落江天萬木空，雁行斜戛塞垣風。","征閨擣月離愁遠，舊館眠雲旅夢通。","郢客豈能陪下里，臯禽爭肯戀樊籠。","此心曠蕩誰相會，盡在南華十卷中。"]', '["搖落江天万木空，雁行斜戛塞垣风。","征閨擣月離愁远，旧館眠云旅梦通。","郢客豈能陪下里，臯禽爭肯戀樊籠。","此心曠蕩誰相會，尽在南华十卷中。"]', '诗', 'shi', '', NULL, '秋夕書事 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d4c636-a730-4f2c-84f2-447f883472f2', '蓮塘霽望', '蓮塘霽望', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["新秋菡萏發紅英，向晚風飄滿郡馨。","萬疊水紋羅乍展，一雙鸂鶒繡初成。","採蓮女散吳歌闋，拾翠人歸楚雨晴。","遠岸牧童吹短笛，蓼花深處信牛行。"]', '["新秋菡萏發紅英，向晚风飄满郡馨。","万叠水紋羅乍展，一雙鸂鶒繡初成。","採蓮女散吳歌闋，拾翠人归楚雨晴。","远岸牧童吹短笛，蓼花深处信牛行。"]', '诗', 'shi', '', NULL, '蓮塘霽望 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6f0957-d7a5-41c0-8c49-78c4f4bc5a9a', '送從弟舍人入蜀', '送從弟舍人入蜀', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["嘉陵江畔餞行車，離袂難分十里餘。","慷慨莫誇心似鐵，留連不覺淚成珠。","風光川谷梅將發，音信雲天雁未疎。","立馬舉鞭無限意，會稀別遠擬何如。"]', '["嘉陵江畔餞行车，離袂难分十里餘。","慷慨莫誇心似鐵，留連不覺泪成珠。","风光川谷梅將發，音信云天雁未疎。","立马舉鞭無限意，會稀別远擬何如。"]', '诗', 'shi', '', NULL, '送從弟舍人入蜀 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5806765-f2d8-4d0f-9018-d0fbcb4365c4', '新迴車院筵上作', '新迴车院筵上作', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["迴車院子未迴車，三載疲民詠袴襦。","借寇已承英主詔，乞骸須上老臣書。","黃金蜀柳籠朱戶，碧玉湘筠映綺疏。","因問滿筵詩酒客，錦江何處有鱸魚。"]', '["迴车院子未迴车，三載疲民詠袴襦。","借寇已承英主詔，乞骸須上老臣书。","黄金蜀柳籠朱戶，碧玉湘筠映綺疏。","因问满筵诗酒客，錦江何处有鱸鱼。"]', '诗', 'shi', '', NULL, '新迴車院筵上作 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e6129cb-80f6-41dc-bc66-a502da4836d3', '寄長安鄭員外', '寄长安鄭員外', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["屈指良交十四人，隙駒風燭漸爲塵。","當初花下三秦客，只有天涯二老身。","乘醉幾同遊北內，尋芳多共謁東隣。","此時阻隔關山遠，月滿江樓淚滿巾。"]', '["屈指良交十四人，隙駒风燭漸爲塵。","當初花下三秦客，只有天涯二老身。","乘醉幾同游北內，尋芳多共謁东隣。","此时阻隔关山远，月满江楼泪满巾。"]', '诗', 'shi', '', NULL, '寄長安鄭員外 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0047d363-0c3d-4fab-93d6-d6ba5b620520', '咸陽懷古', '咸陽懷古', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["高秋咸鎬起霜風，秦漢荒陵樹葉紅。","七國鬬雞方賈勇，中原逐鹿更爭雄。","南山漠漠雲常在，渭水悠悠事旋空。","立馬舉鞭遙望處，阿房遺址夕陽東。"]', '["高秋咸鎬起霜风，秦漢荒陵樹葉紅。","七国鬬雞方賈勇，中原逐鹿更爭雄。","南山漠漠云常在，渭水悠悠事旋空。","立马舉鞭遙望处，阿房遺址夕陽东。"]', '诗', 'shi', '', NULL, '咸陽懷古 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f280384-5f44-4bf9-b190-feb0f531d13a', '春怨', '春怨', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["繡林紅岸落花鈿，故去新來感自然。","絕塞杪春悲漢月，長林深夜泣緗弦。","錦書雁斷應難寄，菱鏡鸞孤貌可憐。","獨倚畫屏人不會，夢魂纔別戍樓邊。"]', '["繡林紅岸落花鈿，故去新来感自然。","絕塞杪春悲漢月，长林深夜泣緗弦。","錦书雁斷應难寄，菱镜鸾孤貌可怜。","独倚畫屏人不會，梦魂纔別戍楼邊。"]', '诗', 'shi', '', NULL, '春怨 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4af037f-38fb-4694-9c7a-4d5fccf92373', '登樓寓望', '登楼寓望', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["憑高多是偶汍瀾，紅葉何堪照病顏。","萬疊雲山供遠恨，一軒風物送秋寒。","背琴鶴客歸松徑，橫笛牛童臥蓼灘。","獨倚郡樓無限意，夕陽西去水東還。"]', '["憑高多是偶汍瀾，紅葉何堪照病顏。","万叠云山供远恨，一軒风物送秋寒。","背琴鹤客归松徑，橫笛牛童臥蓼灘。","独倚郡楼無限意，夕陽西去水东還。"]', '诗', 'shi', '', NULL, '登樓寓望 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515d8d6a-f7e2-48de-8d13-7830c6293d08', '江岸獨步', '江岸独步', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["醉卓寒筇傍水行，漁翁不會獨吟情。","龜能顧印誰相重，鶴偶乘軒自可輕。","簪組百年終長物，文章千古亦虛名。","是非得喪皆閑事，休向南柯與夢爭。"]', '["醉卓寒筇傍水行，漁翁不會独吟情。","龟能顧印誰相重，鹤偶乘軒自可轻。","簪組百年終长物，文章千古亦虛名。","是非得喪皆闲事，休向南柯與梦爭。"]', '诗', 'shi', '', NULL, '江岸獨步 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab46fa7-c66d-4e23-84d1-741f41f0249b', '江樓望鄉寄內', '江楼望乡寄內', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["獨上江樓望故鄉，淚襟霜笛共淒涼。","雲生隴首秋雖早，月在天心夜已長。","魂夢只能隨蛺蝶，煙波無計學鴛鴦。","蜀箋都有三千幅，總寫離情寄孟光。"]', '["独上江楼望故乡，泪襟霜笛共淒涼。","云生隴首秋雖早，月在天心夜已长。","魂梦只能隨蛺蝶，煙波無計学鴛鴦。","蜀箋都有三千幅，總寫離情寄孟光。"]', '诗', 'shi', '', NULL, '江樓望鄉寄內 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d233c37-a81d-4d35-ad20-f2e9bb389f55', '命妓不至', '命妓不至', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["琴中難挑孰憐才，獨對良宵酒數杯。","蘇子黑貂將已盡，宋弘青鳥又空回。","月穿淨牖霜成隙，風捲殘花錦作堆。","欹枕夢魂何處去，醉和春色入天台。"]', '["琴中难挑孰怜才，独对良宵酒數杯。","蘇子黑貂將已尽，宋弘青鸟又空回。","月穿淨牖霜成隙，风捲殘花錦作堆。","欹枕梦魂何处去，醉和春色入天台。"]', '诗', 'shi', '', NULL, '命妓不至 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61dd57c4-9c30-4bdc-b52e-0c492483fc17', '宣賜錦袍設上贈諸郡客', '宣賜錦袍設上贈諸郡客', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["十月芙蓉花滿枝，天庭驛騎賜寒衣。","將同玉蝶侵肌冷，也遣金鵬遍體飛。","夜臥始知多忝竊，晝行方覺轉光輝。","深冬若得朝丹闕，太華峰前衣錦歸。"]', '["十月芙蓉花满枝，天庭驛騎賜寒衣。","將同玉蝶侵肌冷，也遣金鵬遍體飞。","夜臥始知多忝竊，晝行方覺轉光輝。","深冬若得朝丹闕，太华峰前衣錦归。"]', '诗', 'shi', '', NULL, '宣賜錦袍設上贈諸郡客 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('010044dc-55d1-4a60-97bf-18ed5cb30b4c', '晨雞', '晨雞', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["朱冠金距綵毛身，昧爽高聲已報晨。","作瑞莫慚先貢楚，擅塲須信獨推秦。","淮南也伴升仙犬，函谷曾容借曉人。","此日卑棲隨飲啄，宰君驅我亦相馴。"]', '["朱冠金距綵毛身，昧爽高声已報晨。","作瑞莫慚先貢楚，擅塲須信独推秦。","淮南也伴升仙犬，函谷曾容借晓人。","此日卑棲隨饮啄，宰君驱我亦相馴。"]', '诗', 'shi', '', NULL, '晨雞 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28cd125-b380-4c40-90f2-a493f9c2fcd0', '芳春', '芳春', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["微雨微風隔晝簾，金爐檀炷冷慵添。","桃花滿地春牢落，柳絮成堆雪棄嫌。","寶瑟不能邀卓氏，綵毫何必夢江淹。","宦情歸興休相撓，隼斾漁舟總未厭。"]', '["微雨微风隔晝簾，金爐檀炷冷慵添。","桃花满地春牢落，柳絮成堆雪棄嫌。","寶瑟不能邀卓氏，綵毫何必梦江淹。","宦情归兴休相撓，隼斾漁舟總未厭。"]', '诗', 'shi', '', NULL, '芳春 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298c5bbf-a1ca-428c-a16c-63bdb0ce55e2', '春遊 一', '春游 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["柳成金穗草如茵，載酒尋花共賞春。","先入醉鄉君莫問，十年風景在三秦。"]', '["柳成金穗草如茵，載酒尋花共賞春。","先入醉乡君莫问，十年风景在三秦。"]', '诗', 'shi', '', NULL, '春遊 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b70702ea-7ddc-4528-831e-db9557ab2a19', '春遊 二', '春游 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["搖搖離緒不能持，滿郡花開酒熟時。","羞聽黃鶯求善友，強隨綠柳展愁眉。","隔雲故國山千疊，傍水芳林錦萬枝。","聖主未容歸北闕，且將勤儉撫南夷。"]', '["搖搖離緒不能持，满郡花开酒熟时。","羞听黄鶯求善友，強隨綠柳展愁眉。","隔云故国山千叠，傍水芳林錦万枝。","聖主未容归北闕，且將勤儉撫南夷。"]', '诗', 'shi', '', NULL, '春遊 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24fad807-9684-49b6-a9ce-27286797769a', '重陽感懷 一', '重陽感懷 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["重陽不忍上高樓，寒菊年年照暮秋。","萬疊故山雲總隔，兩行鄉淚血和流。","黃茅莽莽連邊郡，紅葉紛紛落釣舟。","歸計未成年漸老，茱萸羞戴雪霜頭。"]', '["重陽不忍上高楼，寒菊年年照暮秋。","万叠故山云總隔，兩行乡泪血和流。","黄茅莽莽連邊郡，紅葉紛紛落釣舟。","归計未成年漸老，茱萸羞戴雪霜头。"]', '诗', 'shi', '', NULL, '重陽感懷 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40e68fd-ecb8-40e4-8c1e-540d08eae0a3', '重陽感懷 二', '重陽感懷 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["載花乘酒上高山，四望秋空八極寬。","蜀國江山存不得，劉家豚犬取何難。","張儀舊壁蒼苔厚，葛亮荒祠古木寒。","獨對斜陽更惆悵，錦江東注似波瀾。"]', '["載花乘酒上高山，四望秋空八極寬。","蜀国江山存不得，劉家豚犬取何难。","張儀旧壁蒼苔厚，葛亮荒祠古木寒。","独对斜陽更惆悵，錦江东注似波瀾。"]', '诗', 'shi', '', NULL, '重陽感懷 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ed1d97-7497-4ffd-a8f4-c4c49a7b8e2b', '宴遊池館', '宴游池館', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["綺筵金碧照芳菲，酒滿瑤巵水滿池。","去歲南岐離郡日，今春東蜀看花時。","儉蓮發臉當籌著，緒柳生腰按柘枝。","座客半酣言笑狎，孔融懷抱正怡怡。"]', '["綺筵金碧照芳菲，酒满瑤巵水满池。","去歲南岐離郡日，今春东蜀看花时。","儉蓮發臉當籌著，緒柳生腰按柘枝。","座客半酣言笑狎，孔融懷抱正怡怡。"]', '诗', 'shi', '', NULL, '宴遊池館 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67f0948-dbd2-449f-82b8-39dcab768551', '寄高書記', '寄高书記', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["齊朝慶裔祖敖曹，麟角無雙鳳九毛。","聲價五侯爭辟命，文章一代振風騷。","醉琴自寄陶家意，夢枕誰聽益郡刀。","補衮應星曾奏舉，北山南海孰爲高。"]', '["齊朝慶裔祖敖曹，麟角無雙鳳九毛。","声價五侯爭辟命，文章一代振风騷。","醉琴自寄陶家意，梦枕誰听益郡刀。","補衮應星曾奏舉，北山南海孰爲高。"]', '诗', 'shi', '', NULL, '寄高書記 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8885d398-bbd9-4de2-b527-33ea4345382a', '再見從弟舍人', '再见從弟舍人', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["屈指依稀十五年，鸞臺秘閣位相懸。","分飛淮甸雁行斷，重見江樓蟾影圓。","滯跡未偕朝北闕，高才方命入西川。","願君通理須還早，拜慶慈親几杖前。"]', '["屈指依稀十五年，鸾台秘閣位相懸。","分飞淮甸雁行斷，重见江楼蟾影圓。","滯跡未偕朝北闕，高才方命入西川。","願君通理須還早，拜慶慈親几杖前。"]', '诗', 'shi', '', NULL, '再見從弟舍人 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e80b3f-36ee-4843-b3e6-fe0e6f01a704', '春晝醉眠', '春晝醉眠', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["朱欄芳草綠纖纖，欹枕高堂捲晝簾。","處處落花春寂寂，時時中酒病懨懨。","塞鴻信斷雖堪訝，梁燕詞多且莫嫌。","自有卷書銷永日，霜華未用鬢邊添。"]', '["朱欄芳草綠纖纖，欹枕高堂捲晝簾。","处处落花春寂寂，时时中酒病懨懨。","塞鴻信斷雖堪訝，梁燕词多且莫嫌。","自有卷书銷永日，霜华未用鬢邊添。"]', '诗', 'shi', '', NULL, '春晝醉眠 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d191843-cb7d-4d85-af7f-a0f55e19915e', '中夏晝臥', '中夏晝臥', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["寂寂無聊九夏中，傍簷依壁待清風。","壯圖奇策無人問，不及南陽一臥龍。"]', '["寂寂無聊九夏中，傍簷依壁待清风。","壯圖奇策無人问，不及南陽一臥龙。"]', '诗', 'shi', '', NULL, '中夏晝臥 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35155334-7e02-4412-8907-5015a699b8af', '春夕寓興', '春夕寓兴', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["忘憂何必在庭萱，是事悠悠竟可寬。","酒病未能辭錦里，春狂又擬入桃源。","風吹楊柳絲千縷，月照梨花雪萬團。","閑泥金徽度芳夕，幽泉石上自潺湲。"]', '["忘憂何必在庭萱，是事悠悠竟可寬。","酒病未能辞錦里，春狂又擬入桃源。","风吹楊柳絲千縷，月照梨花雪万團。","闲泥金徽度芳夕，幽泉石上自潺湲。"]', '诗', 'shi', '', NULL, '春夕寓興 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0913f0e1-00e7-451b-8ef1-896f463d4237', '春夜', '春夜', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["薄薄春雲籠皓月，杏花滿地堆香雪。","醉垂羅袂倚朱欄，小數玉仙歌未闋。"]', '["薄薄春云籠皓月，杏花满地堆香雪。","醉垂羅袂倚朱欄，小數玉仙歌未闋。"]', '诗', 'shi', '', NULL, '春夜 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1e0b44-8cc6-47b3-8357-b05d07cd912c', '訪飲妓不遇招酒徒不至', '訪饮妓不遇招酒徒不至', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["小橋流水接平沙，何處行雲不在家。","畢卓未來輕竹葉，劉晨重到殢桃花。","琴樽冷落春將盡，幃幌蕭條日又斜。","回首却尋芳草路，金鞍拂柳思無涯。"]', '["小橋流水接平沙，何处行云不在家。","畢卓未来轻竹葉，劉晨重到殢桃花。","琴樽冷落春將尽，幃幌蕭條日又斜。","回首却尋芳草路，金鞍拂柳思無涯。"]', '诗', 'shi', '', NULL, '訪飲妓不遇招酒徒不至 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc01ec28-7e26-4067-9733-c4de83956f9a', '春宴河亭', '春宴河亭', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["柳擺輕絲拂嫩黃，檻前流水滿池塘。","一筵金翠臨芳岸，四面煙花出粉牆。","舞袖逐風翻繡浪，歌塵隨燕下雕梁。","蠻箋象管休凝思，且放春心入醉鄉。"]', '["柳擺轻絲拂嫩黄，檻前流水满池塘。","一筵金翠臨芳岸，四面煙花出粉牆。","舞袖逐风翻繡浪，歌塵隨燕下雕梁。","蠻箋象管休凝思，且放春心入醉乡。"]', '诗', 'shi', '', NULL, '春宴河亭 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab792d4d-0cf0-46c5-8a44-df20d5649242', '蜀都道中', '蜀都道中', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["劒關雲棧亂崢嶸，得喪何由險與平。","千載龜城終失守，一堆鬼錄漫留名。","季年必不延昏主，薄賞那堪激懦兵。","李特後來多二世，納降歸擬盡公卿。"]', '["劒关云棧亂崢嶸，得喪何由險與平。","千載龟城終失守，一堆鬼錄漫留名。","季年必不延昏主，薄賞那堪激懦兵。","李特後来多二世，納降归擬尽公卿。"]', '诗', 'shi', '', NULL, '蜀都道中 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cda7e435-20d4-409f-9916-f4286a28d1cc', '萬葛樹', '万葛樹', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["葉如羽蓋豈堪論，百步清陰鎖綠雲。","善政已聞思召伯，英風偏稱號將軍。","靜鋪講席麟經潤，高拂□枝兔影分。","更有歲寒霜雪操，莫將樗櫟擬相羣。"]', '["葉如羽蓋豈堪論，百步清陰鎖綠云。","善政已闻思召伯，英风偏稱號將軍。","静鋪講席麟經潤，高拂□枝兔影分。","更有歲寒霜雪操，莫將樗櫟擬相羣。"]', '诗', 'shi', '', NULL, '萬葛樹 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e8a61c-63ad-4cdc-bd85-ec728a232b22', '春夕遣懷', '春夕遣懷', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["窮通分定莫淒涼，且放歡情入醉鄉。","范蠡扁舟終去相，馮唐半世只爲郎。","風飄玉笛梅初落，酒汎金樽月未央。","休把虛名撓懷抱，九原丘隴盡侯王。"]', '["窮通分定莫淒涼，且放歡情入醉乡。","范蠡扁舟終去相，馮唐半世只爲郎。","风飄玉笛梅初落，酒汎金樽月未央。","休把虛名撓懷抱，九原丘隴尽侯王。"]', '诗', 'shi', '', NULL, '春夕遣懷 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b78742-4d1c-447d-9816-d05eac921a2c', '西齋', '西斋', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["西齋新竹兩三莖，也有風敲碎玉聲。","莫恨移來欄檻遠，譬如元本此間生。"]', '["西斋新竹兩三莖，也有风敲碎玉声。","莫恨移来欄檻远，譬如元本此间生。"]', '诗', 'shi', '', NULL, '西齋 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df7a1a7-b5f6-4e68-917f-45d51ae6b368', '新蟬', '新蟬', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["齊女屏幃失舊容，侍中冠冕有芳蹤。","翅翻晚鬢尋香露，聲引秋絲逐遠風。","旅館聽時髭欲白，戍樓聞處葉多紅。","只知送恨添愁事，誰見凌霄羽蛻功。"]', '["齊女屏幃失旧容，侍中冠冕有芳蹤。","翅翻晚鬢尋香露，声引秋絲逐远风。","旅館听时髭欲白，戍楼闻处葉多紅。","只知送恨添愁事，誰见凌霄羽蛻功。"]', '诗', 'shi', '', NULL, '新蟬 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04272af5-beb9-40ec-83e6-821eea50bb7e', '寄滑州文秀大師', '寄滑州文秀大師', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["分飛屈指十三年，菡萏峰前別社蓮。","薄宦偶然來左蜀，孤雲何事在南燕。","一封瑤簡音初達，兩處金沙色共圓。","珍重湯休惠佳句，郡齋吟久不成眠。"]', '["分飞屈指十三年，菡萏峰前別社蓮。","薄宦偶然来左蜀，孤云何事在南燕。","一封瑤簡音初達，兩处金沙色共圓。","珍重湯休惠佳句，郡斋吟久不成眠。"]', '诗', 'shi', '', NULL, '寄滑州文秀大師 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a97c7b-96bc-44c3-b080-e18c455e35d3', '中春登樓 一', '中春登楼 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["金杯不以滌愁腸，江郡芳時憶故鄉。","兩岸煙花春富貴，一樓風月夜淒涼。","王章莫耻牛衣淚，潘岳休驚鶴鬢霜。","歸去蓮花歸未得，白雲深處有茅堂。"]', '["金杯不以滌愁腸，江郡芳时憶故乡。","兩岸煙花春富貴，一楼风月夜淒涼。","王章莫耻牛衣泪，潘岳休驚鹤鬢霜。","归去蓮花归未得，白云深处有茅堂。"]', '诗', 'shi', '', NULL, '中春登樓 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2d8f1c-82e9-4923-9661-4a628ad5aac5', '中春登樓 二', '中春登楼 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["古今通塞莫咨嗟，謾把霜髯敵歲華。","失手已慙蛇有足，用心休爲鼠無牙。","九天雲淨方憐月，一夜風高便厭花。","獨倚郡樓人不會，釣舟春浪接平沙。"]', '["古今通塞莫咨嗟，謾把霜髯敵歲华。","失手已慙蛇有足，用心休爲鼠無牙。","九天云淨方怜月，一夜风高便厭花。","独倚郡楼人不會，釣舟春浪接平沙。"]', '诗', 'shi', '', NULL, '中春登樓 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d5f4a2-cc60-46c5-9ad4-af2070cf25b7', '自遣', '自遣', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["未上亨衢獨醉吟，賦成無處博黃金。","家人莫問張儀舌，國士須知豫讓心。","照乘始堪沽善價，陽春爭忍混凡音。","鵾鵬鱗翼途程在，九萬風雲海浪深。"]', '["未上亨衢独醉吟，賦成無处博黄金。","家人莫问張儀舌，国士須知豫讓心。","照乘始堪沽善價，陽春爭忍混凡音。","鵾鵬鱗翼途程在，九万风云海浪深。"]', '诗', 'shi', '', NULL, '自遣 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b785ca86-72a6-455b-b8f5-2d9dcfedf411', '偶有下殤因而自遣', '偶有下殤因而自遣', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["彭壽殤齡共兩空，幻泡緣影夢魂中。","缺圓宿會長如月，飄忽浮生疾似風。","修短百年先後定，賢愚千古是非同。","南柯太守知人意，休問陶陶塞上翁。"]', '["彭壽殤齡共兩空，幻泡緣影梦魂中。","缺圓宿會长如月，飄忽浮生疾似风。","修短百年先後定，賢愚千古是非同。","南柯太守知人意，休问陶陶塞上翁。"]', '诗', 'shi', '', NULL, '偶有下殤因而自遣 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b057ee-e776-4a4d-9f5f-9123f67dc8e8', '倦學', '倦学', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["樂廣亡來冰鏡稀，宓妃嫫母混妍媸。","且於霧裏藏玄豹，休向窗中問碧雞。","百氏典墳空自苦，一堆螢雪竟誰知。","門前春色芳如晝，好掩書齋任所之。"]', '["乐廣亡来冰镜稀，宓妃嫫母混妍媸。","且於霧裏藏玄豹，休向窗中问碧雞。","百氏典墳空自苦，一堆螢雪竟誰知。","门前春色芳如晝，好掩书斋任所之。"]', '诗', 'shi', '', NULL, '倦學 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e5b2367-1ade-4758-a224-6d54b1342d30', '去年今日', '去年今日', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["去年今日到榮州，五騎紅塵入郡樓。","貔虎只知迎太守，蠻夷不信是儒流。","姦豪已息時將泰，疲瘵全蘇歲又周。","聖主若容辭重祿，便歸煙水狎羣鷗。"]', '["去年今日到榮州，五騎紅塵入郡楼。","貔虎只知迎太守，蠻夷不信是儒流。","姦豪已息时將泰，疲瘵全蘇歲又周。","聖主若容辞重祿，便归煙水狎羣鷗。"]', '诗', 'shi', '', NULL, '去年今日 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e4ba77c-a082-4525-af10-67108892ff89', '晝寢', '晝寢', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["花落青苔錦數重，書淫不覺避春慵。","[恣]情枕上飛莊蝶，任爾雲間騁陸龍。","玉液未能消氣魄，牙籤方可滌昏蒙。","起來已被詩魔引，窗外寒敲翠竹風。"]', '["花落青苔錦數重，书淫不覺避春慵。","[恣]情枕上飞莊蝶，任爾云间騁陸龙。","玉液未能消氣魄，牙籤方可滌昏蒙。","起来已被诗魔引，窗外寒敲翠竹风。"]', '诗', 'shi', '', NULL, '晝寢 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1eb9ccb-d9a5-4302-bb38-0cfd417aa945', '郡齋寓興', '郡斋寓兴', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["依約樊川似旭川，郡齋風物盡蕭然。","秋庭碧蘚鋪雲錦，晚閣紅蕖簇水仙。","醉筆語狂揮粉壁，歌梁塵亂拂花鈿。","情懷放蕩無羈束，地角天涯亦信緣。"]', '["依約樊川似旭川，郡斋风物尽蕭然。","秋庭碧蘚鋪云錦，晚閣紅蕖簇水仙。","醉笔語狂揮粉壁，歌梁塵亂拂花鈿。","情懷放蕩無羈束，地角天涯亦信緣。"]', '诗', 'shi', '', NULL, '郡齋寓興 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b9a822-7bf9-4d12-9754-255d5f0207bb', '郡樓閑望書懷', '郡楼闲望书懷', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["郡城樓閣繞江濱，風物清秋入望頻。","銅鼓祭龍雲塞廟，蘆花飄市雪黏人。","蓮披淨沼羣香散，鷺點寒煙玉片新。","歸去杜陵池館在，且將朝服拂埃塵。"]', '["郡城楼閣繞江濱，风物清秋入望頻。","銅鼓祭龙云塞廟，蘆花飄市雪黏人。","蓮披淨沼羣香散，鷺点寒煙玉片新。","归去杜陵池館在，且將朝服拂埃塵。"]', '诗', 'shi', '', NULL, '郡樓閑望書懷 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6f2c0a-7d4d-4f45-b072-f8c800fb50cd', '玉燭花', '玉燭花', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["嫋嫋香英三四枝，亭亭紅豔照階墀。","正當晚檻初開處，却似春闈就試時。","少女不吹方熠爚，東君偏惜未離披。","夜深斜倚朱欄外，擬把鄰光借與誰。"]', '["嫋嫋香英三四枝，亭亭紅豔照階墀。","正當晚檻初开处，却似春闈就試时。","少女不吹方熠爚，东君偏惜未離披。","夜深斜倚朱欄外，擬把鄰光借與誰。"]', '诗', 'shi', '', NULL, '玉燭花 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450bba5d-674c-4954-88fe-e72cdb16922a', '從弟舍人惠茶', '從弟舍人惠茶', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["曾求芳茗貢蕪詞，果沐頒霑味甚奇。","龜背起紋輕炙處，雲頭翻液乍烹時。","老丞倦悶偏宜矣，舊客過從別有之。","珍重宗親相寄惠，水亭山閣自攜持。"]', '["曾求芳茗貢蕪词，果沐頒霑味甚奇。","龟背起紋轻炙处，云头翻液乍烹时。","老丞倦悶偏宜矣，旧客過從別有之。","珍重宗親相寄惠，水亭山閣自携持。"]', '诗', 'shi', '', NULL, '從弟舍人惠茶 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc081df-cbdb-4166-8a1c-1ba8ec2960d8', '再看光福寺牡丹', '再看光福寺牡丹', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["去年曾看牡丹花，蛺蝶迎人傍彩霞。","今日再遊光福寺，春風吹我入仙家。","當筵芬馥歌唇動，倚檻嬌羞醉眼斜。","來歲未朝金闕去，依前和露載歸衙。"]', '["去年曾看牡丹花，蛺蝶迎人傍彩霞。","今日再游光福寺，春风吹我入仙家。","當筵芬馥歌唇动，倚檻嬌羞醉眼斜。","来歲未朝金闕去，依前和露載归衙。"]', '诗', 'shi', '', NULL, '再看光福寺牡丹 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607932b6-49ce-400a-8eab-29c22551a9af', '海棠花', '海棠花', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["淡淡微紅色不深，依依偏得似春心。","煙輕虢國顰歌黛，露重長門斂淚衿。","低傍繡簾人易折，密藏香蘂蝶難尋。","良宵更有多情處，月下芬芳伴醉吟。"]', '["淡淡微紅色不深，依依偏得似春心。","煙轻虢国顰歌黛，露重长门斂泪衿。","低傍繡簾人易折，密藏香蘂蝶难尋。","良宵更有多情处，月下芬芳伴醉吟。"]', '诗', 'shi', '', NULL, '海棠花 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f18a35-a520-4e27-9a8a-bbb50590b6ad', '新竹', '新竹', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["近窗臥砌兩三叢，佐靜添幽別有功。","影鏤碎金初透月，聲敲寒玉乍搖風。","無憑費叟煙波碧，莫信湘妃淚點紅。","自是子猷偏愛爾，虛心高節雪霜中。"]', '["近窗臥砌兩三叢，佐静添幽別有功。","影鏤碎金初透月，声敲寒玉乍搖风。","無憑費叟煙波碧，莫信湘妃泪点紅。","自是子猷偏愛爾，虛心高節雪霜中。"]', '诗', 'shi', '', NULL, '新竹 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6377a0-bfc4-4271-bbf5-4d27cd90f5b7', '木芙蓉', '木芙蓉', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["素靈失律詐風流，強把芳菲半載偷。","是葉葳蕤霜照夜，此花爛熳火燒秋。","謝蓮色淡爭堪種，陶菊香穠亦合羞。","誰道金風能肅物，因何厚薄不相侔。"]', '["素靈失律詐风流，強把芳菲半載偷。","是葉葳蕤霜照夜，此花爛熳火燒秋。","謝蓮色淡爭堪種，陶菊香穠亦合羞。","誰道金风能肅物，因何厚薄不相侔。"]', '诗', 'shi', '', NULL, '木芙蓉 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2abd0a39-8b8c-434a-a3e5-0a04b9b90fad', '送二郎君歸長安', '送二郎君归长安', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["我兒辭去淚雙流，蜀郡秦川兩處愁。","紅葉滿山歸故國，黃茅徧地住他州。","荷衣曉挂慙官吏，菱鏡秋窺訝鬢髹。","好向雲泉營舊隱，莫教莊叟畏犧牛。"]', '["我兒辞去泪雙流，蜀郡秦川兩处愁。","紅葉满山归故国，黄茅徧地住他州。","荷衣晓挂慙官吏，菱镜秋窺訝鬢髹。","好向云泉營旧隐，莫教莊叟畏犧牛。"]', '诗', 'shi', '', NULL, '送二郎君歸長安 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fa6585-5e71-4eb2-a24f-4c77605e751c', '送文英大師', '送文英大師', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["屈指平陽別社蓮，蟾光一百度曾圓。","孤雲自在知何處，薄宦參差亦信緣。","山郡披風方穆若，花時分袂更淒然。","搖鞭相送嘉陵岸，回首羣峰隔翠煙。"]', '["屈指平陽別社蓮，蟾光一百度曾圓。","孤云自在知何处，薄宦參差亦信緣。","山郡披风方穆若，花时分袂更淒然。","搖鞭相送嘉陵岸，回首羣峰隔翠煙。"]', '诗', 'shi', '', NULL, '送文英大師 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b6bf724-41ad-4811-950d-30c1fce368cd', '酬勾評事', '酬勾評事', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["閑庭欹枕正悲秋，忽覺新編浣遠愁。","才薄只愁安雁戶，年高空憶復漁舟。","鷺翹皓雪臨汀岸，蓮嫋紅香匝郡樓。","對景却慙無藻思，南金荆玉卒難酬。"]', '["闲庭欹枕正悲秋，忽覺新編浣远愁。","才薄只愁安雁戶，年高空憶复漁舟。","鷺翹皓雪臨汀岸，蓮嫋紅香匝郡楼。","对景却慙無藻思，南金荆玉卒难酬。"]', '诗', 'shi', '', NULL, '酬勾評事 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3488e53-0d1f-471a-89e6-c485fb5b06bb', '初至郡界', '初至郡界', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["嘉陵江畔接榮川，兩畔旌旗下瀨船。","郡印已分炎瘴地，朝衣猶惹御爐煙。","蓮塘小飲香隨艇，月榭高吟水壓天。","錦字莫嫌歸路遠，華夷一統太平年。"]', '["嘉陵江畔接榮川，兩畔旌旗下瀨船。","郡印已分炎瘴地，朝衣猶惹御爐煙。","蓮塘小饮香隨艇，月榭高吟水壓天。","錦字莫嫌归路远，华夷一統太平年。"]', '诗', 'shi', '', NULL, '初至郡界 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195043de-c9e6-4c7b-98db-f367cc71b237', '到郡後有寄', '到郡後有寄', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["蜀路新修盡坦平，交親深幸再逢迎。","正當返袂思鄉國，却似歸家見弟兄。","霑澤只慙堯綍重，泝流還喜范舟輕。","欲將感戀裁書旨，多少漁箋寫得成。"]', '["蜀路新修尽坦平，交親深幸再逢迎。","正當返袂思乡国，却似归家见弟兄。","霑澤只慙堯綍重，泝流還喜范舟轻。","欲將感戀裁书旨，多少漁箋寫得成。"]', '诗', 'shi', '', NULL, '到郡後有寄 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4ed997-c2b4-4ca8-8841-2ec44c9c870c', '長春節', '长春節', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["聖朝佳節遇長春，跪捧金爐祝又焚。","寶藏發來天地秀，兵戈銷後帝皇尊。","太平基址千年永，混一車書萬古存。","更有馨香滿芳檻，和風遲日在蘭蓀。"]', '["聖朝佳節遇长春，跪捧金爐祝又焚。","寶藏發来天地秀，兵戈銷後帝皇尊。","太平基址千年永，混一车书万古存。","更有馨香满芳檻，和风遲日在蘭蓀。"]', '诗', 'shi', '', NULL, '長春節 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77b23db4-167c-4cb4-a207-75f606b754e4', '登郡樓書事', '登郡楼书事', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["偶奉綸書蒞旭川，郡樓嘉致盡依然。","松欹鳥道雲藏寺，月滿漁舟水浸天。","望帝古祠花簇簇，錦城歸路草芊芊。","有時倚檻垂雙袂，故國風光似眼前。"]', '["偶奉綸书蒞旭川，郡楼嘉致尽依然。","松欹鸟道云藏寺，月满漁舟水浸天。","望帝古祠花簇簇，錦城归路草芊芊。","有时倚檻垂雙袂，故国风光似眼前。"]', '诗', 'shi', '', NULL, '登郡樓書事 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9148b4d9-2717-4123-b6b4-2244559a6220', '旭川祁宰思家而卒因述意呈秦川知己', '旭川祁宰思家而卒因述意呈秦川知己', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["歲稔民康絕訟論，政成公暇自由身。","朝看五馬閑如社，夜擁雙姬煖似春。","家計不憂憑冢子，官資無愧是朝臣。","豈同齷齪祁員外，至死悲涼一婦人。"]', '["歲稔民康絕訟論，政成公暇自由身。","朝看五马闲如社，夜擁雙姬煖似春。","家計不憂憑冢子，官資無愧是朝臣。","豈同齷齪祁員外，至死悲涼一婦人。"]', '诗', 'shi', '', NULL, '旭川祁宰思家而卒因述意呈秦川知己 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f586c2fe-fee8-421e-bd73-71b94d555f54', '登郡樓書懷 一', '登郡楼书懷 一', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["煙雨樓臺漸晦冥，錦江澄碧浪花平。","卞和未雪荆山耻，莊舃空傷越國情。","天際寂寥無雁下，雲端依約有僧行。","登高欲繼離騷詠，魂斷愁深寫不成。"]', '["煙雨楼台漸晦冥，錦江澄碧浪花平。","卞和未雪荆山耻，莊舃空傷越国情。","天際寂寥無雁下，云端依約有僧行。","登高欲繼離騷詠，魂斷愁深寫不成。"]', '诗', 'shi', '', NULL, '登郡樓書懷 一 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9783f6-7082-4c36-872f-0f04daa43a25', '登郡樓書懷 二', '登郡楼书懷 二', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["邊郡荒涼悲且歌，故園迢遰隔煙波。","琴聲背俗終如是，劍氣衝星又若何。","朝客漸通書信少，釣舟頻引夢魂多。","北山更有移文者，白首無塵歸去麽。"]', '["邊郡荒涼悲且歌，故园迢遰隔煙波。","琴声背俗終如是，劍氣衝星又若何。","朝客漸通书信少，釣舟頻引梦魂多。","北山更有移文者，白首無塵归去麽。"]', '诗', 'shi', '', NULL, '登郡樓書懷 二 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b11099-8cd4-46c7-b791-75e77b51bb9a', '登郡樓書懷 三', '登郡楼书懷 三', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["莫嗔阮氏哭途窮，萬代深沈恨亦同。","瑞玉豈知將抵鵲，鉛刀何事却屠龍。","九夷欲適嗟吾道，五柳終歸效古風。","獨倚郡樓無限意，滿江煙雨正冥濛。"]', '["莫嗔阮氏哭途窮，万代深沈恨亦同。","瑞玉豈知將抵鵲，鉛刀何事却屠龙。","九夷欲適嗟吾道，五柳終归效古风。","独倚郡楼無限意，满江煙雨正冥濛。"]', '诗', 'shi', '', NULL, '登郡樓書懷 三 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a913591-73bd-4bae-8ba1-24112dbedfa7', '偶聞官吏舉請輒有一篇寄從弟舍人', '偶闻官吏舉請輒有一篇寄從弟舍人', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["官吏潛陳借寇詞，宦情鄉夢兩相違。","青城錦水無心住，紫閣蓮峯有意歸。","張翰鱸魚因醉憶，孟光書信近春稀。","黃茅瘴色看看起，貪者猶疑別是機。"]', '["官吏潛陳借寇词，宦情乡梦兩相違。","青城錦水無心住，紫閣蓮峯有意归。","張翰鱸鱼因醉憶，孟光书信近春稀。","黄茅瘴色看看起，貪者猶疑別是機。"]', '诗', 'shi', '', NULL, '偶聞官吏舉請輒有一篇寄從弟舍人 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0066f9f7-a694-452c-abb3-25c34dd96bb7', '誡是非', '誡是非', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["巧舌如簧總莫聽，是非多自愛憎生。","三人告母雖投[杼]，百犬聞風只吠聲。","辨玉且寬和氏罪，誣金須認不疑情。","因思疇昔遊談者，六國交馳亦受烹。"]', '["巧舌如簧總莫听，是非多自愛憎生。","三人告母雖投[杼]，百犬闻风只吠声。","辨玉且寬和氏罪，誣金須認不疑情。","因思疇昔游談者，六国交驰亦受烹。"]', '诗', 'shi', '', NULL, '誡是非 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99cd20e9-4d06-496a-9afb-e1b1955d00c8', '簡豎儒', '簡豎儒', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["蹄涔豈信有滄浪，螢火何堪竝太陽。","淵奧未曾探禹穴，矜誇便擬越丘牆。","小巫神氣終須怯，下里音聲必不長。","近日冰壺多晦昧，虎皮羊質也觀光。"]', '["蹄涔豈信有滄浪，螢火何堪竝太陽。","淵奧未曾探禹穴，矜誇便擬越丘牆。","小巫神氣終須怯，下里音声必不长。","近日冰壺多晦昧，虎皮羊質也观光。"]', '诗', 'shi', '', NULL, '簡豎儒 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645611be-6595-45d9-a52c-3f89abffd65d', '貽諸學童', '貽諸学童', '7e51695f-19cc-438a-9dc6-12b2ad9eab5a', '唐', '["橫經叉手步還趨，積善方知慶有餘。","五箇小雛離學院，一行新雁入貧居。","攘羊告罪言何直，舐犢牽情理豈虛。","勸汝立身須苦志，月中丹桂自扶疎。"]', '["橫經叉手步還趨，積善方知慶有餘。","五箇小雛離学院，一行新雁入貧居。","攘羊告罪言何直，舐犢牽情理豈虛。","勸汝立身須苦志，月中丹桂自扶疎。"]', '诗', 'shi', '', NULL, '貽諸學童 劉兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fdb9ab5-3dd3-4427-88cf-3f254d2ca8e1', '吳 黃金車', '吳 黄金车', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["分擘山河即漸開，許昌基業已傾頹。","黃金車與斑斕耳，早個須知入讖來。"]', '["分擘山河即漸开，許昌基業已傾頹。","黄金车與斑斕耳，早個須知入讖来。"]', '诗', 'shi', '', NULL, '吳 黃金車 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20faa02b-b327-4fbe-8a40-8826c4592888', '吳 赤壁', '吳 赤壁', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["會獵書來舉國驚，祗應周魯不教迎。","曹公一戰奔波後，赤壁功傳萬古名。"]', '["會獵书来舉国驚，祗應周魯不教迎。","曹公一戰奔波後，赤壁功傳万古名。"]', '诗', 'shi', '', NULL, '吳 赤壁 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd6af9a-5019-46d5-ac95-67ff64fcc05e', '吳 魯肅指囷', '吳 魯肅指囷', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["破產移家事亦難，佐吳從此霸江山。","爭教不立功勳得，指出千囷如等閑。"]', '["破產移家事亦难，佐吳從此霸江山。","爭教不立功勳得，指出千囷如等闲。"]', '诗', 'shi', '', NULL, '吳 魯肅指囷 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c18b40f-01b3-45d4-ac00-6a95655c0d42', '吳 甘寧斫營', '吳 甘寧斫營', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["夜深偷入魏軍營，滿寨驚忙火似星。","百口寶刀千匹絹，也應消得與甘寧。"]', '["夜深偷入魏軍營，满寨驚忙火似星。","百口寶刀千匹絹，也應消得與甘寧。"]', '诗', 'shi', '', NULL, '吳 甘寧斫營 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d61e081-87e4-434a-bce7-77a9743d5471', '吳 徐盛', '吳 徐盛', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["欲把江山鼎足分，邢真銜冊到江南。","當時將相誰堪重，徐盛將軍最不甘。"]', '["欲把江山鼎足分，邢真銜冊到江南。","當时將相誰堪重，徐盛將軍最不甘。"]', '诗', 'shi', '', NULL, '吳 徐盛 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b0e36d-a65b-4419-8094-86cd3337bbdf', '吳 魯肅', '吳 魯肅', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["斫案興言斷衆疑，鼎分從此定雄雌。","若無子敬心相似，爭得烏林破魏師。"]', '["斫案兴言斷衆疑，鼎分從此定雄雌。","若無子敬心相似，爭得烏林破魏師。"]', '诗', 'shi', '', NULL, '吳 魯肅 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d75fd07-e843-44d4-a08c-8c55fa8bda80', '吳 武昌', '吳 武昌', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["西塞山高截九垓，讖謠終日自相催。","武昌魚美應難戀，曆數須歸建業來。"]', '["西塞山高截九垓，讖謠終日自相催。","武昌鱼美應难戀，曆數須归建業来。"]', '诗', 'shi', '', NULL, '吳 武昌 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2872e675-29c0-451d-a341-5bad5c6a6cb8', '吳 顧雍', '吳 顧雍', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["贊國經綸更有誰，蔡公相歎亦相師。","貴爲丞相封侯了，歸後家人總不知。"]', '["贊国經綸更有誰，蔡公相歎亦相師。","貴爲丞相封侯了，归後家人總不知。"]', '诗', 'shi', '', NULL, '吳 顧雍 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cfeb1e4-a376-4129-af9b-23f77f91bd65', '吳 呂蒙', '吳 呂蒙', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["幼小家貧實可哀，願征行去志難回。","不探虎穴求身達，爭得人間富貴來。"]', '["幼小家貧實可哀，願征行去志难回。","不探虎穴求身達，爭得人间富貴来。"]', '诗', 'shi', '', NULL, '吳 呂蒙 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c52db75-b70c-44fe-98fd-0dad3b2f6b91', '吳 介象', '吳 介象', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["好道君王遇亦難，變通靈異幾多般。","介先生有神仙術，釣得鱸魚在玉盤。"]', '["好道君王遇亦难，变通靈異幾多般。","介先生有神仙術，釣得鱸鱼在玉盤。"]', '诗', 'shi', '', NULL, '吳 介象 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b986c272-8844-43ec-982b-63bf65c39bd9', '吳 濡須塢', '吳 濡須塢', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["風揭洪濤響若雷，枕波爲壘險相隈。","莫言有個濡須塢，幾度曹公失志回。"]', '["风揭洪濤响若雷，枕波爲壘險相隈。","莫言有個濡須塢，幾度曹公失志回。"]', '诗', 'shi', '', NULL, '吳 濡須塢 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf15431d-1ee4-44ea-b9a3-a1de1e6914d6', '吳 周泰', '吳 周泰', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["名與諸公又不同，金瘡痕在滿身中。","不將御蓋宣恩澤，誰信將軍別有功。"]', '["名與諸公又不同，金瘡痕在满身中。","不將御蓋宣恩澤，誰信將軍別有功。"]', '诗', 'shi', '', NULL, '吳 周泰 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59f205d-3f8f-4ac7-abbf-dd42a07a81b6', '吳 張紘', '吳 張紘', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["東部張公與衆殊，共施經畧贊全吳。","陳琳漫自稱雄伯，神氣應須怯大巫。"]', '["东部張公與衆殊，共施經畧贊全吳。","陳琳漫自稱雄伯，神氣應須怯大巫。"]', '诗', 'shi', '', NULL, '吳 張紘 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8708cf61-0147-437d-b6f5-8d0f29383a48', '吳 太史慈', '吳 太史慈', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["聖德招賢遠近知，曹公心計却成欺。","陳韓昔日嘗投楚，豈是當歸召得伊。"]', '["聖德招賢远近知，曹公心計却成欺。","陳韓昔日嘗投楚，豈是當归召得伊。"]', '诗', 'shi', '', NULL, '吳 太史慈 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d95b04-ebc2-42c1-9cca-6f248da6c6ef', '吳 孫堅后', '吳 孫堅后', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["委存張公翊聖材，幾將賢德贊文臺。","爭教不霸江山得，日月徵曾入夢來。"]', '["委存張公翊聖材，幾將賢德贊文台。","爭教不霸江山得，日月徵曾入梦来。"]', '诗', 'shi', '', NULL, '吳 孫堅后 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3ec3b1-494e-49df-b1c1-1ccdbca02e2b', '吳 陸統', '吳 陸統', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["將軍身歿有兒孤，虎子爲名教讀書。","更向宮中教騎馬，感君恩重合何如。"]', '["將軍身歿有兒孤，虎子爲名教读书。","更向宮中教騎马，感君恩重合何如。"]', '诗', 'shi', '', NULL, '吳 陸統 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('465ca3c9-d399-4f30-9dc3-7e16ec734442', '吳 青蓋', '吳 青蓋', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["曆數將終勢已摧，不修君德更堪哀。","被他青蓋言相誤，元是須教入晉來。"]', '["曆數將終勢已摧，不修君德更堪哀。","被他青蓋言相誤，元是須教入晉来。"]', '诗', 'shi', '', NULL, '吳 青蓋 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d1e6f6-743c-47f3-b2d5-8a7bcf9b35ae', '晉 七寶鞭', '晉 七寶鞭', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["天命須知豈偶然，亂臣徒欲用兵權。","聖謨廟畧還應別，渾不消他七寶鞭。"]', '["天命須知豈偶然，亂臣徒欲用兵權。","聖謨廟畧還應別，渾不消他七寶鞭。"]', '诗', 'shi', '', NULL, '晉 七寶鞭 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93f39d8-e91b-4b15-b60d-2c10623550db', '晉 庾悅鵝炙', '晉 庾悅鵝炙', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["春暖江南景氣新，子鵝炙美就中珍。","庾家廚盛劉公困，渾弗相貽也惱人。"]', '["春暖江南景氣新，子鵝炙美就中珍。","庾家廚盛劉公困，渾弗相貽也惱人。"]', '诗', 'shi', '', NULL, '晉 庾悅鵝炙 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c82a64-7a44-4301-9a5c-77eff57f30d7', '晉 謝玄', '晉 謝玄', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["百萬兵來逼合肥，謝玄爲將統雄師。","旌旗首尾千餘里，渾不消他一局棊。"]', '["百万兵来逼合肥，謝玄爲將統雄師。","旌旗首尾千餘里，渾不消他一局棊。"]', '诗', 'shi', '', NULL, '晉 謝玄 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93488d4b-299c-4788-9452-49103cd43b9d', '晉 謝混', '晉 謝混', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["尚主當初偶未成，此時誰合更關情。","可憐謝混風華在，千古翻傳禁臠名。"]', '["尚主當初偶未成，此时誰合更关情。","可怜謝混风华在，千古翻傳禁臠名。"]', '诗', 'shi', '', NULL, '晉 謝混 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595ff87e-6190-4cc0-8639-1e6fb7c952bf', '晉 陸玩', '晉 陸玩', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["陸公高論亦由衷，謙讓還慙未有功。","天下忠良人欲盡，始應交我作三公。"]', '["陸公高論亦由衷，謙讓還慙未有功。","天下忠良人欲尽，始應交我作三公。"]', '诗', 'shi', '', NULL, '晉 陸玩 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4baa4b24-99d2-4e8c-81d4-4f6d9f7bc36e', '晉 王坦之', '晉 王坦之', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["晉祚安危只此行，坦之何必苦憂驚。","謝公合定寰區在，爭遣當時事得成。"]', '["晉祚安危只此行，坦之何必苦憂驚。","謝公合定寰區在，爭遣當时事得成。"]', '诗', 'shi', '', NULL, '晉 王坦之 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99fa083d-1708-4e68-b6c0-8bdf9b2bbbe8', '晉 蒲葵扇', '晉 蒲葵扇', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["拋捨東山歲月遙，幾施經畧挫雄豪。","若非名德喧寰宇，爭得蒲葵價數高。"]', '["拋捨东山歲月遙，幾施經畧挫雄豪。","若非名德喧寰宇，爭得蒲葵價數高。"]', '诗', 'shi', '', NULL, '晉 蒲葵扇 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a93474-ff61-4362-912c-760138929e9f', '晉 王郎', '晉 王郎', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["太尉門庭亦甚高，王郎名重禮相饒。","自家妻父猶如此，誰更逢君得折腰。"]', '["太尉门庭亦甚高，王郎名重禮相饒。","自家妻父猶如此，誰更逢君得折腰。"]', '诗', 'shi', '', NULL, '晉 王郎 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00b0d5a0-bf63-4f5a-9f6c-718ccc5d3a26', '晉 劉毅', '晉 劉毅', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["遶牀堪壯喝盧聲，似鐵容儀衆盡驚。","二十七人同舉義，幾人全得舊功名。"]', '["遶牀堪壯喝盧声，似鐵容儀衆尽驚。","二十七人同舉義，幾人全得旧功名。"]', '诗', 'shi', '', NULL, '晉 劉毅 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94bef8b1-78b9-432b-a5d2-2987d529ba48', '晉 王恭', '晉 王恭', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["春風濯濯柳容儀，鶴氅神情舉世推。","可惜教君仗旄鉞，枉將心地託牢之。"]', '["春风濯濯柳容儀，鹤氅神情舉世推。","可惜教君仗旄鉞，枉將心地託牢之。"]', '诗', 'shi', '', NULL, '晉 王恭 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e311a3-726f-49ba-a4bc-3c05d82abf51', '晉 謝公賭墅', '晉 謝公賭墅', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["發遣將軍欲去時，畧無情撓只貪棊。","自從乞與羊曇後，賭墅功成更有誰。"]', '["發遣將軍欲去时，畧無情撓只貪棊。","自從乞與羊曇後，賭墅功成更有誰。"]', '诗', 'shi', '', NULL, '晉 謝公賭墅 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936fd16d-0ba4-48af-9b33-fd5ec6ace67c', '晉 苻堅投箠', '晉 苻堅投箠', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["投箠填江語未終，謝安乘此立殊功。","三台星爛乾坤在，且與張華死不同。"]', '["投箠填江語未終，謝安乘此立殊功。","三台星爛乾坤在，且與張华死不同。"]', '诗', 'shi', '', NULL, '晉 苻堅投箠 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba437da2-5f6b-4a44-8a59-3f832fd7db79', '晉 衛玠', '晉 衛玠', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["叔寶羊車海內稀，山家女壻好風姿。","江東士女無端甚，看殺玉人渾不知。"]', '["叔寶羊车海內稀，山家女壻好风姿。","江东士女無端甚，看殺玉人渾不知。"]', '诗', 'shi', '', NULL, '晉 衛玠 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('608997b6-76fb-4654-bbd9-cd7ff23996d8', '晉 郭璞脫襦', '晉 郭璞脫襦', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["吟坐因思郭景純，每言窮達似通神。","到頭分命難移改，解脫清襦與別人。"]', '["吟坐因思郭景純，每言窮達似通神。","到头分命难移改，解脫清襦與別人。"]', '诗', 'shi', '', NULL, '晉 郭璞脫襦 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175098fa-eb4c-4ba6-907e-39534452efa3', '晉 庾樓', '晉 庾楼', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["江州樓上月明中，從事同登眺遠空。","玉樹忽薶千載後，有誰重此繼清風。"]', '["江州楼上月明中，從事同登眺远空。","玉樹忽薶千載後，有誰重此繼清风。"]', '诗', 'shi', '', NULL, '晉 庾樓 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949348c9-b9a8-4f5d-a5e1-6f960941cc4c', '晉 新亭', '晉 新亭', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["容易乘虛逼帝畿，滿江艛艣與旌旗。","盧循若解新亭上，勝負還應未可知。"]', '["容易乘虛逼帝畿，满江艛艣與旌旗。","盧循若解新亭上，勝負還應未可知。"]', '诗', 'shi', '', NULL, '晉 新亭 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e973d8bb-6146-4668-8a2d-2bfa94711428', '宋 大峴', '宋 大峴', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["大峴纔過喜可知，指空言已副心期。","公孫計策嗟無用，天與南朝作霸基。"]', '["大峴纔過喜可知，指空言已副心期。","公孫計策嗟無用，天與南朝作霸基。"]', '诗', 'shi', '', NULL, '宋 大峴 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8635ff72-f931-4752-b843-614a9a5a0961', '宋 放宮人', '宋 放宮人', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["納諫廷臣免犯顏，自然恩可霸江山。","姚興侍女方承寵，放出宮闈若等閑。"]', '["納諫廷臣免犯顏，自然恩可霸江山。","姚兴侍女方承寵，放出宮闈若等闲。"]', '诗', 'shi', '', NULL, '宋 放宮人 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16eedfc4-88d7-40e8-b09e-ba8fe5aef124', '宋 借南苑', '宋 借南苑', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["人主詞應不偶然，幾人曾說笑掀天。","不知南苑今何在，借與張公三百年。"]', '["人主词應不偶然，幾人曾说笑掀天。","不知南苑今何在，借與張公三百年。"]', '诗', 'shi', '', NULL, '宋 借南苑 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e359f4e5-6d0b-4650-83cc-6e996b912643', '宋 謝澹雲霞友', '宋 謝澹云霞友', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["仗氣凌人豈可親，只將范泰是知聞。","緣何喚作雲霞友，却恐雲霞未似君。"]', '["仗氣凌人豈可親，只將范泰是知闻。","緣何喚作云霞友，却恐云霞未似君。"]', '诗', 'shi', '', NULL, '宋 謝澹雲霞友 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb1b7fe-2804-435a-a8f4-245aed0fc99f', '宋 烏衣巷', '宋 烏衣巷', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["古迹荒基好歎嗟，滿川吟景只煙霞。","烏衣巷在何人住，回首令人憶謝家。"]', '["古迹荒基好歎嗟，满川吟景只煙霞。","烏衣巷在何人住，回首令人憶謝家。"]', '诗', 'shi', '', NULL, '宋 烏衣巷 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c92013-bdc0-4fa4-9eb7-4c12cefe963a', '宋 袁粲', '宋 袁粲', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["負才尚氣滿朝知，高臥閑吟見客稀。","獨步何人識袁尹，白楊郊外醉方歸。"]', '["負才尚氣满朝知，高臥闲吟见客稀。","独步何人識袁尹，白楊郊外醉方归。"]', '诗', 'shi', '', NULL, '宋 袁粲 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4feb86fc-d5e8-490e-96ff-ce4828fd7b49', '宋 劉伯龍', '宋 劉伯龙', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["位重何如不厭貧，伯龍孤子只修身。","固知生計還須有，窮鬼臨時也笑人。"]', '["位重何如不厭貧，伯龙孤子只修身。","固知生計還須有，窮鬼臨时也笑人。"]', '诗', 'shi', '', NULL, '宋 劉伯龍 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddf29a9-dd23-4223-95c5-602387e140c7', '宋 王方平', '宋 王方平', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["拂衣耕釣已多時，江上山前樂可知。","著却貂裘將採藥，任他人喚作漁師。"]', '["拂衣耕釣已多时，江上山前乐可知。","著却貂裘將採藥，任他人喚作漁師。"]', '诗', 'shi', '', NULL, '宋 王方平 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097a9ac1-20c5-4322-9ac9-0ac9ffea0889', '宋 黃羅襦', '宋 黄羅襦', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["戚屬羣臣盡見猜，預憂身後又堪哀。","到頭委付何曾是，虛把羅襦與彥回。"]', '["戚屬羣臣尽见猜，預憂身後又堪哀。","到头委付何曾是，虛把羅襦與彥回。"]', '诗', 'shi', '', NULL, '宋 黃羅襦 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2194c81d-2200-414a-80b1-8e45650102b0', '宋 謝朏', '宋 謝朏', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["謝家諸子盡蘭香，各震芳名滿帝鄉。","惟有千金更堪重，只將高臥向齊王。"]', '["謝家諸子尽蘭香，各震芳名满帝乡。","惟有千金更堪重，只將高臥向齊王。"]', '诗', 'shi', '', NULL, '宋 謝朏 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806e578d-367d-4609-bbc3-ca96a46c57d1', '宋 羊玄保', '宋 羊玄保', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["運命將來各有期，好官才闕即思之。","就中堪愛羊玄保，偏受君王分外知。"]', '["運命將来各有期，好官才闕即思之。","就中堪愛羊玄保，偏受君王分外知。"]', '诗', 'shi', '', NULL, '宋 羊玄保 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea51910-22c4-44ab-871a-a7ac83f764e9', '齊 謝朏', '齊 謝朏', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["解璽傳呼詔侍中，却來高臥豈疏慵。","此時忠節還希有，堪羨君王特地容。"]', '["解璽傳呼詔侍中，却来高臥豈疏慵。","此时忠節還希有，堪羨君王特地容。"]', '诗', 'shi', '', NULL, '齊 謝朏 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf4b849-79d3-4f39-a383-eea07abb3aae', '齊 小兒執燭', '齊 小兒執燭', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["謝公情量已難量，忠宋心誠豈暫忘。","執燭小兒渾放去，略無言語與君王。"]', '["謝公情量已难量，忠宋心誠豈暫忘。","執燭小兒渾放去，略無言語與君王。"]', '诗', 'shi', '', NULL, '齊 小兒執燭 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661c4823-2114-4bc1-9970-d1d4daa8bc51', '齊 王僧祐', '齊 王僧祐', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["肯與公卿作等倫，澹然名德只推君。","任他車騎來相訪，簫鼓盈庭似不聞。"]', '["肯與公卿作等倫，澹然名德只推君。","任他车騎来相訪，簫鼓盈庭似不闻。"]', '诗', 'shi', '', NULL, '齊 王僧祐 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2fe4e3f-f6ab-4df8-a6c6-8a4aad4b03b5', '齊 王僧虔', '齊 王僧虔', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["位高名重不堪疑，懇讓儀同帝亦知。","不學常流爭進取，却憂門有二台司。"]', '["位高名重不堪疑，懇讓儀同帝亦知。","不学常流爭進取，却憂门有二台司。"]', '诗', 'shi', '', NULL, '齊 王僧虔 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecba34f9-c6e8-45e3-bee2-723a4f711bb4', '齊 明帝裹蒸', '齊 明帝裹蒸', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["至尊尊貴異人間，御膳天廚豈等閑。","惜得裹蒸無用處，不如安霸取江山。"]', '["至尊尊貴異人间，御膳天廚豈等闲。","惜得裹蒸無用处，不如安霸取江山。"]', '诗', 'shi', '', NULL, '齊 明帝裹蒸 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf444a2-990d-43d2-aee5-de67df71d49a', '齊 鬱林王', '齊 鬱林王', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["強哀強慘亦從伊，歸到私庭喜可知。","喜字漫書三十六，到頭能得幾多時。"]', '["強哀強慘亦從伊，归到私庭喜可知。","喜字漫书三十六，到头能得幾多时。"]', '诗', 'shi', '', NULL, '齊 鬱林王 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f8e75b-407c-4d67-9d8d-bc303517bf4c', '齊 何氏小山', '齊 何氏小山', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["顯達何曾肯繫心，築居郊外好園林。","賺他謝朏出山去，贏得高名直至今。"]', '["显達何曾肯繫心，築居郊外好园林。","賺他謝朏出山去，贏得高名直至今。"]', '诗', 'shi', '', NULL, '齊 何氏小山 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1e8545d-87e4-454d-a632-ec0988107271', '齊 王倫之', '齊 王倫之', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["豫章太守重詞林，圖畫陳蕃與華歆。","更奠子將幷孺子，爲君千載作知音。"]', '["豫章太守重词林，圖畫陳蕃與华歆。","更奠子將幷孺子，爲君千載作知音。"]', '诗', 'shi', '', NULL, '齊 王倫之 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17b3a1a0-1f9f-419d-a7a8-f5ca86b7e936', '齊 潘妃', '齊 潘妃', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["曾步金蓮寵絕倫，豈甘今日委埃塵。","玉兒還有懷恩處，不肯將身嫁小臣。"]', '["曾步金蓮寵絕倫，豈甘今日委埃塵。","玉兒還有懷恩处，不肯將身嫁小臣。"]', '诗', 'shi', '', NULL, '齊 潘妃 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085adf86-1ddf-4c7b-a094-c605472201da', '齊 王亮', '齊 王亮', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["後見梁王未免哀，奈何無計拯傾頹。","若教彼相顛扶得，爭遣明公到此來。"]', '["後见梁王未免哀，奈何無計拯傾頹。","若教彼相顛扶得，爭遣明公到此来。"]', '诗', 'shi', '', NULL, '齊 王亮 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('842fba13-93e6-45bd-90b8-549319543770', '梁 分宮女', '梁 分宮女', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["滌蕩齊宮法令新，分張宮女二千人。","可憐無限如花貌，重見世間桃李春。"]', '["滌蕩齊宮法令新，分張宮女二千人。","可怜無限如花貌，重见世间桃李春。"]', '诗', 'shi', '', NULL, '梁 分宮女 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c3113b-d02d-47fb-a208-6e3160b8aaa8', '梁 馬仙埤', '梁 马仙埤', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["齊朝太守不甘降，忠節當時動四方。","義士要教天下見，且留君住待袁昂。"]', '["齊朝太守不甘降，忠節當时动四方。","義士要教天下见，且留君住待袁昂。"]', '诗', 'shi', '', NULL, '梁 馬仙埤 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b9f8aa2-813e-46dd-8b1a-15ed7e121367', '梁 勍敵', '梁 勍敵', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["傳聞天子重儒才，特爲皇華綺宴開。","今日方驚遇勍敵，此人元自北朝來。"]', '["傳闻天子重儒才，特爲皇华綺宴开。","今日方驚遇勍敵，此人元自北朝来。"]', '诗', 'shi', '', NULL, '梁 勍敵 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f38bc8-a6d3-4b3a-b183-eca22a7a886f', '梁 蔡撙', '梁 蔡撙', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["紫茄白莧以爲珍，守任清真轉更貧。","不飲吳興郡中水，古今能有幾多人。"]', '["紫茄白莧以爲珍，守任清真轉更貧。","不饮吳兴郡中水，古今能有幾多人。"]', '诗', 'shi', '', NULL, '梁 蔡撙 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26cbaab-ccf0-45bd-b0ef-3e90d4e31d78', '梁 楚祠', '梁 楚祠', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["曾與蕭侯醉玉桮，此時神影盡傾頹。","莫云千古無靈聖，也向西川助敵來。"]', '["曾與蕭侯醉玉桮，此时神影尽傾頹。","莫云千古無靈聖，也向西川助敵来。"]', '诗', 'shi', '', NULL, '梁 楚祠 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02c01ff4-e324-4d1d-906e-a5668ec96029', '梁 謝朏小輿', '梁 謝朏小輿', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["小輿升殿掌鈞台，不免無憀却憶回。","應恨被他何胤誤，悔先容易出山來。"]', '["小輿升殿掌鈞台，不免無憀却憶回。","應恨被他何胤誤，悔先容易出山来。"]', '诗', 'shi', '', NULL, '梁 謝朏小輿 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97d355f-0c96-41c6-910d-37899aaf63e0', '梁 八關齋', '梁 八关斋', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["依憑金地甚虔誠，忍溺空王爲聖明。","內殿設齋申禱祝，豈無功德及臺城。"]', '["依憑金地甚虔誠，忍溺空王爲聖明。","內殿設斋申禱祝，豈無功德及台城。"]', '诗', 'shi', '', NULL, '梁 八關齋 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42dd1ac-fc7d-4487-8f36-e0a7e597321b', '梁 庾信', '梁 庾信', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["苦心詞賦向誰談，淪落周朝志豈甘。","可惜多才庾開府，一生惆悵憶江南。"]', '["苦心词賦向誰談，淪落周朝志豈甘。","可惜多才庾开府，一生惆悵憶江南。"]', '诗', 'shi', '', NULL, '梁 庾信 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f722c666-e64d-4a02-babf-0571a029977e', '陳 王僧辨', '陳 王僧辨', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["彼此英雄各有名，石頭高臥擬爭衡。","當時堪笑王僧辨，待欲將心託聖明。"]', '["彼此英雄各有名，石头高臥擬爭衡。","當时堪笑王僧辨，待欲將心託聖明。"]', '诗', 'shi', '', NULL, '陳 王僧辨 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be1afb4-54ca-4adf-bc04-758a4e5ec6ff', '陳 武帝蚌盤', '陳 武帝蚌盤', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["金翠絲黃略不舒，蚌盤清宴意何如。","豈知三閣繁華日，解爲君王妙破除。"]', '["金翠絲黄略不舒，蚌盤清宴意何如。","豈知三閣繁华日，解爲君王妙破除。"]', '诗', 'shi', '', NULL, '陳 武帝蚌盤 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b05353a-6a61-4908-8b0a-9e19b9d08cfa', '陳 虞居士', '陳 虞居士', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["苦諫將軍總不知，幾隨煙焰作塵飛。","東山居士何人識，惟有君王却許歸。"]', '["苦諫將軍總不知，幾隨煙焰作塵飞。","东山居士何人識，惟有君王却許归。"]', '诗', 'shi', '', NULL, '陳 虞居士 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d86caf5-fc10-4ebc-8d7a-f3688857c71d', '陳 姚察', '陳 姚察', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["曾佐徐陵向北遊，剖陳疑事動名流。","却歸掌選清何甚，一匹花綀不肯收。"]', '["曾佐徐陵向北游，剖陳疑事动名流。","却归掌選清何甚，一匹花綀不肯收。"]', '诗', 'shi', '', NULL, '陳 姚察 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8433b5d-4e0d-419f-be28-25b39fede0c9', '陳 宣帝傷將卒', '陳 宣帝傷將卒', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["前後兵師戰勝回，百餘城壘盡歸來。","當時將卒應知感，況得君王爲舉哀。"]', '["前後兵師戰勝回，百餘城壘尽归来。","當时將卒應知感，況得君王爲舉哀。"]', '诗', 'shi', '', NULL, '陳 宣帝傷將卒 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ce92a9-063a-4091-91a8-42b92556e10d', '陳 臨春閣', '陳 臨春閣', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["臨春高閣上侵雲，風起香飄數里聞。","自是君王正沈醉，豈知消息報隋軍。"]', '["臨春高閣上侵云，风起香飄數里闻。","自是君王正沈醉，豈知消息報隋軍。"]', '诗', 'shi', '', NULL, '陳 臨春閣 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891e5f83-460a-4824-8eff-40709539ffbd', '陳 [結]綺閣', '陳 [結]綺閣', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["結綺高宜眺海涯，上凌丹漢拂雲霞。","一千朱翠同居此，爭奈恩多屬麗華。"]', '["結綺高宜眺海涯，上凌丹漢拂云霞。","一千朱翠同居此，爭奈恩多屬丽华。"]', '诗', 'shi', '', NULL, '陳 [結]綺閣 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d56783b-2d55-4497-9306-f9008d148523', '陳 望僊閣', '陳 望僊閣', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["多少沈檀結築成，望仙爲號倚青冥。","不知孔氏何形狀，醉得君主不解醒。"]', '["多少沈檀結築成，望仙爲號倚青冥。","不知孔氏何形狀，醉得君主不解醒。"]', '诗', 'shi', '', NULL, '陳 望僊閣 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3b34d0-32ce-4f87-a1b5-95585c5b1317', '陳 三閣', '陳 三閣', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["三閣相通綺宴開，數千朱翠遶周回。","只知斷送君王醉，不道韓擒已到來。"]', '["三閣相通綺宴开，數千朱翠遶周回。","只知斷送君王醉，不道韓擒已到来。"]', '诗', 'shi', '', NULL, '陳 三閣 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8cd45dc-274f-4b7f-ba31-2f8932e6c9c1', '陳 狎客', '陳 狎客', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["八宮妃盡賦篇章，風揭歌聲錦繡香。","選得十人爲狎客，有誰能解諫君王。"]', '["八宮妃尽賦篇章，风揭歌声錦繡香。","選得十人爲狎客，有誰能解諫君王。"]', '诗', 'shi', '', NULL, '陳 狎客 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50152499-6d45-4892-b857-6d1f1830cf14', '陳 淮水', '陳 淮水', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["文物衣冠盡入秦，六朝繁盛忽埃塵。","自從淮水乾枯後，不見王家更有人。"]', '["文物衣冠尽入秦，六朝繁盛忽埃塵。","自從淮水乾枯後，不见王家更有人。"]', '诗', 'shi', '', NULL, '陳 淮水 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df67c3cd-47fc-4b31-bca5-bf321e745d99', '陳 江令宅', '陳 江令宅', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["不向南朝立諫名，舊居基在事分明。","令人惆悵江中令，只作篇章過一生。"]', '["不向南朝立諫名，旧居基在事分明。","令人惆悵江中令，只作篇章過一生。"]', '诗', 'shi', '', NULL, '陳 江令宅 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f392e396-6adc-4339-9132-dabc6787532d', '陳 後庭舞', '陳 後庭舞', '29b7d92a-e641-4d15-9836-4fe4ea7d08b7', '唐', '["嬿婉回風態若飛，麗華翹袖玉爲姿。","後庭一曲從教舞，舞破江山君未知。"]', '["嬿婉回风態若飞，丽华翹袖玉爲姿。","後庭一曲從教舞，舞破江山君未知。"]', '诗', 'shi', '', NULL, '陳 後庭舞 孫元晏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eab8c6e-fcf9-45cf-9750-471fc2dbf153', '班倢伃', '班倢伃', '09e6d1c2-93a9-4b77-a2df-3ca89f754eb8', '唐', '["賤妾如桃李，君王若歲時。","秋風一已勁，搖落不勝悲。","寂寂蒼苔滿，沈沈綠草滋。","繁華非此日，指輦競何辭。"]', '["賤妾如桃李，君王若歲时。","秋风一已勁，搖落不勝悲。","寂寂蒼苔满，沈沈綠草滋。","繁华非此日，指輦競何辞。"]', '诗', 'shi', '', NULL, '班倢伃 嚴識玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0723bf-29c7-4277-b1d9-3c12f2f7594a', '賦得御製句朔野陣雲飛', '賦得御製句朔野陣云飞', '77d9fa50-1365-41a1-ae4c-ffb7fe7124e4', '唐', '["塞日穿痕斷，邊鴻背影飛。","縹緲浮黃屋，陰沈護御衣。"]', '["塞日穿痕斷，邊鴻背影飞。","縹緲浮黄屋，陰沈護御衣。"]', '诗', 'shi', '', NULL, '賦得御製句朔野陣雲飛 何象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b7b8b92-a509-4fb1-9b50-bca62b4ec925', '宿金河戍', '宿金河戍', '6c2248fd-fa40-41fb-9fad-986d1f0451dd', '唐', '["朝發鐵麟驛，夕宿金河戍。","奔波急王程，一日千里路。","但見容鬢改，不知歲華暮。","悠悠沙漠行，王事彌多故。"]', '["朝發鐵麟驛，夕宿金河戍。","奔波急王程，一日千里路。","但见容鬢改，不知歲华暮。","悠悠沙漠行，王事彌多故。"]', '诗', 'shi', '', NULL, '宿金河戍 張震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c7c934-5567-451d-8e47-1e736eb6fac0', '補新宮 一', '補新宮 一', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["奐奐新宮，禮樂其融。","爾德惟賢，爾□維忠。","爲忠以公，斯筵是同。","人之醉我，與我延賓。"]', '["奐奐新宮，禮乐其融。","爾德惟賢，爾□維忠。","爲忠以公，斯筵是同。","人之醉我，與我延賓。"]', '诗', 'shi', '', NULL, '補新宮 一 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b06c7fd-46b6-44f6-bed0-9de353df57b7', '補新宮 二', '補新宮 二', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["奐奐新宮，既奐而輪。","其固如山，其儼如雲。","其寢斯安，□□□分。","我既考落，以燕羣臣。"]', '["奐奐新宮，既奐而輪。","其固如山，其儼如云。","其寢斯安，□□□分。","我既考落，以燕羣臣。"]', '诗', 'shi', '', NULL, '補新宮 二 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d42007c-124c-4aa1-94ef-d228140bb294', '補新宮 三', '補新宮 三', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["奐奐新宮，既祭既延。","我□□鏞，于以醉賢。","有禮無愆，我有斯宮。","斯宮以安，康後萬年。"]', '["奐奐新宮，既祭既延。","我□□鏞，于以醉賢。","有禮無愆，我有斯宮。","斯宮以安，康後万年。"]', '诗', 'shi', '', NULL, '補新宮 三 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ddba38c-4ffa-487d-89bf-468826b264de', '補茅鴟 一', '補茅鴟 一', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["茅鴟茅鴟，無集我岡。","汝食汝飽，莫我爲祥。","願彈去汝，來彼鳳凰。","來彼鳳凰，其儀有章。"]', '["茅鴟茅鴟，無集我岡。","汝食汝飽，莫我爲祥。","願彈去汝，来彼鳳凰。","来彼鳳凰，其儀有章。"]', '诗', 'shi', '', NULL, '補茅鴟 一 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de3b6a3-cdf9-43ed-903a-1a098af5c426', '補茅鴟 二', '補茅鴟 二', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["茅鴟茅鴟，無啄我雀。","汝食汝飽，莫我肯略。","願彈去汝，來彼瑞鵲。","來彼瑞鵲，其音可樂。"]', '["茅鴟茅鴟，無啄我雀。","汝食汝飽，莫我肯略。","願彈去汝，来彼瑞鵲。","来彼瑞鵲，其音可乐。"]', '诗', 'shi', '', NULL, '補茅鴟 二 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79874942-d8cc-4d1f-9dd0-d30241d1e20d', '補茅鴟 三', '補茅鴟 三', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["茅鴟茅鴟，無搏鷅鶹。","汝食汝飽，莫我爲休。","願彈去汝，來彼鳲鳩。","來彼鳲鳩，食子其周。"]', '["茅鴟茅鴟，無搏鷅鶹。","汝食汝飽，莫我爲休。","願彈去汝，来彼鳲鳩。","来彼鳲鳩，食子其周。"]', '诗', 'shi', '', NULL, '補茅鴟 三 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5177fc1-3b2d-41b4-befb-c10d8b94ce8f', '補茅鴟 四', '補茅鴟 四', '5651ba07-df61-43cf-b8c1-82eeb6fd5cdc', '唐', '["茅鴟茅鴟，無㗲我陵。","汝食汝飽，莫我好聲。","願彈去汝，來彼蒼鷹。","來彼蒼鷹，祭鳥是徵。"]', '["茅鴟茅鴟，無㗲我陵。","汝食汝飽，莫我好声。","願彈去汝，来彼蒼鷹。","来彼蒼鷹，祭鸟是徵。"]', '诗', 'shi', '', NULL, '補茅鴟 四 丘光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8c0395-f63b-49cf-b055-2b10ea8afb78', '瑕瑜不相掩', '瑕瑜不相掩', '4b68710b-740b-48e1-b894-dc9cec4081e3', '唐', '["抱璞應難辨，妍媸每自融。","貞姿偏特達，微玷遇磨礱。","涇渭流終異，瑕瑜自不同。","半曾光透石，未掩氣如虹。","縝密誠爲智，包藏豈謂忠。","停看分美惡，今得值良工。"]', '["抱璞應难辨，妍媸每自融。","貞姿偏特達，微玷遇磨礱。","涇渭流終異，瑕瑜自不同。","半曾光透石，未掩氣如虹。","縝密誠爲智，包藏豈謂忠。","停看分美惡，今得值良工。"]', '诗', 'shi', '', NULL, '瑕瑜不相掩 武翊黃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccffe9d4-a66c-41ea-b04c-f4b374c83a94', '袁江口懷王司勳王吏部', '袁江口懷王司勳王吏部', 'ac94af6c-3d44-449a-824a-cbab032f381e', '唐', '["京華不啻三千里，客淚如今一萬雙。","若箇最爲相憶處，青楓黃竹入袁江。"]', '["京华不啻三千里，客泪如今一万雙。","若箇最爲相憶处，青楓黄竹入袁江。"]', '诗', 'shi', '', NULL, '袁江口懷王司勳王吏部 李祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafddc67-dc33-441c-8839-8d81601a9b87', '贈進士李守微', '贈進士李守微', '2474b692-b85c-46d4-8a23-f9a0114d1b4f', '唐', '["一定童顏老歲華，貧寒游歷貴人家。","煉成正氣功應大，養得元神道不差。","舃曳鶴毛乾毾𣬬，杖攜筇節瘦槎牙。","如何蓬閬不歸去，落盡蟠桃幾度花。"]', '["一定童顏老歲华，貧寒游歷貴人家。","煉成正氣功應大，養得元神道不差。","舃曳鹤毛乾毾𣬬，杖携筇節瘦槎牙。","如何蓬閬不归去，落尽蟠桃幾度花。"]', '诗', 'shi', '', NULL, '贈進士李守微 韓嶼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02d6505c-901e-4e90-a5da-78a864f9d4f2', '馬上有見', '马上有见', 'dd1cabc8-e03a-4155-ad70-1ea9c05a7c27', '唐', '["行盡疎林見小橋，綠楊深處有紅蕉。","無端眼界無分別，安置心頭不肯銷。"]', '["行尽疎林见小橋，綠楊深处有紅蕉。","無端眼界無分別，安置心头不肯銷。"]', '诗', 'shi', '', NULL, '馬上有見 李茂復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d056a9-ca1e-45ff-af60-7a865eb9cffa', '自歎', '自歎', 'dd1cabc8-e03a-4155-ad70-1ea9c05a7c27', '唐', '["落日西山近一竿，世間恩愛極難𢬵。","近來不作顛狂事，免被冤家惡眼看。"]', '["落日西山近一竿，世间恩愛極难𢬵。","近来不作顛狂事，免被冤家惡眼看。"]', '诗', 'shi', '', NULL, '自歎 李茂復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f09b13c-f19d-45c5-af6e-cf099e8be705', '贈吳圓', '贈吳圓', '99ce9a24-29e1-41a8-9870-1d5fc3354c6e', '唐', '["經年理郡少歡娛，爲習干戈間飲徒。","今日臨行盡交割，分明收取媚川珠。"]', '["經年理郡少歡娛，爲習干戈间饮徒。","今日臨行尽交割，分明收取媚川珠。"]', '诗', 'shi', '', NULL, '贈吳圓 李曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4156ff-c06a-446e-803b-131e304e1440', '答李曜', '答李曜', 'a6369c93-3c07-4aec-ac78-9e0c815869a5', '唐', '["曳履優容日日歡，須言達德倍汍瀾。","韶光今已輸先手，領得蠙珠掌上看。"]', '["曳履優容日日歡，須言達德倍汍瀾。","韶光今已輸先手，領得蠙珠掌上看。"]', '诗', 'shi', '', NULL, '答李曜 吳圓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf25078-3cae-4ad7-9100-5a8512db0b7a', '和訾家洲宴游', '和訾家洲宴游', '1936d485-8d12-42fa-b07c-9d123a0e0b2b', '唐', '["新春蘂綻訾家洲，信是南方最勝游。","酒滿百分殊不怕，人添一歲更堪愁。","鶯聲暗逐歌聲豔，花態還隨舞態羞。","莫惜今朝同酩酊，任他龜鶴與蜉蝣。"]', '["新春蘂綻訾家洲，信是南方最勝游。","酒满百分殊不怕，人添一歲更堪愁。","鶯声暗逐歌声豔，花態還隨舞態羞。","莫惜今朝同酩酊，任他龟鹤與蜉蝣。"]', '诗', 'shi', '', NULL, '和訾家洲宴游 陸弘休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13039106-f805-483a-b073-7e04517c87bf', '題賈島墓', '題賈島墓', 'f74b3488-edc1-4aeb-ba89-321d257bf1bd', '唐', '["倚恃才難繼，昂藏貌不恭。","騎驢衝大尹，奪卷忤宣宗。","馳譽超先輩，居官下我儂。","司倉舊曹署，一見一心忡。"]', '["倚恃才难繼，昂藏貌不恭。","騎驢衝大尹，奪卷忤宣宗。","驰譽超先輩，居官下我儂。","司倉旧曹署，一见一心忡。"]', '诗', 'shi', '', NULL, '題賈島墓 安錡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d3aec4-a237-4e5b-97d2-43957c68c4a2', '贈別營妓卿卿', '贈別營妓卿卿', '9967f9ae-0c8b-4c77-86d5-a2413b8734f1', '唐', '["憐君無那是多情，枕上相看直到明。","日照綠窗人去住，鴉啼紅粉淚縱橫。","愁腸只向金閨斷，白髮應從玉塞生。","爲報花時少惆悵，此生終不負卿卿。"]', '["怜君無那是多情，枕上相看直到明。","日照綠窗人去住，鴉啼紅粉泪縱橫。","愁腸只向金閨斷，白髮應從玉塞生。","爲報花时少惆悵，此生終不負卿卿。"]', '诗', 'shi', '', NULL, '贈別營妓卿卿 油蔚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c530a5c-4785-44dd-8702-a7c2bb644f10', '巢燕', '巢燕', '82130d54-e70d-45d7-b71a-46ca1943e883', '唐', '["燕來巢我簷，我屋非高大。","所貴兒童善，保爾無殃禍。","莫巢孀婦家，孀婦怨孤坐。","妬爾長雙飛，打爾危巢破。"]', '["燕来巢我簷，我屋非高大。","所貴兒童善，保爾無殃禍。","莫巢孀婦家，孀婦怨孤坐。","妬爾长雙飞，打爾危巢破。"]', '诗', 'shi', '', NULL, '巢燕 胡玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd8476a2-6337-4d8b-a879-260811639ee2', '廬山桑落洲', '廬山桑落洲', '82130d54-e70d-45d7-b71a-46ca1943e883', '唐', '["莫問桑田事，但看桑落洲。","數家新住處，昔日大江流。","古岸崩欲盡，平沙長未休。","想應百年後，人世更悠悠。"]', '["莫问桑田事，但看桑落洲。","數家新住处，昔日大江流。","古岸崩欲尽，平沙长未休。","想應百年後，人世更悠悠。"]', '诗', 'shi', '', NULL, '廬山桑落洲 胡玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde4c549-84a9-4238-a1d4-db974bb54e6d', '石楠樹', '石楠樹', '82130d54-e70d-45d7-b71a-46ca1943e883', '唐', '["本自清江石上生，移栽此處稱閑情。","青雲士盡識珍木，白屋人多喚俗名。","重布綠陰滋蘚色，深藏好鳥引雛聲。","余今一日千迴看，每度看來眼益明。"]', '["本自清江石上生，移栽此处稱闲情。","青云士尽識珍木，白屋人多喚俗名。","重布綠陰滋蘚色，深藏好鸟引雛声。","余今一日千迴看，每度看来眼益明。"]', '诗', 'shi', '', NULL, '石楠樹 胡玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4c54bcd-4108-4ca9-9b33-b9c796b3dc8a', '句', '句', '82130d54-e70d-45d7-b71a-46ca1943e883', '唐', '["輪中別有物，光外更無空。"]', '["輪中別有物，光外更無空。"]', '诗', 'shi', '', NULL, '句 胡玢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63d1035-09c2-473d-b8e0-c43e976f601a', '酒胡子', '酒胡子', '00d2eaf8-44cc-464d-a032-ef60a903f83a', '唐', '["同心相遇思同歡，擎出酒胡當玉盤。","盤中臲卼不自定，四座清賓注意看。","可亦不在心，否亦不在面，徇客隨時自圓轉。","酒胡五藏屬他人，十分亦是無情勸。","爾不耕，亦不飢。","爾不蠶，亦有衣。","有眼不能分黼黻，有口不能明是非。","鼻何尖，眼何碧，儀形本非天地力。","雕鐫匠意苦多端，翠帽朱衫巧妝飾。","長安斗酒十千酤，劉伶平生爲酒徒。","劉伶虛向酒中死，不得酒池中拍浮。","酒胡一滴不入眼，空令酒胡名酒胡。"]', '["同心相遇思同歡，擎出酒胡當玉盤。","盤中臲卼不自定，四座清賓注意看。","可亦不在心，否亦不在面，徇客隨时自圓轉。","酒胡五藏屬他人，十分亦是無情勸。","爾不耕，亦不飢。","爾不蠶，亦有衣。","有眼不能分黼黻，有口不能明是非。","鼻何尖，眼何碧，儀形本非天地力。","雕鐫匠意苦多端，翠帽朱衫巧妝飾。","长安斗酒十千酤，劉伶平生爲酒徒。","劉伶虛向酒中死，不得酒池中拍浮。","酒胡一滴不入眼，空令酒胡名酒胡。"]', '诗', 'shi', '', NULL, '酒胡子 盧注 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47f5de23-d195-4308-8f41-b338c254a927', '西施', '西施', '00d2eaf8-44cc-464d-a032-ef60a903f83a', '唐', '["惆悵興亡繫綺羅，世人猶自選青娥。","越王解破夫差國，一箇西施已是多。"]', '["惆悵兴亡繫綺羅，世人猶自選青娥。","越王解破夫差国，一箇西施已是多。"]', '诗', 'shi', '', NULL, '西施 盧注 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5944a00-b312-43f8-94ce-f59c3b2ec15c', '題西施浣紗石', '題西施浣紗石', '105eb2fc-04f7-4247-a7b8-861ce7f42866', '唐', '["一朝入紫宮，萬古遺芳塵。","至今溪邊花，不敢嬌青春。"]', '["一朝入紫宮，万古遺芳塵。","至今溪邊花，不敢嬌青春。"]', '诗', 'shi', '', NULL, '題西施浣紗石 胡幽貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b35033b-44a4-4886-98c0-32a4ec016706', '歸四明', '归四明', '105eb2fc-04f7-4247-a7b8-861ce7f42866', '唐', '["海色連四明，仙舟去容易。","天籍豈輙問，不是卑朝士。"]', '["海色連四明，仙舟去容易。","天籍豈輙问，不是卑朝士。"]', '诗', 'shi', '', NULL, '歸四明 胡幽貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f9a3f44-57d4-4214-9c17-56325d206675', '送人游邵州', '送人游邵州', 'a0149d7d-8817-4c6d-b76c-0ea8294253d3', '唐', '["春江正渺渺，送別兩依依。","煙裏棹將遠，渡頭人未歸。","漁家侵疊浪，島樹挂殘暉。","況入湖湘路，那堪花亂飛。"]', '["春江正渺渺，送別兩依依。","煙裏棹將远，渡头人未归。","漁家侵叠浪，島樹挂殘暉。","況入湖湘路，那堪花亂飞。"]', '诗', 'shi', '', NULL, '送人游邵州 狄煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f2d4534-c99a-4639-8b0b-c02d34b56b4c', '題柳', '題柳', 'a0149d7d-8817-4c6d-b76c-0ea8294253d3', '唐', '["天南與天北，此處影婆娑。","翠色折不盡，離情生更多。","雨餘籠灞岸，煙暝夾隋河。","自有佳名在，秦松繼得麽。"]', '["天南與天北，此处影婆娑。","翠色折不尽，離情生更多。","雨餘籠灞岸，煙暝夾隋河。","自有佳名在，秦松繼得麽。"]', '诗', 'shi', '', NULL, '題柳 狄煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31fce595-d7f2-44dc-821f-f692a1a27d16', '詠南嶽徑松', '詠南嶽徑松', 'a0149d7d-8817-4c6d-b76c-0ea8294253d3', '唐', '["一陣雨聲歸嶽嶠，兩條寒色下瀟湘。","客吟晚景停孤櫂，僧踏清陰徹上方。"]', '["一陣雨声归嶽嶠，兩條寒色下瀟湘。","客吟晚景停孤櫂，僧踏清陰徹上方。"]', '诗', 'shi', '', NULL, '詠南嶽徑松 狄煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2249ab-f00c-4a51-8add-257c5e794e72', '句', '句', 'a0149d7d-8817-4c6d-b76c-0ea8294253d3', '唐', '["數點當秋霽，不知何處峰？更無聲接續，空有影相隨。"]', '["數点當秋霽，不知何处峰？更無声接續，空有影相隨。"]', '诗', 'shi', '', NULL, '句 狄煥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d74df0b-604b-45dc-802c-841be59f0112', '潯陽觀水', '潯陽观水', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["朝宗漢水接陽臺，唅呀填坑吼作雷。","莫見九江平穩去，還從三峽嶮巇來。","南經夢澤寬浮日，西出岷山劣泛杯。","直至滄溟涵貯盡，沈深不動浸昭回。"]', '["朝宗漢水接陽台，唅呀填坑吼作雷。","莫见九江平穩去，還從三峽嶮巇来。","南經梦澤寬浮日，西出岷山劣泛杯。","直至滄溟涵貯尽，沈深不动浸昭回。"]', '诗', 'shi', '', NULL, '潯陽觀水 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b55283-69b8-480c-8008-a762da10d4cc', '水', '水', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["方圓不定性空求，東注滄溟早晚休。","高截碧塘長耿耿，遠飛青嶂更悠悠。","瀟湘月浸千年色，夢澤煙含萬古愁。","別有嶺頭嗚咽處，爲君分作斷腸流。"]', '["方圓不定性空求，东注滄溟早晚休。","高截碧塘长耿耿，远飞青嶂更悠悠。","瀟湘月浸千年色，梦澤煙含万古愁。","別有嶺头嗚咽处，爲君分作斷腸流。"]', '诗', 'shi', '', NULL, '水 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb6bc82-a940-47dc-bb6a-8ad208454518', '松', '松', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["倚空高檻冷無塵，往事閑徵夢欲分。","翠色本宜霜後見，寒聲偏向月中聞。","啼猿想帶蒼山雨，歸鶴應和紫府雲。","莫向東園競桃李，春光還是不容君。"]', '["倚空高檻冷無塵，往事闲徵梦欲分。","翠色本宜霜後见，寒声偏向月中闻。","啼猿想带蒼山雨，归鹤應和紫府云。","莫向东园競桃李，春光還是不容君。"]', '诗', 'shi', '', NULL, '松 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a114e227-28f2-4877-b744-12cdb34cb7e6', '柳', '柳', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["雪盡青門弄影微，暖風遲日早鶯歸。","如憑細葉留春色，須把長條繫落暉。","彭澤有情還鬱鬱，隋堤無主自依依。","世間惹恨偏饒此，可是行人折贈稀。"]', '["雪尽青门弄影微，暖风遲日早鶯归。","如憑細葉留春色，須把长條繫落暉。","彭澤有情還鬱鬱，隋堤無主自依依。","世间惹恨偏饒此，可是行人折贈稀。"]', '诗', 'shi', '', NULL, '柳 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c457dc82-d65a-4575-af65-1a6ea5e72862', '竹', '竹', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["樹色連雲萬葉開，王孫不厭滿庭栽。","凌霜盡節無人見，終日虛心待鳳來。","誰許風流添興詠，自憐瀟灑出塵埃。","朱門處處多閑地，正好移陰覆翠苔。"]', '["樹色連云万葉开，王孫不厭满庭栽。","凌霜尽節無人见，終日虛心待鳳来。","誰許风流添兴詠，自怜瀟灑出塵埃。","朱门处处多闲地，正好移陰覆翠苔。"]', '诗', 'shi', '', NULL, '竹 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59dbad4-f4cd-47e4-a839-9d9597d5ab7a', '鵲', '鵲', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["纔見離巢羽翼開，盡能輕颺出塵埃。","人間樹好紛紛占，天上橋成草草回。","幾度送風臨玉戶，一時傳喜到妝臺。","若教顏色如霜雪，應與清平作瑞來。"]', '["纔见離巢羽翼开，尽能轻颺出塵埃。","人间樹好紛紛占，天上橋成草草回。","幾度送风臨玉戶，一时傳喜到妝台。","若教顏色如霜雪，應與清平作瑞来。"]', '诗', 'shi', '', NULL, '鵲 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4678e71d-2920-4548-a8ea-1cb759c445d3', '燈', '灯', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["分影由來恨不同，綠窗孤館兩何窮。","熒煌短焰長疑暗，零落殘花旋委空。","幾處隔簾愁夜雨，誰家當戶怯秋風。","莫言明滅無多重，曾比人生一世中。"]', '["分影由来恨不同，綠窗孤館兩何窮。","熒煌短焰长疑暗，零落殘花旋委空。","幾处隔簾愁夜雨，誰家當戶怯秋风。","莫言明滅無多重，曾比人生一世中。"]', '诗', 'shi', '', NULL, '燈 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('710f1b9a-9b92-44a9-90f9-4d0e238fcd2b', '句', '句', 'd75cde9a-58a5-4694-9884-276d9930536d', '唐', '["門掩落花人別後，窗含殘月酒醒時。"]', '["门掩落花人別後，窗含殘月酒醒时。"]', '诗', 'shi', '', NULL, '句 韓溉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b41e25f5-5a57-497f-a3a2-84bdfb9331f5', '春怨', '春怨', '95e79b95-f50d-444c-8d08-354e54d6e92c', '唐', '["打起黃鶯兒，莫教枝上啼。","啼時驚妾夢，不得到遼西。"]', '["打起黄鶯兒，莫教枝上啼。","啼时驚妾梦，不得到遼西。"]', '诗', 'shi', '', NULL, '春怨 金昌緒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d34867-5ad9-4787-8ebd-8fd03e6a0cc1', '放猨', '放猨', 'da8c0897-d46d-4a96-baca-db948dddc3f4', '唐', '["孤猨鎖檻歲年深，放出城南百丈林。","綠水任從聯臂飲，青山不用斷腸吟。"]', '["孤猨鎖檻歲年深，放出城南百丈林。","綠水任從聯臂饮，青山不用斷腸吟。"]', '诗', 'shi', '', NULL, '放猨 曾麻幾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3189af41-4de5-42ed-99ce-aa99ab2de0fa', '觀兄弟同夜成婚', '观兄弟同夜成婚', '2fff5339-7313-4526-af38-498daa96bf13', '唐', '["棠棣開雙萼，夭桃照兩花。","分庭含佩響，隔扇偶妝華。","迎風俱似雪，映綺共如霞。","今宵二神女，幷在一仙家。"]', '["棠棣开雙萼，夭桃照兩花。","分庭含佩响，隔扇偶妝华。","迎风俱似雪，映綺共如霞。","今宵二神女，幷在一仙家。"]', '诗', 'shi', '', NULL, '觀兄弟同夜成婚 鄭軌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f947de8c-92fe-4321-b627-721ffd429241', '夏彈琴', '夏彈琴', 'dbda1360-43a2-4000-a010-4d4bbae22f7e', '唐', '["碧山本岑寂，素琴何清幽。","彈爲風入松，崖谷颯已秋。","庭鶴舞白雪，泉魚躍洪流。","予欲娛世人，明月難暗投。","感歎未終曲，淚下不可收。","嗚呼鍾子期，零落歸荒丘。","死而若有知，魂兮從我游。"]', '["碧山本岑寂，素琴何清幽。","彈爲风入松，崖谷颯已秋。","庭鹤舞白雪，泉鱼躍洪流。","予欲娛世人，明月难暗投。","感歎未終曲，泪下不可收。","嗚呼鍾子期，零落归荒丘。","死而若有知，魂兮從我游。"]', '诗', 'shi', '', NULL, '夏彈琴 劉戩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e86e8bf4-f3a8-414e-94fc-007f80e4354e', '過函谷關', '過函谷关', '214e561c-ea56-4c2e-af8f-d32b8d1aae49', '唐', '["地險崤函北，途經分陝東。","逶迤衆山盡，荒涼古塞空。","河光流曉日，樹影散朝風。"]', '["地險崤函北，途經分陝东。","逶迤衆山尽，荒涼古塞空。","河光流晓日，樹影散朝风。"]', '诗', 'shi', '', NULL, '過函谷關 楊齊哲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b3c2f6-393c-4968-9b1e-c3d592592d9a', '傷死奴', '傷死奴', '47adfe8b-c454-4d9e-8027-ee108d8c2847', '唐', '["丹籍生涯淺，黃泉歸路深。","不及江陵樹，千秋長作林。"]', '["丹籍生涯淺，黄泉归路深。","不及江陵樹，千秋长作林。"]', '诗', 'shi', '', NULL, '傷死奴 劉夷道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cabf81a-c85e-4b1a-ab19-572d4d719d3f', '侍宴賦得起坐彈鳴琴二首 一', '侍宴賦得起坐彈鳴琴二首 一', '447378a3-e923-435c-a7e9-4b22df89184d', '唐', '["北林鵲夜飛，南軒月初進。","調弦發清徵，蕩心怯褊恡。","變作離鴻聲，還入思歸引。","長歎未終極，秋風飄素鬢。"]', '["北林鵲夜飞，南軒月初進。","調弦發清徵，蕩心怯褊恡。","变作離鴻声，還入思归引。","长歎未終極，秋风飄素鬢。"]', '诗', 'shi', '', NULL, '侍宴賦得起坐彈鳴琴二首 一 楊希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9801b4c-510e-45b1-ba22-ebf5090704e3', '侍宴賦得起坐彈鳴琴二首 二', '侍宴賦得起坐彈鳴琴二首 二', '447378a3-e923-435c-a7e9-4b22df89184d', '唐', '["絲傳園客意，曲奏楚妃情。","罕有知音者，空勞流水聲。"]', '["絲傳园客意，曲奏楚妃情。","罕有知音者，空勞流水声。"]', '诗', 'shi', '', NULL, '侍宴賦得起坐彈鳴琴二首 二 楊希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b84794e-f7ac-43fe-9356-82bb680bfb7c', '詠琴', '詠琴', '447378a3-e923-435c-a7e9-4b22df89184d', '唐', '["久擅龍門質，孤竦嶧陽名。","齊[娥]初發弄，趙女正調聲。","嘉客勿遽反，繁弦曲未成。"]', '["久擅龙门質，孤竦嶧陽名。","齊[娥]初發弄，趙女正調声。","嘉客勿遽反，繁弦曲未成。"]', '诗', 'shi', '', NULL, '詠琴 楊希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bc841e-5d20-49d2-a91b-61222eb792fb', '詠笙', '詠笙', '447378a3-e923-435c-a7e9-4b22df89184d', '唐', '["短長插鳳翼，洪細摹鸞音。","能令楚妃歎，復使荆王吟。","切切孤竹管，來應雲和琴。"]', '["短长插鳳翼，洪細摹鸾音。","能令楚妃歎，复使荆王吟。","切切孤竹管，来應云和琴。"]', '诗', 'shi', '', NULL, '詠笙 楊希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55300d72-52fa-43d6-8a05-fac0c6e4bf40', '詠舞', '詠舞', '447378a3-e923-435c-a7e9-4b22df89184d', '唐', '["二八如同雪，三春類早花。","分行向燭轉，一種逐風斜。"]', '["二八如同雪，三春類早花。","分行向燭轉，一種逐风斜。"]', '诗', 'shi', '', NULL, '詠舞 楊希道 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d09a638-dd14-44ac-ac17-ed416422bdca', '詠妓', '詠妓', '47310811-a036-4a08-82cd-9f92ad367f45', '唐', '["妖姬飾靚妝，窈窕出蘭房。","日照當軒影，風吹滿路香。","早時歌扇薄，今日舞衫長。","不應令曲誤，持此試周郎。"]', '["妖姬飾靚妝，窈窕出蘭房。","日照當軒影，风吹满路香。","早时歌扇薄，今日舞衫长。","不應令曲誤，持此試周郎。"]', '诗', 'shi', '', NULL, '詠妓 王勣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb34b393-79b9-4ebe-9760-86e6f6be66d1', '益州城西張超亭觀妓', '益州城西張超亭观妓', '47310811-a036-4a08-82cd-9f92ad367f45', '唐', '["落日明歌席，行雲逐舞人。","江前飛暮雨，梁上下輕塵。","冶服看疑畫，妝臺望似春。","高車勿遽返，長袖欲相親。"]', '["落日明歌席，行云逐舞人。","江前飞暮雨，梁上下轻塵。","冶服看疑畫，妝台望似春。","高车勿遽返，长袖欲相親。"]', '诗', 'shi', '', NULL, '益州城西張超亭觀妓 王勣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91474a0-27fa-4e20-b243-10acb4190cc7', '辛司法宅觀妓', '辛司法宅观妓', '47310811-a036-4a08-82cd-9f92ad367f45', '唐', '["南國佳人至，北堂羅薦開。","長裙隨鳳管，促柱送鸞杯。","雲光身後落，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '["南国佳人至，北堂羅薦开。","长裙隨鳳管，促柱送鸾杯。","云光身後落，雪態掌中回。","到愁金谷晚，不怪玉山頹。"]', '诗', 'shi', '', NULL, '辛司法宅觀妓 王勣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef029348-a389-4705-8903-d17de5734933', '秋池一枝蓮', '秋池一枝蓮', 'abe820c7-ec03-4c5f-85f9-6af42ecaf937', '唐', '["秋至皆零落，凌波獨吐紅。","托根方得所，未肯即隨風。"]', '["秋至皆零落，凌波独吐紅。","托根方得所，未肯即隨风。"]', '诗', 'shi', '', NULL, '秋池一枝蓮 郭恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9236e030-9820-49e0-b5be-aef19dcaf9b3', '婕妤怨', '婕妤怨', 'e5629d0c-063e-4d3d-8ad4-944b91eb4535', '唐', '["賤妾裁紈扇，初搖明月姿。","君王看舞席，坐起秋風時。","玉樹清御路，金陳翳垂絲。","昭陽無分理，愁寂任前期。"]', '["賤妾裁紈扇，初搖明月姿。","君王看舞席，坐起秋风时。","玉樹清御路，金陳翳垂絲。","昭陽無分理，愁寂任前期。"]', '诗', 'shi', '', NULL, '婕妤怨 張烜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76519323-4e3f-4442-b757-dce23dc21c5d', '長門怨', '长门怨', 'cc41cc33-6f5d-47ef-8938-d8a647d37487', '唐', '["長門落景盡，洞房秋月明。","玉階草露積，金屋網塵生。","妾妒今應改，君恩昔未平。","寄語臨邛客，何時作賦成。"]', '["长门落景尽，洞房秋月明。","玉階草露積，金屋網塵生。","妾妒今應改，君恩昔未平。","寄語臨邛客，何时作賦成。"]', '诗', 'shi', '', NULL, '長門怨 張修之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b0278c-d198-48e5-954b-fbc27eb7b526', '王昭君', '王昭君', '5d53dd79-ea92-4f70-8c91-ab719dffdd03', '唐', '["圖畫失天真，容華坐誤人。","君恩不可再，妾命在和親。","淚點關山月，衣銷邊塞塵。","一聞陽鳥至，思絕漢宮春。"]', '["圖畫失天真，容华坐誤人。","君恩不可再，妾命在和親。","泪点关山月，衣銷邊塞塵。","一闻陽鸟至，思絕漢宮春。"]', '诗', 'shi', '', NULL, '王昭君 梁獻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('605e8805-d2fa-41ff-a7e9-7140c78ef7ac', '芳樹', '芳樹', 'b9868478-a7fc-4499-9d1a-11d8a5aca5af', '唐', '["芳樹宜三月，曈曈豔綺年。","香交珠箔氣，陰占綠庭煙。","小葉風吹長，繁花露濯鮮。","遂令穠李兒，折取簪花鈿。"]', '["芳樹宜三月，曈曈豔綺年。","香交珠箔氣，陰占綠庭煙。","小葉风吹长，繁花露濯鲜。","遂令穠李兒，折取簪花鈿。"]', '诗', 'shi', '', NULL, '芳樹 符子珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54c32e1f-8b27-41d9-a0b5-e5f2582f9dba', '觀妓', '观妓', '1f6ff4ec-aaa7-4436-8d61-0d0be1b1b6c8', '唐', '["向晚小乘遊，朝來新上頭。","從來許長袖，未有客難留。"]', '["向晚小乘游，朝来新上头。","從来許长袖，未有客难留。"]', '诗', 'shi', '', NULL, '觀妓 李何 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062e81ae-95dc-4d3e-b9f9-ea23451c82c5', '邯鄲俠少年', '邯鄲俠少年', '14d1d9e2-74c3-4af9-92ce-fc89482cf1be', '唐', '["夜渡濁河津，衣中劒滿身。","兵符劫晉鄙，匕首刺秦人。","執事非無膽，高堂念有親。","昨緣秦苦趙，來往大梁頻。"]', '["夜渡濁河津，衣中劒满身。","兵符劫晉鄙，匕首刺秦人。","執事非無膽，高堂念有親。","昨緣秦苦趙，来往大梁頻。"]', '诗', 'shi', '', NULL, '邯鄲俠少年 鄭鏦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe17dde-0803-4a16-b0af-30048872d60a', '玉階怨', '玉階怨', '14d1d9e2-74c3-4af9-92ce-fc89482cf1be', '唐', '["昔日同飛燕，今朝似伯勞。","情深爭擲果，寵罷怨殘桃。","別殿春心斷，長門夜樹高。","雖能不自悔，誰見舊衣褒。"]', '["昔日同飞燕，今朝似伯勞。","情深爭擲果，寵罷怨殘桃。","別殿春心斷，长门夜樹高。","雖能不自悔，誰见旧衣褒。"]', '诗', 'shi', '', NULL, '玉階怨 鄭鏦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf75b4d-b436-4606-be25-38d14287b43f', '婕妤怨', '婕妤怨', '14d1d9e2-74c3-4af9-92ce-fc89482cf1be', '唐', '["南國承歡日，東方候曉時。","那能妒褒姒，祗愛笑唐兒。","寶葉隨雲髻，珠絲鍛履綦。","不知飛燕意，何事苦相疑。"]', '["南国承歡日，东方候晓时。","那能妒褒姒，祗愛笑唐兒。","寶葉隨云髻，珠絲鍛履綦。","不知飞燕意，何事苦相疑。"]', '诗', 'shi', '', NULL, '婕妤怨 鄭鏦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c85a7438-8498-42aa-a9f3-f0f89c1887b4', '入塞曲', '入塞曲', '14d1d9e2-74c3-4af9-92ce-fc89482cf1be', '唐', '["留滯邊庭久，歸思歲月賒。","黃雲同入塞，白首獨還家。","宛馬隨秦草，胡人問漢花。","還傷李都尉，獨自沒黃沙。"]', '["留滯邊庭久，归思歲月賒。","黄云同入塞，白首独還家。","宛马隨秦草，胡人问漢花。","還傷李都尉，独自沒黄沙。"]', '诗', 'shi', '', NULL, '入塞曲 鄭鏦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55655ff6-aef0-4f87-b017-157afe23cee6', '賞殘花', '賞殘花', 'b61d44e6-7f60-4a13-b346-1b5c2b68e4dd', '唐', '["零落多依草，芳香散著人。","低簷一枝在，猶占滿堂春。"]', '["零落多依草，芳香散著人。","低簷一枝在，猶占满堂春。"]', '诗', 'shi', '', NULL, '賞殘花 紇干著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569ed0de-4674-4941-bd23-c1a0634d26b8', '古仙詞', '古仙词', 'b61d44e6-7f60-4a13-b346-1b5c2b68e4dd', '唐', '["珠幡絳節曉霞中，漢武清齋待少翁。","不向人間戀春色，桃花自滿紫陽宮。"]', '["珠幡絳節晓霞中，漢武清斋待少翁。","不向人间戀春色，桃花自满紫陽宮。"]', '诗', 'shi', '', NULL, '古仙詞 紇干著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac2ecfc-6d6e-4a3c-a503-d23fac7c0ae2', '感春詞', '感春词', 'b61d44e6-7f60-4a13-b346-1b5c2b68e4dd', '唐', '["未得鳴珂謁漢宮，江頭寂寞向春風。","悲歌一曲心應醉，萬葉千花淚眼中。"]', '["未得鳴珂謁漢宮，江头寂寞向春风。","悲歌一曲心應醉，万葉千花泪眼中。"]', '诗', 'shi', '', NULL, '感春詞 紇干著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c47ef80-a127-446d-8ecb-31eaabcd34d0', '灞上', '灞上', 'b61d44e6-7f60-4a13-b346-1b5c2b68e4dd', '唐', '["鳴鞭晚日禁城東，渭水晴煙灞岸風。","都傍柳陰回首望，春天樓閣五雲中。"]', '["鳴鞭晚日禁城东，渭水晴煙灞岸风。","都傍柳陰回首望，春天楼閣五云中。"]', '诗', 'shi', '', NULL, '灞上 紇干著 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8004b06b-41b5-43aa-ba43-ce8e418407fe', '凌雲寺', '凌云寺', 'd316d705-614a-421f-be43-7d1a303ed6ea', '唐', '["古寺臨江間碧波，石梯深入白雲窠。","僧禪寂寂無人跡，滿地落花春又過。"]', '["古寺臨江间碧波，石梯深入白云窠。","僧禪寂寂無人跡，满地落花春又過。"]', '诗', 'shi', '', NULL, '凌雲寺 李習 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18575368-2853-4fc0-b1ee-8f98e9e0e42a', '鳳棲怨', '鳳棲怨', '07eef91d-7fa0-446e-8152-1d3c33836793', '唐', '["佳人名莫愁，珠箔上花鉤。","清鏡鴛鴦匣，新妝翡翠樓。","擣衣明月夜，吹管白雲秋。","惟恨金吾子，年年向隴頭。"]', '["佳人名莫愁，珠箔上花鉤。","清镜鴛鴦匣，新妝翡翠楼。","擣衣明月夜，吹管白云秋。","惟恨金吾子，年年向隴头。"]', '诗', 'shi', '', NULL, '鳳棲怨 顏舒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5475f18-667a-4f89-a97a-35b1a4550ac8', '春女怨', '春女怨', '1a2f6e97-a10a-4d1e-a46f-415e07d15dc3', '唐', '["獨坐紗窗刺繡遲，紫荆花下囀黃鸝。","欲知無限傷春意，盡在停針不語時。"]', '["独坐紗窗刺繡遲，紫荆花下囀黄鸝。","欲知無限傷春意，尽在停針不語时。"]', '诗', 'shi', '', NULL, '春女怨 朱絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78cbde2-edf3-4166-9aa7-4e1115b9cccc', '失題', '失題', '025022cd-ba33-4ebc-9ecf-26f53a73cf34', '唐', '["雙燕今朝至，何時發海濱？窺簷向人語，如道故鄉春。"]', '["雙燕今朝至，何时發海濱？窺簷向人語，如道故乡春。"]', '诗', 'shi', '', NULL, '失題 徐璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a414387-9a5a-4e97-9d7e-fd0d73ee5bcd', '催妝', '催妝', '2ad7d821-fb1b-4454-b4ff-21377ffba07c', '唐', '["傳聞燭下調紅粉，明鏡臺前別作春。","不須面上渾妝却，留著雙眉待畫人。"]', '["傳闻燭下調紅粉，明镜台前別作春。","不須面上渾妝却，留著雙眉待畫人。"]', '诗', 'shi', '', NULL, '催妝 徐安期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58da5236-5f49-43b6-a97f-393c061eab53', '隔壁聞奏伎', '隔壁闻奏伎', '62f630e9-e1a7-4cc2-930d-5bab4af7a957', '唐', '["徒聞管弦切，不見舞腰回。","賴有歌梁合，塵飛一半來。"]', '["徒闻管弦切，不见舞腰回。","賴有歌梁合，塵飞一半来。"]', '诗', 'shi', '', NULL, '隔壁聞奏伎 裴延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2773dc92-2757-46df-8715-8ba1565f79a6', '詠翦花', '詠翦花', '62f630e9-e1a7-4cc2-930d-5bab4af7a957', '唐', '["花寒未聚蝶，色豔已驚人。","懸知陌上柳，應妒手中春。"]', '["花寒未聚蝶，色豔已驚人。","懸知陌上柳，應妒手中春。"]', '诗', 'shi', '', NULL, '詠翦花 裴延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78be780-b2a1-4de6-b512-a72a355d536b', '歎美人照鏡', '歎美人照镜', 'df2ce956-4a4b-483b-918d-658dd87e64f5', '唐', '["插花枝共動，含笑靨俱生。","衫分兩處色，釧響一邊聲。","就中還妒影，恐奪可憐名。"]', '["插花枝共动，含笑靨俱生。","衫分兩处色，釧响一邊声。","就中還妒影，恐奪可怜名。"]', '诗', 'shi', '', NULL, '歎美人照鏡 陳述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa43bc94-52d6-4a76-90cd-dd34f0cf5b1f', '開緘怨', '开緘怨', '082df5de-50ee-4eaa-8019-83be2a72061d', '唐', '["夫婿邊庭久，幽閨恨幾重。","玉琴知別日，金鏡識愁容。","懶寄雲中服，慵開海上封。","年年得衣慣，且試莫裁縫。"]', '["夫婿邊庭久，幽閨恨幾重。","玉琴知別日，金镜識愁容。","懶寄云中服，慵开海上封。","年年得衣慣，且試莫裁縫。"]', '诗', 'shi', '', NULL, '開緘怨 朱琳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae5a4c42-cfac-4077-9ce9-cf56025e183d', '雜言', '杂言', 'c0b38740-8c8f-4377-b59a-625898ca2a4d', '唐', '["天不與人言，禍福能自至。","水火雖活人，暫不得即死。","蹈之焚斯須，憑之溺容易。","水火與禍福，豈有先言耳。"]', '["天不與人言，禍福能自至。","水火雖活人，暫不得即死。","蹈之焚斯須，憑之溺容易。","水火與禍福，豈有先言耳。"]', '诗', 'shi', '', NULL, '雜言 謝陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ded700-11dd-40e4-b093-bee065c7ed9c', '書事', '书事', '5cef1c6b-1bd0-4b17-9cf3-d61aa4959518', '唐', '["果決生涯向路中，西投知己話從容。","雲遮劍閣三千里，水隔瞿塘十二峰。","闊步文翁坊裏月，閑尋杜老宅邊松。","到頭須卜林泉隱，自愧無能繼臥龍。"]', '["果決生涯向路中，西投知己話從容。","云遮劍閣三千里，水隔瞿塘十二峰。","闊步文翁坊裏月，闲尋杜老宅邊松。","到头須卜林泉隐，自愧無能繼臥龙。"]', '诗', 'shi', '', NULL, '書事 何贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1dce452-b83c-40fc-9e05-815c7eafbbd0', '鴈塔', '鴈塔', 'd7c33e7c-5839-4294-ba77-d539bf8cae65', '唐', '["崢嶸澈倒景，刻峭俯無地。","勇進攀有緣，即嶮恐迷墜。","窅然喪五蘊，蠢爾懷萬類。","實際罔他尋，波羅必可致。","南山繚上苑，祇樹連巖翠。","北斗臨帝城，扶宮切太清。","餐和裨日用，味道懿天明。","綠野冷風浹，紫微佳氣晶。","馴禽演法要，忍草藉經行。","本願從茲適，方知物世輕。"]', '["崢嶸澈倒景，刻峭俯無地。","勇進攀有緣，即嶮恐迷墜。","窅然喪五蘊，蠢爾懷万類。","實際罔他尋，波羅必可致。","南山繚上苑，祇樹連巖翠。","北斗臨帝城，扶宮切太清。","餐和裨日用，味道懿天明。","綠野冷风浹，紫微佳氣晶。","馴禽演法要，忍草藉經行。","本願從茲適，方知物世轻。"]', '诗', 'shi', '', NULL, '鴈塔 解彥融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524ecb86-26b8-44db-9100-a7a8d2a9bcbe', '昭君怨', '昭君怨', 'f1f8a90f-cd4f-4207-99f4-d45a2559bd08', '唐', '["新年猶尚小，那堪遠聘秦。","裾衫沾馬汗，眉黛染胡塵。","舉眼無相識，路逢皆異人。","唯有梅將李，猶帶故鄉春。"]', '["新年猶尚小，那堪远聘秦。","裾衫沾马汗，眉黛染胡塵。","舉眼無相識，路逢皆異人。","唯有梅將李，猶带故乡春。"]', '诗', 'shi', '', NULL, '昭君怨 董初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9826a309-8ef9-42b0-8903-d5cda7453f57', '南山', '南山', '22b42eb8-c5f3-449a-b69c-f2b28c8d1e60', '唐', '["湖北雨初晴，湖南山盡見。","嵒嵒石帆影，如得海風便。","仙穴茅山峰，彩雲時一見。","邀君共探此，異籙殘幾卷。"]', '["湖北雨初晴，湖南山尽见。","嵒嵒石帆影，如得海风便。","仙穴茅山峰，彩云时一见。","邀君共探此，異籙殘幾卷。"]', '诗', 'shi', '', NULL, '南山 賀朝清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb7a86a-2c1d-410e-9a1f-20c14a758b90', '賦得遊人久不歸', '賦得游人久不归', '22b42eb8-c5f3-449a-b69c-f2b28c8d1e60', '唐', '["鄉關眇天末，引領悵懷歸。","羈旅久淫滯，物色屢芳菲。","稍覺私意盡，行看鬔鬢稀。","如何千里外，佇立霑裳衣。"]', '["乡关眇天末，引領悵懷归。","羈旅久淫滯，物色屢芳菲。","稍覺私意尽，行看鬔鬢稀。","如何千里外，佇立霑裳衣。"]', '诗', 'shi', '', NULL, '賦得遊人久不歸 賀朝清 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec437fe-6347-4989-b53e-1065d2b25cd6', '白紵辭 一', '白紵辞 一', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["玉纓翠珮雜輕羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清聲褭雲思繁多，凝笳哀琴時相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐聽終曲，墜葉飄花難再復。"]', '["玉纓翠珮杂轻羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清声褭云思繁多，凝笳哀琴时相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐听終曲，墜葉飄花难再复。"]', '诗', 'shi', '', NULL, '白紵辭 一 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f0b9071-c9b9-487c-bf97-fc4d89de649a', '白紵辭 二', '白紵辞 二', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["躡珠履，步瓊筵。","輕身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼風蕭蕭漏水急。","月華泛溢紅蓮濕，牽裙攬帶翻成泣。"]', '["躡珠履，步瓊筵。","轻身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼风蕭蕭漏水急。","月华泛溢紅蓮濕，牽裙攬带翻成泣。"]', '诗', 'shi', '', NULL, '白紵辭 二 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288df8f2-e0e3-4ccb-8a75-e0d2e317ea7a', '還渭南感舊二首 一', '還渭南感旧二首 一', 'a14cc2a3-9f8d-4313-b96e-6d0c9e373eea', '唐', '["寢室悲長簟，妝樓泣鏡臺。","獨悲桃李節，不共一時開。","魂兮若有感，髣髴夢中來。"]', '["寢室悲长簟，妝楼泣镜台。","独悲桃李節，不共一时开。","魂兮若有感，髣髴梦中来。"]', '诗', 'shi', '', NULL, '還渭南感舊二首 一 唐暄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c01b8b-02df-44bd-b331-e48fbe26d807', '還渭南感舊二首 二', '還渭南感旧二首 二', 'a14cc2a3-9f8d-4313-b96e-6d0c9e373eea', '唐', '["常時華室靜，笑語度更籌。","恍惚人事改，冥漠委荒丘。","陽原歎薤露，陰壑悼藏舟。","清夜妝臺月，空想畫眉愁。"]', '["常时华室静，笑語度更籌。","恍惚人事改，冥漠委荒丘。","陽原歎薤露，陰壑悼藏舟。","清夜妝台月，空想畫眉愁。"]', '诗', 'shi', '', NULL, '還渭南感舊二首 二 唐暄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd6c4a3-10f0-4cb4-9d6f-8b69778997cb', '贈亡妻張氏', '贈亡妻張氏', 'a14cc2a3-9f8d-4313-b96e-6d0c9e373eea', '唐', '["嶧陽桐半死，延津劒一沈。","如何宿昔內，空負百年心。"]', '["嶧陽桐半死，延津劒一沈。","如何宿昔內，空負百年心。"]', '诗', 'shi', '', NULL, '贈亡妻張氏 唐暄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0500c6f9-6432-4bd8-910e-052d1ab7884b', '題司空山觀', '題司空山观', 'ac6128ec-2204-4926-ab5a-bd2e57704d10', '唐', '["梁代真人上紫微，水盤山脚五雲飛。","松杉老盡無消息，猶得千年一度歸。"]', '["梁代真人上紫微，水盤山脚五云飞。","松杉老尽無消息，猶得千年一度归。"]', '诗', 'shi', '', NULL, '題司空山觀 李韶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6c9e13-cd8e-49c5-b353-3ff2260a9ace', '戲題盱眙壁', '戲題盱眙壁', '07ea8fc4-3ef2-43e0-be02-3c6ca5544d7b', '唐', '["豈肯閑尋竹徑行，却嫌絲管好蛙聲。","自從煮鶴燒琴後，背却青山臥月明。"]', '["豈肯闲尋竹徑行，却嫌絲管好蛙声。","自從煮鹤燒琴後，背却青山臥月明。"]', '诗', 'shi', '', NULL, '戲題盱眙壁 韋鵬翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40ba8774-1f69-4ad2-80eb-31f7255d3242', '題楊少卿書後', '題楊少卿书後', 'faf1b088-9c1f-424c-b2ac-7f81d32374ab', '唐', '["端溪石硯宣城管，王屋松煙紫兔毫。","更得孤卿老書札，人間無此五般高。"]', '["端溪石硯宣城管，王屋松煙紫兔毫。","更得孤卿老书札，人间無此五般高。"]', '诗', 'shi', '', NULL, '題楊少卿書後 安鴻漸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84834cee-75e6-406e-a652-c7d08a2d093d', '自紫陽觀至華陽洞宿侯尊師草堂簡同遊', '自紫陽观至华陽洞宿侯尊師草堂簡同游', 'c39457ba-980d-4b0d-b269-f1e625131476', '唐', '["石林媚煙景，句曲盤江甸。","南向佳氣濃，峰峰遙隱見。","漸臨華陽口，微路入葱蒨。","七曜懸洞宮，五雲抱山殿。","銀函意誰發，金液徒堪薦。","千載桃花春，秦人深不見。","東溪喜相遇，貞白如會面。","青鳥來去閑，紅霞朝夕變。","一從化真骨，萬里乘飛電。","蘿月延步虛，松花醉閑宴。","幽人即長往，茂宰應交戰。","明發歸琴堂，知君嬾爲縣。"]', '["石林媚煙景，句曲盤江甸。","南向佳氣濃，峰峰遙隐见。","漸臨华陽口，微路入葱蒨。","七曜懸洞宮，五云抱山殿。","銀函意誰發，金液徒堪薦。","千載桃花春，秦人深不见。","东溪喜相遇，貞白如會面。","青鸟来去闲，紅霞朝夕变。","一從化真骨，万里乘飞電。","蘿月延步虛，松花醉闲宴。","幽人即长往，茂宰應交戰。","明發归琴堂，知君嬾爲縣。"]', '诗', 'shi', '', NULL, '自紫陽觀至華陽洞宿侯尊師草堂簡同遊 李延陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a54f389-251e-4085-8cbd-66c288c60d73', '題鍾雅青紗枕', '題鍾雅青紗枕', 'febe445d-a3a4-4931-99aa-4f3316980e94', '唐', '["陰香裝豔入青紗，還與欹眠好事家。","夢裏却成山色雨，沈山不敢鬬青華。"]', '["陰香裝豔入青紗，還與欹眠好事家。","梦裏却成山色雨，沈山不敢鬬青华。"]', '诗', 'shi', '', NULL, '題鍾雅青紗枕 秦尚運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339f4fcf-62ee-4505-b608-b75a44161be9', '題搔口', '題搔口', '9acc5688-e2e1-4ca8-aefe-97ccb850df55', '唐', '["嘗聞燒尾便拏空，只過天門更一重。","大禹未生門未鑿，可能天下總無龍。"]', '["嘗闻燒尾便拏空，只過天门更一重。","大禹未生门未鑿，可能天下總無龙。"]', '诗', 'shi', '', NULL, '題搔口 張仲謀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b29f012-6843-41d0-a61f-f6daa3d57995', '山寺見楊少卿書壁因題其尾', '山寺见楊少卿书壁因題其尾', 'e08e9424-3251-46d0-8742-7fffc1622dd9', '唐', '["少卿真跡滿僧居，祗恐鍾王也不如。","爲報遠公須愛惜，此書書後更無書。"]', '["少卿真跡满僧居，祗恐鍾王也不如。","爲報远公須愛惜，此书书後更無书。"]', '诗', 'shi', '', NULL, '山寺見楊少卿書壁因題其尾 馮少吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac4e8c5-8608-40a8-9315-c5296dbbfa79', '經杜甫舊宅', '經杜甫旧宅', 'ab808012-52ab-4288-85d6-1f289f1352ae', '唐', '["浣花溪裏花多處，爲憶先生在蜀時。","萬古只應留舊宅，千金無復換新詩。","沙棚水檻鷗飛盡，樹壓村橋馬過時。","山月不知人事變，夜來江上與誰期。"]', '["浣花溪裏花多处，爲憶先生在蜀时。","万古只應留旧宅，千金無复換新诗。","沙棚水檻鷗飞尽，樹壓村橋马過时。","山月不知人事变，夜来江上與誰期。"]', '诗', 'shi', '', NULL, '經杜甫舊宅 殷陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ab266d-3eaa-4c37-939a-8f2ea02adf57', '行縣至浮查寺', '行縣至浮查寺', '908d9b86-ad42-4e8c-a5a5-d8be97c47c8a', '唐', '["二十年前此布衣，鹿鳴西上虎符歸。","行時賓從光前事，到處松杉長舊圍。","野老競遮官道拜，沙鷗遙避隼旟飛。","春風一宿琉璃地，自有泉聲愜素機。"]', '["二十年前此布衣，鹿鳴西上虎符归。","行时賓從光前事，到处松杉长旧圍。","野老競遮官道拜，沙鷗遙避隼旟飞。","春风一宿琉璃地，自有泉声愜素機。"]', '诗', 'shi', '', NULL, '行縣至浮查寺 羅炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2308f16-aec3-4bd5-9bcd-24e9ebcd80e4', '敕和元相公家園即事寄王相公', '敕和元相公家园即事寄王相公', 'd62ca98b-3d08-4467-a576-67017862b9f9', '唐', '["共列中台貴，能齊物外心。","迴車青閣晚，解帶碧芳深。","夜水隨畦入，晴花度竹尋。","題詩更相應，一字重千金。"]', '["共列中台貴，能齊物外心。","迴车青閣晚，解带碧芳深。","夜水隨畦入，晴花度竹尋。","題诗更相應，一字重千金。"]', '诗', 'shi', '', NULL, '敕和元相公家園即事寄王相公 韓雄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48d44c3-feb5-40c8-a856-05f5c027547a', '仲秋太常寺觀公輅車拜陵', '仲秋太常寺观公輅车拜陵', '75f14bff-a236-42d8-b539-bebd41fb7490', '唐', '["南宮初開律，金風已戒涼。","拜陵將展敬，車輅儼成行。","士庶觀祠禮，公卿習舊章。","郊原佳氣引，園寢瑞煙長。","鹵簿辭丹闕，威儀列太常。","聖心何所寄，惟德在無忘。"]', '["南宮初开律，金风已戒涼。","拜陵將展敬，车輅儼成行。","士庶观祠禮，公卿習旧章。","郊原佳氣引，园寢瑞煙长。","鹵簿辞丹闕，威儀列太常。","聖心何所寄，惟德在無忘。"]', '诗', 'shi', '', NULL, '仲秋太常寺觀公輅車拜陵 苗仲方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9dc403a-a474-4498-a7b8-af589e2163fd', '尋易尊師不遇', '尋易尊師不遇', 'f9a67038-4019-447c-8a26-696467c592c3', '唐', '["爛熳紅霞光照衣，苔封白石路微微。","華陽洞裏何人在，落盡松花不見歸。"]', '["爛熳紅霞光照衣，苔封白石路微微。","华陽洞裏何人在，落尽松花不见归。"]', '诗', 'shi', '', NULL, '尋易尊師不遇 陳嶰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb78251-4368-4537-ad9b-973d8f676fb6', '早過棃嶺喜雪書情呈崔判官', '早過棃嶺喜雪书情呈崔判官', 'fbd728aa-f1b0-42d1-8e0a-b15c1de2e2f5', '唐', '["度嶺逢朝雪，行看馬跡深。","輕標南國瑞，寒慰北人心。","皎潔停丹嶂，飄颻映綠林。","共君歌樂土，無作白頭吟。"]', '["度嶺逢朝雪，行看马跡深。","轻標南国瑞，寒慰北人心。","皎潔停丹嶂，飄颻映綠林。","共君歌乐土，無作白头吟。"]', '诗', 'shi', '', NULL, '早過棃嶺喜雪書情呈崔判官 張起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3e609e-e7fb-4dc9-84f2-fdfbbf8faf9b', '春情', '春情', 'fbd728aa-f1b0-42d1-8e0a-b15c1de2e2f5', '唐', '["畫閣餘寒在，新年舊燕歸。","梅花猶帶雪，未得試春衣。"]', '["畫閣餘寒在，新年旧燕归。","梅花猶带雪，未得試春衣。"]', '诗', 'shi', '', NULL, '春情 張起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2275179c-519b-44ea-b7fd-6b9c85b7cb14', '贈竇蔡二記室入蜀', '贈竇蔡二記室入蜀', 'b6b5b372-8448-4f7a-8ad6-6716ac6255fd', '唐', '["崑山積良寶，大廈構衆材。","馬卿委官去，鄒子背淮來。","風流信多美，朝夕豫平臺。","逸翮獨不羣，清才復遒上。","六輔昔推名，二江今振響。","英華雖外發，磨琢終內朗。","四海奮羽儀，清風久播馳。","沈鬱林難廁，青山翻易阻。","迴首望煙霞，誰知慕儔侶。","飄然不繫舟，爲情自可求。","若奉西園夜，浩想北園愁。","無因逐萍藻，從爾泛清流。"]', '["崑山積良寶，大廈構衆材。","马卿委官去，鄒子背淮来。","风流信多美，朝夕豫平台。","逸翮独不羣，清才复遒上。","六輔昔推名，二江今振响。","英华雖外發，磨琢終內朗。","四海奮羽儀，清风久播驰。","沈鬱林难廁，青山翻易阻。","迴首望煙霞，誰知慕儔侶。","飄然不繫舟，爲情自可求。","若奉西园夜，浩想北园愁。","無因逐萍藻，從爾泛清流。"]', '诗', 'shi', '', NULL, '贈竇蔡二記室入蜀 陳政 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06159912-0e2d-44da-bd3f-90e42153c795', '採菊', '採菊', '98987da3-b917-448f-9952-a5a26a445ae6', '唐', '["簇簇竟相鮮，一枝開幾番。","味甘資麴{艹/糪}，香好勝蘭蓀。","古道風搖遠，荒籬露壓繁。","盈筐時採得，服餌近知門。"]', '["簇簇竟相鲜，一枝开幾番。","味甘資麴{艹/糪}，香好勝蘭蓀。","古道风搖远，荒籬露壓繁。","盈筐时採得，服餌近知门。"]', '诗', 'shi', '', NULL, '採菊 李建業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a0813e-d591-41d7-957f-e04ad2db810f', '水精環', '水精环', 'b318340a-8853-471a-9067-4a611f4ff89b', '唐', '["王室符長慶，環中得水精。","任圓循不極，見素質仍貞。","信是天然瑞，非因樸斲成。","無瑕勝玉美，至潔過冰清。","未肯齊珉價，寧同雜佩聲。","能銜任黃雀，亦欲應時明。"]', '["王室符长慶，环中得水精。","任圓循不極，见素質仍貞。","信是天然瑞，非因樸斲成。","無瑕勝玉美，至潔過冰清。","未肯齊珉價，寧同杂佩声。","能銜任黄雀，亦欲應时明。"]', '诗', 'shi', '', NULL, '水精環 羅維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db641eb5-3dd5-44ae-9688-c0eb005da71a', '看牡丹', '看牡丹', 'b5289aaa-49ee-42a2-8d13-554aa475ff6d', '唐', '["擁毳對芳叢，由來趣不同。","髮從今日白，花是去年紅。","豔色隨朝露，馨香逐晚風。","何須待零落，然後始知空。"]', '["擁毳对芳叢，由来趣不同。","髮從今日白，花是去年紅。","豔色隨朝露，馨香逐晚风。","何須待零落，然後始知空。"]', '诗', 'shi', '', NULL, '看牡丹 殷益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95358367-9762-480e-8cf6-f0cd0cad1dee', '賦得垣衣', '賦得垣衣', '0c7e8da3-b3ac-4587-ae43-cd025441b5bd', '唐', '["漠漠復霏霏，爲君垣上衣。","昭陽輦下草，應笑此生非。","掩藹青春去，蒼茫白露稀。","猶勝萍逐水，流浪不相依。"]', '["漠漠复霏霏，爲君垣上衣。","昭陽輦下草，應笑此生非。","掩藹青春去，蒼茫白露稀。","猶勝萍逐水，流浪不相依。"]', '诗', 'shi', '', NULL, '賦得垣衣 李得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d245633-9131-4afa-b96e-a23b0d9189cf', '冬晚對雪憶胡處士', '冬晚对雪憶胡处士', '7cd82895-d713-4074-91d1-5fc3b3fb4859', '唐', '["寒更傳唱晚，清鏡覽衰顏。","隔牖風驚竹，開簾雪滿山。","灑空深巷靜，積素廣庭閑。","借問袁安舍，翛然尚閉關。"]', '["寒更傳唱晚，清镜覽衰顏。","隔牖风驚竹，开簾雪满山。","灑空深巷静，積素廣庭闲。","借问袁安舍，翛然尚閉关。"]', '诗', 'shi', '', NULL, '冬晚對雪憶胡處士 王邵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e326e353-777c-4656-8752-c14f3cf1309d', '池上', '池上', 'baa1f229-5b84-41b9-8ac2-a3003299831e', '唐', '["荷葉罩芙蓉，圓青映嫩紅。","佳人南陌上，翠蓋立春風。"]', '["荷葉罩芙蓉，圓青映嫩紅。","佳人南陌上，翠蓋立春风。"]', '诗', 'shi', '', NULL, '池上 曹脩古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c323f45-2326-462c-9b22-88e6a8e34b61', '對趙穎歌', '对趙穎歌', 'a2592a3b-d343-4edf-8160-56336972d6ab', '唐', '["人間幾日變桑田，誰識神仙洞裏天。","短促雖知有殊異，且須歡醉在生前。"]', '["人间幾日变桑田，誰識神仙洞裏天。","短促雖知有殊異，且須歡醉在生前。"]', '诗', 'shi', '', NULL, '對趙穎歌 朱子真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6078f45d-2a0b-4386-b2e1-99188da142cc', '賦百舌鳥', '賦百舌鸟', '44ca4964-a46b-4423-912d-16dacf2d03eb', '唐', '["此禽輕巧少同倫，我聽長疑舌滿身。","星未沒河先報曉，柳猶粘雪便迎春。","頻嫌海燕巢難定，却訝林鶯語不真。","莫倚清風更多事，玉樓還有晏眠人。"]', '["此禽轻巧少同倫，我听长疑舌满身。","星未沒河先報晓，柳猶粘雪便迎春。","頻嫌海燕巢难定，却訝林鶯語不真。","莫倚清风更多事，玉楼還有晏眠人。"]', '诗', 'shi', '', NULL, '賦百舌鳥 嚴郭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c490656-abbe-416a-89f8-9453bf58e72d', '孤雁', '孤雁', '1b75d02d-5578-4e6b-97f6-de8904d48e6e', '唐', '["隻影翩翩下碧湘，傍池鴛鷺宿銀塘。","雖逢夜雨迷深浦，終向晴天著舊行。","憶伴幾回思片月，蛻翎多爲繫繁霜。","江南塞北俱關念，兩地飛歸是故鄉。"]', '["隻影翩翩下碧湘，傍池鴛鷺宿銀塘。","雖逢夜雨迷深浦，終向晴天著旧行。","憶伴幾回思片月，蛻翎多爲繫繁霜。","江南塞北俱关念，兩地飞归是故乡。"]', '诗', 'shi', '', NULL, '孤雁 張子明 shi');
